def P(c=0, e=0):
    if c==0: return {}
    return {e: Fr(c)}
def padd(a,b):
    r=defaultdict(Fr); r.update(a)
    for e,c in b.items(): r[e]+=c
    return {e:c for e,c in r.items() if c}
def pmul(a,b):
    r=defaultdict(Fr)
    for e1,c1 in a.items():
        for e2,c2 in b.items(): r[e1+e2]+=c1*c2
    return {e:c for e,c in r.items() if c}
def pneg(a): return {e:-c for e,c in a.items()}
def psub(a,b): return padd(a,pneg(b))
def ppow(a,n):
    r=P(1)
    if n<0:
        a= { -e: Fr(1)/c for e,c in a.items() } if len(a)==1 else None
        assert a is not None, "invert only monomials"
        n=-n
    for _ in range(n): r=pmul(r,a)
    return r
def pinv_mono(a):
    assert len(a)==1
    e,c=next(iter(a.items()))
    return {-e: Fr(1)/c}
q = P(1,2)   # q = s''^2
qi = P(1,-2)
ZERO=P(0); ONE=P(1)

def peq(a,b): return psub(a,b)==ZERO
def pstr(a):
    if not a: return "0"
    parts=[]
    for e in sorted(a):
        c=a[e]
        if e==0: parts.append(str(c))
        else: parts.append(f"{c}*s''^{e}")
    return "+".join(parts)

# Symbols: M00,M01,M10,M11 (arcs copy1: a,b,c,d rows i, cols j) and N00,N01,N10,N11 (dual), L (grouplike), Li
# Word = tuple of symbol names. Polynomial: dict word -> Laurent poly coeff.
