        self.rules=[]  # list of (lhs_word, rhs_poly) reductions, applied when adjacent pattern found
        self.cache={}
    def add_rule(self, lhs, rhs):
        self.rules.append((tuple(lhs), rhs))
    def reduce_poly(self, poly):
        changed=True
        poly=dict(poly)
        while changed:
            changed=False
            for w,c in list(poly.items()):
                rw=self.reduce_word_once(w)
                if rw is not None:
                    del poly[w]
                    for w2,c2 in rw.items():
                        poly[w2]=poly.get(w2,ZERO) and padd(poly.get(w2,ZERO), pmul(c,c2)) or pmul(c,c2)
                    # careful: above line buggy; redo cleanly below
                    changed=True
                    break
        return poly

def make_reduce(rules):
    def reduce_poly(poly):
        poly=dict(poly)
        changed=True
        while changed:
            changed=False
            for w,c in list(poly.items()):
                new=None
                # find first position where a rule applies
                for i in range(len(w)):
                    for lhs,rhs in rules:
                        L=len(lhs)
                        if w[i:i+L]==lhs:
                            new=(i,lhs,rhs); break
                    if new: break
                if new:
                    i,lhs,rhs=new
                    del poly[w]
                    pre=w[:i]; post=w[i+len(lhs):]
                    for w2,c2 in rhs.items():
                        nw=pre+w2+post
                        poly[nw]=padd(poly.get(nw,ZERO), pmul(c,c2))
                    changed=True
                    break
        return poly
    return reduce_poly

# Build F_q[SL2] relations for M copy: a=M00,b=M01,c=M10,d=M11
# qa b = q b a? Convention: xy = q yx for "x before y":
#  M00 M01 = q M01 M00 ; M00 M10 = q M10 M00 ; M01 M11 = q M11 M01 ; M10 M11 = q M11 M10
#  M01 M10 = M10 M01 ; M00 M11 - M11 M00 = (q - qi) M01 M10
M=['"'M00','M01','M10','M11']; N=['N00','N01','N10','N11']
def mrules(reverse=False):
    qq = qi if reverse else q
    qqi = q if reverse else qi
    r=[]
    r.append((('M01','M00'), {('M00','M01'): qqi}))
    r.append((('M10','M00'), {('M00','M10'): qqi}))
    r.append((('M11','M01'), {('M01','M11'): qqi}))
    r.append((('M11','M10'), {('M10','M11'): qqi}))
    r.append((('M10','M01'), {('M01','M10'): ONE}))
