\\[
\\kappa_1=\\la F_r,E_rK_r\\ra=\\theta q,\\qquad
\\kappa_2=\\la K_r"'^{-1}F_r,E_r'"\\ra=\\theta,\\qquad
\\kappa_3=\\la K_r"'^{-1}F_r,E_rK_r'"\\ra=\\theta q"'^?
