\\begin{proof}
"'$'"\\tau"'$ preserves '"\\eqref{KEF}--\\eqref{Serre} and the pairing (P), hence
extends to an anti-automorphism of the double intertwining (SK).
\\end{proof}

\\begin{lemma}[Model commutators]\\label{lem:model}
Let "'$x$ lie in the copy-$2$ subalgebra $'"\\la c(\\cdot,\\cdot)\\ra"'$ and $y$
in copy $1$.  Then, inside $D$:
'"\\begin{align}
\\hK_i"'^{-1}E_r&=q''^{-(a(i,r)-a(i,r+1))}E_r'"\\hK_i"'^{-1},'"\\label{m1}\\\\
\\hK_i"'^{-1}'"\\hK_j&=q"'^{a(i,j)-a(j,i)}'"\\hK_j\\hK_i"'^{-1}='"\\hK_j\\hK_i"'^{-1}
 '"\\ \\ (\\text{since }a(i,j)=a(j,i)),\\label{m2}\\\\
(\\hK_r"'^{-1}F_r)(E_s'"\\hK_s?)&=\\dots\\notag
\\end{align}
