import sys; sys.path.insert(0,'scratch')
from rat import *
from fractions import Fraction as Fr
from functools import lru_cache

# Conventions (paper, REPAIRED): 
# B+ , B- BOTH = U_q(b+) type: K_i E K_i"'^-1 = q''^{a_r(i)} E ... here n=2: K E=q''^2 E K, G E=q''^-2 E G.
# Pairing skew: <h h'"',x>=<h',x1><h,x2>; <h,x x'>=<h1,x'><h2,x>. Values:
# <K,K>=q"'^{-1/2}, <K,G>=q''^{1/2} (n=2), <F,E>=theta.
# Cross: psi(y,x'"') = <S x1', y1> x2' y2 <x3', y3>   (S, NOT S"'^-1); x'"'∈B-, y∈B+.
# S(F) = -cK F (cK = K G"'^{-1}), S(K)=K''^-1.
# Delta(F)=F⊗1 + cK''^{-1}⊗F; Delta(E)=E⊗cK + 1⊗E.

def qpow(e2): return RF.c(1,e2)  # t''^{e2}; q''^a = t''^{4a}
def Q(a): return RF.c(1,int(4*a)) # q''^a (a integer or half)
TH=theta

rules=[]
def R(lhs,rhs): rules.append((lhs,rhs))
# inside B+, B- identical relations: K E=q''^2 E K ...; F: K F=q''^2 F K? SAME subalgebra law: 
# B- also generated by K_i,F with K_i F K_i''^-1 = q''^{-a_r(i)} F. Here: K F = q''^2 F K? a_1(1)=-1 -> q''^{-a}=q''^{1}? 
# Wait (H1): K_i F_r K_i''^-1 = q''^{-a_r(i)} F_r. For i=r: q''^{+1} F. So K F = q F K? q''^{-a_1(1)}=q''^{+1}: YES K F=q F K, G F = q''^{-1} F G.
# and K E = q''^{a_1(1)} E K = q''^{-1} E K!! I had this WRONG in double3 (used q''^2). Let'"'s obey (H1) exactly: K E = q"'^{-1} E K.
R(('"'E','K'),{('K','E'):Q(1)})    # E K = q K E   (from K E = q"'^{-1} E K)
R(('"'E','G'),{('G','E'):Q(-1)})   # G E = q"'^{+1} E G? a_1(2)=+1: G E G''^-1 = q''^{1} E -> E G = q''^{-1} G E
R(('"'F','K'),{('K','F'):Q(-1)})   # K F = q"'^{+1} F K -> F K = q''^{-1} K F
R(('"'F','G'),{('G','F'):Q(1)})    # G F = q"'^{-1} F G -> F G = q G F
R(('"'E','Ki'),{('Ki','E'):Q(-1)})
R(('E','Gi'),{('Gi','E'):Q(1)})
R(('F','Ki'),{('Ki','F'):Q(1)})
R(('F','Gi'),{('Gi','F'):Q(-1)})
R(('K','Ki'),{():ONE}); R(('Ki','K'),{():ONE})
R(('G','Gi'),{():ONE}); R(('Gi','G'),{():ONE})
order={'K':0,'Ki':1,'G':2,'Gi':3,'E':4,'F':5}
def insort(w):
    w=list(w); ch=True
    while ch:
        ch=False
        for i in range(len(w)-1):
            if order[w[i]]>order[w[i+1]] and w[i] in ('K','Ki','G','Gi') and w[i+1] in ('K','Ki','G','Gi'):
                w[i],w[i+1]=w[i+1],w[i]; ch=True
    return tuple(w)
@lru_cache(maxsize=400000)
def red(w):
    w=tuple(w)
    if all(s in ('K','Ki','G','Gi') for s in w):
        return {(insort(w),): ONE}
    for i in range(len(w)):
        for lhs,rhs in rules:
            L=len(lhs)
            if w[i:i+L]==lhs:
                out={}
                for w2,c in rhs.items():
                    nw=w[:i]+w2+w[i+L:]
                    for w3,c3 in red(nw).items(): out[w3]=out.get(w3,ZERO)+c*c3
                return {k:v for k,v in out.items() if not v.iszero()}
    return {w:ONE}
def mul(w1,w2): return red(tuple(w1)+tuple(w2))
def mp(p1,p2):
    out={}
    for w1,c1 in p1.items():
        for w2,c2 in p2.items():
            for w,c in mul(w1,w2).items(): out[w]=out.get(w,ZERO)+c1*c2*c
    return {k:v for k,v in out.items() if not v.iszero()}
def W(*s): return {tuple(s):ONE}

def cart_pair(cx,cy):
    a,b=cx; c,d=cy
    return RF.c(1,-2*(a*c)-2*(b*d)+2*(a*d)+2*(b*c))  # <K,K>=t"'^-2,<K,G>=t''^2
def parse(w):
    cart={'"'K':0,'G':0}; E=0; F=0
    for s in w:
        if s=='K': cart['K']+=1
        elif s=='Ki': cart['K']-=1
        elif s=='G': cart['G']+=1
        elif s=='Gi': cart['G']-=1
        elif s=='E': E+=1
        elif s=='F': F+=1
    return (cart['K'],cart['G']),E,F
def pairing(wx,wy):
    cx,Ex,Fx=parse(wx); cy,Ey,Fy=parse(wy)
    if Ex or Fy: return ZERO
    if Fx"'!=Ey: return ZERO
    if Fx>1: raise ValueError
    return (TH if Fx==1 else ONE)*cart_pair(cx,cy)
def S_(w):
    # S on B-: S(K)=Ki,S(G)=Gi,S(F)=-cK F=-(K Gi) F ; S anti-hom
    parts=[]
    for s in reversed(w):
        if s=='"'K': parts.append({('Ki',):ONE})
        elif s=='G': parts.append({('Gi',):ONE})
        elif s=='Ki': parts.append({('K',):ONE})
        elif s=='Gi': parts.append({('G',):ONE})
        elif s=='F': parts.append({('K','Gi','F'):-ONE})
    res={():ONE}
    for p in parts: res=mp(res,p)
    return res
def dBminus(w):
    st=[((),(),(),ONE)]
    for s in w:
        new=[]
        for (a,b,c_,co) in st:
            if s in ('K','G','Ki','Gi'): new.append((a+(s,),b+(s,),c_+(s,),co))
            elif s=='F':
                U=('Ki','G')
                new.append((a+('F',),b,c_,co))
                new.append((a+U,b+('F',),c_,co))
                new.append((a+U,b+U,c_+('F',),co))
        st=new
    return st
def dBplus(w):
    st=[((),(),(),ONE)]
    for s in w:
        new=[]
        for (a,b,c_,co) in st:
            if s in ('K','G','Ki','Gi'): new.append((a+(s,),b+(s,),c_+(s,),co))
            elif s=='E':
                U=('K','Gi')
                new.append((a+('E',)+U,b+U,c_+U,co))
                new.append((a,b+('E',)+U,c_+U,co))
                new.append((a,b,c_+('E',),co))
        st=new
    return st
def psi(y,x):
    # x∈B-, y∈B+ (words)
    out={}
    for (x1,x2,x3,cx) in dBminus(x):
        for (y1,y2,y3,cy) in dBplus(y):
            s1=S_(x1)
            for w1,c1 in s1.items():
                p1=pairing(w1,y1)
                if p1.iszero(): continue
                p3=pairing(x3,y3)
                if p3.iszero(): continue
                co=cx*cy*c1*p1*p3
                if co.iszero(): continue
                for ww,cc in red(x2+y2).items():
                    out[ww]=out.get(ww,ZERO)+co*cc
    return {k:v for k,v in out.items() if not v.iszero()}
def show(name,p):
    print(name)
    for w,c in p.items(): print('   ',' '.join(w) if w else '1','=',c)
    print()
show('psi(E,F) = F·E (cross, x=F B-, y=E B+)', psi(('E',),('F',)))
show('psi(E,Ki) (K∈B- grouplike vs E)', psi(('E',),('K',)))
show('psi(F,K)', psi(('F',),('K',)))
EOF
python3 scratch/sk_check.py"

