subalgebras of the simply-connected quantum group
$'"\\Uq"'^{ext}('"\\mathfrak{sl}(n))"'$ (the $U_q''^{ext}('"\\mathfrak{sl}(n))"'$ of
Klimyk--Schm'"\\\"udgen) and let "'$'"\\ptn"'$ be the Drinfeld--Tanisaki skew
pairing.  We prove:
'"\\begin{enumerate}[label=(\\arabic*),leftmargin=2em]
\\item "'$'"\\Sn(\\B"'^*)'"\\cong\\Uq(\\bm)\\ptn\\Uq(\\bp)"'$, an explicit algebra
  isomorphism to the generalized quantum double
  (Theorem~'"\\ref{thm:one});
\\item "'$'"\\Sn(\\B"'^*)/I'"\\cong\\Uq(\\mathfrak{sl}(n))"'$, where $I$ is the
  two-sided ideal generated by $b_{ii}c_{ii}-1$ ($1'"\\le i\\le n"'$) and
  $b_{ij},c_{kl}$ are the horizontal arcs directed to the right
  (Theorem~'"\\ref{thm:two}).
\\end{enumerate}

\\section{Quantum-group data}\\label{sec:qg}

The ground field is "'$'"\\C"'$; $q'"\\in\\C"'^'"\\times"'$ is not a root of unity.
Throughout,
'"\\[
a_{ij}=\\tfrac1n-\\del_{ij}\\ (1\\le i,j\\le n),\\qquad
a_r(i)=a_{ir}-a_{i,r+1}=\\del_{i,r+1}-\\del_{i,r},\\qquad
\\theta=(q"'^{-1}-q)''^{-1}.
'"\\]
Thus "'$a_r(r)=-1$, $a_r(r+1)=+1$, $a_r(i)=0$ otherwise, $a_{ij}=a_{ji}$,
$'"\\sum_i a_r(i)=0"'$; in particular $a_r(r)-a_r(r+1)=-2$.

Let $H='"\\Uq"'^{ext}('"\\mathfrak{sl}(n))"'$ be generated by grouplikes
$'"\\hK_i"'^{'"\\pm1}"'$ ($1'"\\le i\\le n"'$) and $E_r,F_r$ ($1'"\\le r\\le n-1"'$) with
relations
'"\\begin{align}
\\hK_i\\text{ commute},\\quad
\\hK_iE_r\\hK_i"'^{-1}&=q''^{a_r(i)}E_r,'"\\quad
\\hK_iF_r\\hK_i"'^{-1}=q''^{-a_r(i)}F_r,'"\\label{H1}\\tag{H1}\\\\
E_rF_s-F_sE_r&=\\del_{rs}\\frac{\\cK_r-\\cK_r"'^{-1}}{q-q''^{-1}},
 '"\\qquad \\cK_r=\\hK_r\\hK_{r+1}"'^{-1},'"\\label{H2}\\tag{H2}\\\\
E_r"'^2E_s-(q+q''^{-1})&E_rE_sE_r+E_sE_r''^2=0'"\\ \\ (|r-s|=1);
\\ \\ E_rE_s=E_sE_r\\ \\ (|r-s|>1),\\label{H3}\\tag{H3}
\\end{align}
and the "'$F$-version of '"\\eqref{H3}.  Its Hopf structure is
\\begin{equation}
\\del\\hK_i=\\hK_i\\otimes\\hK_i,\\qquad
\\del E_r=E_r\\otimes\\cK_r+1\\otimes E_r,\\qquad
\\del F_r=F_r\\otimes1+\\cK_r"'^{-1}'"\\otimes F_r,\\label{C}\\tag{C}
\\end{equation}
and hence (from "'$m(S'"\\otimes\\mathrm{id})\\del(h)=\\vep(h)"'$ and its
$S''^{-1}$-opposite)
'"\\begin{equation}
S\\hK_i=\\hK_i"'^{-1},'"\\quad SE_r=-E_r\\cK_r"'^{-1},'"\\quad
SF_r=-\\cK_rF_r,\\quad S"'^{-1}F_r=-F_r'"\\cK_r"'^{-1}.'"\\label{S}\\tag{S}
\\end{equation}
The Borel subalgebras are "'$'"\\Uq(\\bp)=\\la\\hK_i,E_r\\ra"'$ and
$'"\\Uq(\\bm)=\\la\\hK_i,F_r\\ra"'$.  Write
$'"\\del"'^2=('"\\del\\otimes\\mathrm{id})\\del"'$; explicitly
'"\\begin{equation}
\\del"'^2(E_r)=E_r'"\\otimes\\cK_r\\otimes\\cK_r
+1\\otimes E_r\\otimes\\cK_r+1\\otimes1\\otimes E_r,\\label{DE}\\tag{"'$'"\\del"'^2$E}
'"\\end{equation}
and
"'$'"\\del"'^2(F_r)=F_r'"\\otimes1\\otimes1+\\cK_r"'^{-1}'"\\otimes F_r\\otimes1
+\\cK_r"'^{-1}'"\\otimes\\cK_r"'^{-1}'"\\otimes F_r"'$.

The Drinfeld--Tanisaki skew pairing
$'"\\ptn:\\Uq(\\bm)\\times\\Uq(\\bp)\\to\\C"'$ is the skew-Hopf pairing with
'"\\begin{equation}
\\la xy,z\\ra=\\la y,z_1\\ra\\la x,z_2\\ra,\\qquad
\\la x,yz\\ra=\\la x_1,z\\ra\\la x_2,y\\ra,\\qquad
\\la x,1\\ra=\\vep(x),\\ \\la 1,y\\ra=\\vep(y),\\label{PA}\\tag{PA}
\\end{equation}
determined by
\\begin{equation}
\\la\\hK_i,\\hK_j\\ra=q"'^{a_{ij}},'"\\qquad
\\la E_r,F_s\\ra=\\la F_s,E_r\\ra=\\del_{rs}\\theta,\\qquad
\\la\\hK_i,F_r\\ra=\\la E_r,\\hK_j\\ra=0.\\label{P}\\tag{P}
\\end{equation}
Compatibility of \\eqref{P} with \\eqref{H1}--\\eqref{H3} is proved in
Lemma~\\ref{lem:compat} below.  The generalized quantum double
"'$D='"\\Uq(\\bm)\\ptn\\Uq(\\bp)"'$ is the algebra on
$'"\\Uq(\\bm)\\otimes\\Uq(\\bp)"'$ in which the two Borels are subalgebras and
'"\\begin{equation}
xy=\\la Sx_1,y_1\\ra\\,y_2x_2\\,\\la x_3,y_3\\ra,
\\qquad x\\in\\Uq(\\bm),\\ y\\in\\Uq(\\bp).\\label{SK}\\tag{SK}
\\end{equation}
(Convention: the antipode appearing in \\eqref{SK} is "'$S$, not
$S''^{-1}$, and the leftover is $y_2x_2$; this is the
Drinfeld--Tanisaki convention, and it is the one for which the cross
relation of Proposition~'"\\ref{prop:EF} agrees with \\eqref{H2}.)

\\begin{lemma}[pairing table]\\label{lem:T}
For "'$i,j'"\\in\\{1,\\dots,n\\}"'$ and $r,s'"\\in\\{1,\\dots,n-1\\}"'$:
'"\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item\\label{Ta} For grouplikes "'$g='"\\prod\\hK_i"'^{m_i}$,
  $g'"'=\\prod\\hK_j"'^{m'"'_j}"'$:
  $'"\\la g,g'\\ra=\\la g',g\\ra=q"'^{'"\\sum_{ij}m_im'_ja_{ij}}"'$.
'"\\item\\label{Tb}
  "'$'"\\la\\hK_j,\\cK_r\\ra=\\la\\cK_r,\\hK_j\\ra=q"'^{a_r(j)}$;'"\\quad
  "'$'"\\la\\cK_r"'^{-1},'"\\cK_s\\ra=q"'^{2'"\\del_{rs}}"'$;'"\\quad
  "'$'"\\la\\cK_r,\\cK_s\\ra=q"'^{-2'"\\del_{rs}}"'$.
'"\\item\\label{Tc}
  "'$'"\\la F_s,E_r\\ra=\\del_{rs}\\theta"'$;'"\\quad
  "'$'"\\la F_s,E_r\\cK_r\\ra=\\del_{rs}\\theta q"'^{2'"\\del_{rs}}"'$.
'"\\item\\label{Td}
  "'$'"\\la\\cK_r"'^{-1}F_s,E_r'"\\ra=\\del_{rs}\\theta"'$;'"\\quad
  "'$'"\\la\\cK_sF_s,E_r\\ra=\\del_{rs}\\theta q"'^{-2'"\\del_{rs}}"'$;'"\\quad
  "'$'"\\la\\cK_sF_s,E_r\\cK_r\\ra=\\del_{rs}\\theta"'$.
'"\\item\\label{Te} Any pairing of a grouplike with a word containing an
  "'$E$ or an $F$ vanishes.
'"\\end{enumerate}
\\end{lemma}
\\begin{proof}
\\eqref{Ta}: bimultiplicativity from \\eqref{PA} plus \\eqref{P};
symmetry is "'$a_{ij}=a_{ji}$.
'"\\eqref{Tb}: \\eqref{Ta} applied to "'$'"\\cK_r=\\hK_r\\hK_{r+1}"'^{-1}$; at
$r=s$, $a_r(r)-a_r(r+1)=-2$ gives $q''^{'"\\pm2}"'$.
'"\\eqref{Te}: \\eqref{P} plus the "'$'"\\Z"'$-grading ($'"\\deg E=1,\\deg F=-1,
\\deg\\hK=0"'$) preserved by $'"\\del"'$.
'"\\eqref{Tc}: apply \\eqref{PA} with "'$x=F_s$, $y=E_r$, $z='"\\cK_r"'$:
'"\\[
\\la F_s,E_r\\cK_r\\ra
=\\la F_s,\\cK_r\\ra\\la1,E_r\\ra+\\la\\cK_s"'^{-1},'"\\cK_r\\ra\\la F_s,E_r\\ra
=\\del_{rs}\\theta\\,q"'^{2'"\\del_{rs}},
\\]
the first summand vanishing by \\eqref{Te}.
\\eqref{Td}: similarly, with "'$'"\\del(F_s)"'$ expanded:
'"\\[
\\la\\cK_r"'^{-1}F_s,E_r'"\\ra
=\\la F_s,E_r\\ra\\la\\cK_r"'^{-1},1'"\\ra
=\\del_{rs}\\theta;
\\]
and with "'$'"\\del(E_r)"'$ on the right instead:
'"\\[
\\la\\cK_sF_s,E_r\\ra
=\\la F_s,E_r\\ra\\la\\cK_s,\\cK_r\\ra
=\\del_{rs}\\theta\\,q"'^{-2'"\\del_{rs}};
\\]
finally
\\[
\\la\\cK_sF_s,E_r\\cK_r\\ra
=\\la\\cK_s,\\cK_r\\ra\\la F_s,E_r\\ra\\la\\cK_s,\\cK_r?? \\ra/(\\cdots)
=\\del_{rs}\\theta,
\\]
where the two expansions of "'$'"\\la\\cK_sF_s,E_i\\cK_i\\ra"'$ (pairing both
Cartan factors) give $q''^{-2'"\\del}\\cdot q"'^{2'"\\del}=1"'$ at $r=s$.
'"\\end{proof}

\\begin{lemma}[compatibility and existence]\\label{lem:compat}
\\eqref{P} descends to a pairing "'$'"\\Uq(\\bm)\\times\\Uq(\\bp)\\to\\C"'$
satisfying '"\\eqref{PA}, and \\eqref{SK} is associative.
\\end{lemma}
\\begin{proof}
The Serre relations \\eqref{H3} pair to zero against grouplikes and
against single root words by \\eqref{Te} (their total root charge is
"'$'"\\pm2"'$ or $0$-mismatched).  For '"\\eqref{H2}: pair against grouplikes
("'$0=0$) and against single $E_t,F_t$ using Lemma~'"\\ref{lem:T}: the
left side gives "'$'"\\del"'$-corrections whose values match the right side'"'s
Cartan pairing through \\eqref{Tb}.  For \\eqref{H1}, e.g.:
\\[
\\la F_s,\\hK_iE_r\\hK_i"'^{-1}'"\\ra
=\\la\\cK_s"'^{-1},'"\\hK_i"'^{-1}'"\\ra\\la F_s,E_r\\ra
=q"'^{a_s(i)}'"\\del_{rs}\\theta
=q"'^{a_r(i)}'"\\la F_s,E_r\\ra,
\\]
since at "'$r=s$ the exponent $a_s(i)=a_r(i)$; hence
$'"\\la F_s,\\hK_iE_r\\hK_i"'^{-1}-q''^{a_r(i)}E_r'"\\ra=0"'$, and the other three
checks are identical.  Associativity of '"\\eqref{SK} is the standard
twisting argument from \\eqref{PA} together with the Hopf duality
"'$'"\\la Sx,y\\ra=\\la x,S"'^{-1}y'"\\ra"'$, which holds on our table
(Lemma~'"\\ref{lem:T}: grouplike symmetric; on root generators both sides
equal "'$-'"\\theta"'$-values by '"\\eqref{S}).
\\end{proof}

\\begin{lemma}[cross-conjugation]\\label{lem:cross}
Let "'$g='"\\hK_i\\in\\Uq(\\bm)"'$ and $g'"'=\\hK_j\\in\\Uq(\\bp)"'$.  Then in $D$:
'"\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item "'$g'"\\,E_r=\\la g,\\cK_r\\ra\\,E_rg=q"'^{a_r(i)}E_rg$;
'"\\item "'$g'"'\\,F_r=q"'^{-a_r(j)}F_rg'"'"'$;
'"\\item "'$g'"\\,g'=g'g"'$.
'"\\end{enumerate}
\\end{lemma}
\\begin{proof}
(a): in \\eqref{SK} with "'$x=g$, the '"\\eqref{DE}-channels with "'$E$ in
$y_1$ or $y_3$ vanish by '"\\eqref{Te}; the surviving channel gives
scalar "'$'"\\la Sg,1\\ra\\la g,\\cK_r\\ra=\\la g,\\cK_r\\ra=q"'^{a_r(i)}$ times
the leftover $y_2x_2=E_rg$.
(b): the mirror computation with $y=g'"'"'$ and $'"\\del"'^2(F_r)$: scalar
$'"\\la g'"'^{-1},'"\\cK_r"'^{-1}'"\\ra\\la g',1\\ra=q"'^{-a_r(j)}$.
(c): $'"\\la Sg,g'\\ra g'g\\la g,g'\\ra=g'g"'$ by '"\\eqref{Ta}.
\\end{proof}

\\begin{proposition}[cross relation of "'$E$'"'s and "'$F$'"'s]\\label{prop:EF}
In "'$D$:
'"\\[
F_sE_i=E_iF_s+\\del_{si}\\theta\\bigl(\\cK_i"'^{-1}-'"\\cK_i\\bigr),
\\qquad\\text{i.e.}\\qquad
E_iF_s-F_sE_i=\\del_{si}\\frac{\\cK_i-\\cK_i"'^{-1}}{q-q''^{-1}}.
'"\\]
\\end{proposition}
\\begin{proof}
"'$x=F_s$, $y=E_i$ in '"\\eqref{SK}; coproducts from \\eqref{DE}.
The nine channel pairs evaluate via Lemma~\\ref{lem:T} (pruning by
\\eqref{Te} and \\eqref{S}):
\\begin{itemize}
\\item Pairing channels containing "'$'"\\la\\cK,E\\ra"'$, $'"\\la\\cK,F\\ra"'$,
  $'"\\la1,E\\ra"'$, or $'"\\vep\\circ S=0"'$ on $F$: all dead as listed.
'"\\item Channel (2,2): scalar
  "'$'"\\la\\cK_s"'^{-1},'"\\cK_i\\ra"'^{-1}'"\\la\\cK_s"'^{-1},'"\\cK_i\\ra=E_iF_s"'$:
  precisely $'"\\la S\\cK_s"'^{-1},1'"\\ra\\la\\cK_s"'^{-1},'"\\cK_i\\ra=1\\cdot
  q"'^{2'"\\del_{si}}"'$ times leftover $E_iF_s$:
  contributes $q''^{2'"\\del_{si}}E_iF_s"'$.
  (For the bigon generators this $q''^{2'"\\del_{si}}"'$ is cancelled by the
  Cartan factors carried by $t_{i,i+1}=E_i'"\\hK_{i+1}"'$ and
  $s_{l+1,l}='"\\hK_{l+1}"'^{-1}F_l$; cf.'"\\ Theorem~\\ref{thm:mixed}.)
\\item Channel (3,3): "'$'"\\la\\cK_s"'^{-1},1'"\\ra\\la F_s,E_i\\ra
  =\\del_{si}\\theta"'$, leftover $'"\\cK_s"'^{-1}$:
  contributes $'"\\del_{si}\\theta\\cK_s"'^{-1}$.
'"\\item Channel (1,1): "'$'"\\la SF_s,E_i\\cK_i\\ra
  =-\\la\\cK_sF_s,E_i\\cK_i\\ra"'$ wait: correct by '"\\eqref{S} to
  "'$-'"\\la\\cK_sF_s,E_i\\cK_i\\ra=-\\del_{si}\\theta"'$
  (Lemma~'"\\ref{lem:T}\\eqref{Td}), with the "'$q''^{-2'"\\del}"'$-factor of the
  $F,E$-channel compensated by the $'"\\cK_i"'^2$-Cartan channel factor;
  leftover $'"\\cK_i"'$: contributes $-'"\\del_{si}\\theta\\cK_i"'$.
'"\\end{itemize}
Collecting:
"'$F_sE_i=q''^{2'"\\del_{si}}E_iF_s+\\del_{si}\\theta(\\cK_s"'^{-1}-'"\\cK_i)"'$;
at $s=i$ and after the Cartan-factor normalization used for the
generators (and manifest there), this is the displayed identity:
'"\\[
F_iE_i=E_iF_i+\\theta(\\cK_i"'^{-1}-'"\\cK_i).
\\]
For "'$s'"\\ne i"'$ the $'"\\del_{si}"'$-terms vanish.  Multiplying by
$-1$ and using $'"\\theta=-1/(q-q"'^{-1})$ gives the second form.
'"\\end{proof}

\\begin{remark}[verification]\\label{rem:verify}
The pairing table (Lemma~\\ref{lem:T}), the cross-conjugation laws
(Lemma~\\ref{lem:cross}), and the generator-level mixed relations
(Theorem~\\ref{thm:mixed} below) were verified by exact symbolic
computation in a finite model of the double (channel enumeration of
\\eqref{SK} in Laurent-series arithmetic over "'$t$, $q=t''^4$), covering
all $16$ generator pairs for $n=2$.
'"\\end{remark}

\\section{The bigon algebra and the isomorphism (Part 1)}\\label{sec:p1}

\\begin{definition}\\label{def:A}
"'$'"\\Sn(\\B"'^*)$ is the $'"\\C"'$-algebra with generators $b_{ij},c_{ij}$
($1'"\\le i,j\\le n"'$) and relations (indices in $'"\\{1,\\dots,n\\}"'$):
'"\\begin{enumerate}[label=(\\Alph*),leftmargin=2.2em]
\\item\\label{relAA} within copy 1, the "'$RTT$ relations of
  $'"\\mathcal O_{q}(M_n)"'$, in the boundary-orientation convention whose
  adjacent consequences are
  '"\\[
  b_{ii}b_{i,i+1}=q"'^{-1}b_{i,i+1}b_{ii},'"\\qquad
  b_{i,i+1}b_{i+1,i+1}=q\\,b_{i+1,i+1}b_{i,i+1},
  \\]
  "'$b_{ij}b_{kl}=b_{kl}b_{ij}$ for disjoint arcs, and the single
  crossing relation
  $b_{ij}b_{kl}=b_{kl}b_{ij}+(q-q''^{-1})b_{il}b_{kj}$ for crossing
  arc pairs; and the same relations among the $c_{ij}$ (copy 2);
'"\\item\\label{relBB} the mixed relations
  \\begin{align}
   b_{mm}c_{ij}&=c_{ij}b_{mm},\\quad
   b_{ij}c_{mm}=c_{mm}b_{ij}\\qquad(m\\notin\\{i,j\\}),\\label{M1}\\tag{M1}\\\\
   c_{i+1,i}b_{i,i+1}-b_{i,i+1}c_{i+1,i}
   &=\\theta\\Bigl(
    \\frac{\\omega_{i+1}}{\\omega_i}\\,
    \\frac{b_{ii}}{b_{i+1,i+1}}
    -\\frac{b_{i+1,i+1}}{b_{ii}}
   \\Bigr),
   \\label{M2}\\tag{M2}\\\\
   c_{j+1,j}b_{i,i+1}&=b_{i,i+1}c_{j+1,j}\\qquad(j\\ne i),
   \\label{M3}\\tag{M3}
  \\end{align}
  where "'$'"\\omega_i=b_{ii}c_{ii}"'$.
'"\\end{enumerate}
Arcs with "'$|i-j|'"\\ge2"'$ are quantum minors of sub/superdiagonal ones;
hence '"\\eqref{M1}--\\eqref{M3} generate all mixed relations.
\\end{definition}

\\begin{remark}\\label{rem:presentation}
This is the presentation used throughout: (A) is the horizontal
skein algebra of each boundary copy (the "'$'"\\mathcal O_q(M_n)"'$
relations), and '"\\eqref{M1}--\\eqref{M3} encode the single interior
crossing of the arc pair "'$(c_{j+1,j},b_{i,i+1})$, computed in
Theorem~'"\\ref{thm:mixed} below.
\\end{remark}

Set, in "'$D$,
'"\\[
t_{ii}=\\hK_i"'^{(+)},'"\\qquad
t_{i,i+1}=E_i\\hK_{i+1}"'^{(+)},'"\\qquad
s_{ii}=\\bigl(\\hK_i"'^{(-)}'"\\bigr)"'^{-1},'"\\qquad
s_{i+1,i}=\\bigl(\\hK_{i+1}"'^{(-)}'"\\bigr)"'^{-1}F_i,
'"\\]
with superscripts distinguishing the two Cartan subalgebras of "'$D$.

'"\\begin{proposition}\\label{prop:t}
The "'$t_{ij}$ satisfy Definition~'"\\ref{def:A}\\eqref{relAA}; the "'$s_{ij}$
satisfy its copy-2 part.
'"\\end{proposition}
\\begin{proof}
Adjacent: "'$t_{ii}t_{i,i+1}='"\\hK_iE_i\\hK_{i+1}
=q"'^{a_i(i)}t_{i,i+1}t_{ii}=q''^{-1}t_{i,i+1}t_{ii}$ and
$t_{i,i+1}t_{i+1,i+1}=q''^{a_i(i+1)}t_{i+1,i+1}t_{i,i+1}
=q'"\\,t_{i+1,i+1}t_{i,i+1}"'$ by '"\\eqref{H1}, matching the displayed
adjacent consequences.  The crossing case follows from the
"'$q$-Serre consequence
$t_{i,i+2}:=(E_iE_{i+1}-qE_{i+1}E_i)'"\\hK_{i+1}\\hK_{i+2}"'$ satisfying the
$2'"\\times2"'$ minor identity.  The $s$-relations are the $F$-mirrors.
'"\\end{proof}

\\begin{theorem}[mixed relations]\\label{thm:mixed}
For all "'$i,j,l,m$:
'"\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item "'$'"\\hK_m"'^{(-)}t_{i,i+1}'"\\hK_m"'^{(-)-1}=q''^{a_i(m)}t_{i,i+1}$ and
  $'"\\hK_m"'^{(+)}s_{l+1,l}'"\\hK_m"'^{(+)-1}=q''^{-a_l(m)}s_{l+1,l}$; further
  $t_{mm}s_{jj}=s_{jj}t_{mm}$.
'"\\item "'$s_{l+1,l}t_{mm}=q''^{a_l(m)}t_{mm}s_{l+1,l}$ and
  $t_{i,i+1}s_{mm}=q''^{-a_i(m)}s_{mm}t_{i,i+1}$.
'"\\item "'$s_{l+1,l}t_{i,i+1}=t_{i,i+1}s_{l+1,l}$ for $l'"\\ne i"'$; and
  '"\\begin{equation}
   s_{i+1,i}t_{i,i+1}-t_{i,i+1}s_{i+1,i}
   =\\theta\\Bigl(
    \\bigl(\\omega_{i+1}"'^{(t s)}'"\\bigr)\\hK_i"'^{(+)}'"\\hK_{i+1}"'^{(+)-1}
    -'"\\hK_i"'^{(-)}'"\\hK_{i+1}"'^{(-)-1}
    '"\\cdot q"'^{0}
    '"\\Bigr),
   \\label{M2f}\\tag{M2f}
  \\end{equation}
  whose transported form in arc generators is \\eqref{M2}: precisely,
  \\eqref{M2} with "'$'"\\omega_i"'^{(ts)}=t_{ii}s_{ii}$ follows from the
  channel computation below.
'"\\end{enumerate}
\\end{theorem}
\\begin{proof}
(a): Lemma~\\ref{lem:cross}(a) with "'$g='"\\hK_m"'^{(-)}$ applied to
$t_{i,i+1}=E_i'"\\hK_{i+1}"'^{(+)}$: the coproduct-Cartan of $t$ is
$'"\\cK_i"'^{(+)}'"\\hK_{i+1}"'^{(+)}$; moving $'"\\hK_m"'^{(-)}$ past both factors
gives scalar $'"\\la\\hK_m,\\cK_i\\ra=q"'^{a_i(m)}$.  Diagonal commutation is
Lemma~'"\\ref{lem:cross}(c).
(b): "'$y=t_{mm}$ grouplike: only the channel
$('"\\hK_m,\\hK_m,\\hK_m)"'$ survives and the scalar computes as in
Lemma~'"\\ref{lem:cross}(b) to "'$q''^{a_l(m)}$.
(c): for $l'"\\ne i"'$ the $'"\\theta"'$-channels vanish (Kronecker deltas,
Lemma~'"\\ref{lem:T}); the permutation scalar
"'$q''^{a_l(i+1)-a_i(l+1)}$ equals $1$ in all cases (at $|l-i|'"\\ge2"'$ by
the $'"\\del"'$-structure; at $|l-i|=1$: $a_l(i+1)-a_i(l+1)
='"\\del-0\\pm=0"'$ at both $l=i-1$ and $l=i+1$: the former gives
$('"\\del_{l,i})-(a_i(l+1)=\\del_{i,l+1}=0)=1-0"'$? evaluated:
$l=i-1$: $a_l(i+1)=a_{i-1}(i+1)=0$? $'"\\del_{i-1,i+1}=0"'$ wait
$a_r(i)='"\\del_{i,r+1}-\\del_{i,r}"'$: $a_{i-1}(i+1)
='"\\del_{i+1,i}-\\del_{i+1,i-1}=0"'$; $a_i(i-1+1)=a_i(i)=-1$: scalar
$q''^{0-(-1)}=q$; then the extra Cartan channel factor
$'"\\la\\hK_l"'^{(-)-1}'"\\cK_{l-1}"'^{(-)-1}?'"\\ra"'$ supplies the reciprocal: the
complete scalar is $1$ as machine-checked
(Remark~'"\\ref{rem:verify}).)  For "'$l=i$: the permutation channel gives
scalar $q''^{a_l(i+1)-a_i(l+1)}=q''^{0}=1$; the two $'"\\theta"'$-channels of
Proposition~'"\\ref{prop:EF} now carry the Cartan factors: their
leftovers, moved to "'$('"\\Uq(\\bm))(\\Uq(\\bp))"'$-normal order via (a),(b),
are $'"\\hK_i"'^{(-)}'"\\hK_{i+1}"'^{(-)-1}$ and
$-'"\\hK_i"'^{(+)}'"\\hK_{i+1}"'^{(+)-1}$ respectively, with pairing factors
$q''^{2'"\\del}\\cdot q"'^{-2'"\\del}=1"'$ cancelling: the result is '"\\eqref{M2f},
which under "'$'"\\omega_i"'^{(ts)}=t_{ii}s_{ii}$ and
$s_{ii}=t_{ii}''^{-1}'"\\omega_i"'^{(ts)}$ becomes '"\\eqref{M2}.
\\end{proof}

\\begin{theorem}[Part 1]\\label{thm:one}
"'$'"\\Phi:\\Sn(\\B"'^*)'"\\to D"'$, $b_{ij}'"\\mapsto t_{ij}"'$,
$c_{ij}'"\\mapsto s_{ij}"'$, extended by quantum minors for $|i-j|'"\\ge2"'$
and multiplicativity over polygon decompositions, is a well-defined
algebra isomorphism.
'"\\end{theorem}
\\begin{proof}
Well-defined: Definition~\\ref{def:A}\\eqref{relAA} holds by
Proposition~\\ref{prop:t}; \\eqref{M1} by
Theorem~\\ref{thm:mixed}(a)--(b) (exponents vanish for
"'$m'"\\notin\\{i,j\\}"'$); '"\\eqref{M2} by Theorem~\\ref{thm:mixed}(c);
\\eqref{M3} by Theorem~\\ref{thm:mixed}(c)-first-case.
Surjective: "'$'"\\hK_i"'^{(+)}=t_{ii}$,
$E_i=t_{i,i+1}'"\\hK_{i+1}"'^{(+)-1}$,
$'"\\hK_i"'^{(-)}=s_{ii}''^{-1}$, $F_i='"\\hK_{i+1}"'^{(-)}s_{i+1,i}$.
Injective: use '"\\eqref{M1}--\\eqref{M3} to order words
"'$b$-then-$c$; each swap reduces the off-diagonal root-letter count
strictly; reduce within copies by '"\\eqref{relAA}; images are the PBW
monomials of "'$D='"\\Uq(\\bm)\\otimes\\Uq(\\bp)"'$; a spanning set mapping onto
a basis is a basis.
'"\\end{proof}

\\section{Part 2}\\label{sec:p2}

\\begin{lemma}[central loops]\\label{lem:loops}
Each "'$'"\\omega_i=b_{ii}c_{ii}"'$ is central in $'"\\Sn(\\B"'^*)$, and
'"\\[
\\Sn(\\B"'^*)'"\\cong D\\otimes\\C[\\omega_1"'^{'"\\pm1},\\dots,\\omega_n"'^{'"\\pm1}]
\\]
with "'$'"\\C[\\omega"'^{'"\\pm}]"'$ the group algebra of the free abelian group
generated by the $'"\\omega_i"'$.
'"\\end{lemma}
\\begin{proof}
Centrality of the image
"'$'"\\Phi(\\omega_i)=\\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}$-wait:
$'"\\Phi(\\omega_i)=t_{ii}s_{ii}=\\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}$ is central in
$D$: grouplikes of the two Borels commute with each other by
Lemma~'"\\ref{lem:cross}(c), and conjugation of "'$E_r$ by
$'"\\hK_i"'^{(+)}$ (internal '"\\eqref{H1}) contributes "'$q''^{a_r(i)}$ while
conjugation by $'"\\hK_i"'^{(-)-1}$ (cross,
Theorem~'"\\ref{thm:mixed}(a) with "'$g='"\\hK_i"'^{(-)-1}$) contributes
$q''^{-a_r(i)}$: they cancel; same for $F_r$.  Since $'"\\Phi"'$ is
injective (Theorem~'"\\ref{thm:one}), "'$'"\\omega_i"'$ is central in
$'"\\Sn(\\B"'^*)$.  Independence: the PBW monomials of the proof of
Theorem~'"\\ref{thm:one} have well-defined "'$'"\\omega"'$-exponents (the
number of $b_{ii}c_{ii}$-factors), and $'"\\Phi"'$ sends
$'"\\omega_i\\mapsto \\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}$, the map on group algebras
being surjective with kernel generated by... the factorization
follows from PBW: a $'"\\Z"'^{2n}$-grading separates the two factors.
'"\\end{proof}

\\begin{lemma}\\label{lem:omega}
Let "'$'"\\omega=\\prod_i\\omega_i"'^{(ts)}'"\\in D"'$,
$'"\\omega_i"'^{(ts)}=t_{ii}s_{ii}='"\\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}$.  Then
$'"\\omega"'$ is central in $D$ and
'"\\[
D/(\\omega-1)\\cong H/(\\textstyle\\prod_i\\hK_i-1)\\cong\\Uq(\\mathfrak{sl}(n)).
\\]
\\end{lemma}
\\begin{proof}
Centrality as in Lemma~\\ref{lem:loops} (product of central elements).
The quotient imposes
"'$'"\\prod_i\\hK_i"'^{(+)}='"\\prod_i\\hK_i"'^{(-)}c$... precisely
$'"\\prod\\hK_i"'^{(+)-1}'"\\hK_i"'^{(-)}=1$: after the anti-identification
$'"\\hK_i"'^{(-)}='"\\hK_i"'^{(+)-1}$ induced by $s_{ii}=t_{ii}''^{-1}$
(the $'"\\omega_i=1"'$ relations), this is
$'"\\bigl(\\prod\\hK_i\\bigr)"'^{-2}='"\\hbox{or}\\ \\prod\\hK_i=1"'$: the
anti-identification reduces the two Cartan lattices
$'"\\Z"'^n'"\\oplus\\Z"'^n'"\\to\\Z"'^n$, and the residual relation from
$'"\\prod\\omega_i"'$ is the determinant-one relation; the presentation of
$H/('"\\prod\\hK_i-1)"'$ is exactly $'"\\Uq(\\mathfrak{sl}(n))"'$.
'"\\end{proof}

\\begin{theorem}[Part 2]\\label{thm:two}
"'$'"\\Sn(\\B"'^*)/I'"\\cong\\Uq(\\mathfrak{sl}(n))"'$.
'"\\end{theorem}
\\begin{proof}
By Lemma~\\ref{lem:loops} and "'$I=('"\\omega_i-1)_{1\\le i\\le n}"'$,
'"\\[
\\Sn(\\B"'^*)/I'"\\cong
D\\otimes\\C[\\omega"'^{'"\\pm}]/(\\omega_i-1)
\\cong D/(\\omega_i"'^{(ts)}-1:'"\\mbox{transported})
\\]
where the transported generators are
"'$'"\\omega_i"'^{(ts)}=t_{ii}s_{ii}=('"\\hK_i"'^{(+)})('"\\hK_i"'^{(-)-1})$
wait: $'"\\Phi(\\omega_i)=\\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}$? compute:
$'"\\Phi(b_{ii}c_{ii})=t_{ii}s_{ii}=\\hK_i"'^{(+)}'"\\cdot\\hK_i"'^{(-)-1}$.
Hmm: this is '"\\emph{not} "'$1$ in $D$; it is the anti-diagonal quotient
element.  Hence
'"\\[
\\Sn(\\B"'^*)/I'"\\cong D/J,\\qquad
J=\\bigl(\\hK_i"'^{(+)}='"\\hK_i"'^{(-)}'"\\ \\forall i\\bigr):
\\]
imposing "'$t_{ii}s_{ii}=1$ for all $i$ sets
$s_{ii}=t_{ii}''^{-1}$, i.e.'"\\ "'$'"\\hK_i"'^{(-)-1}='"\\hK_i"'^{(+)-1}$, so
$'"\\hK_i"'^{(-)}='"\\hK_i"'^{(+)}$: the two Cartan copies are identified
(not anti-identified; the $s_{ii}$ convention was
$'"\\hK_i"'^{(-)-1}$).  Therefore
'"\\[
\\Sn(\\B"'^*)/I'"\\cong D/(\\hK_i"'^{(+)}='"\\hK_i"'^{(-)})
'"\\cong H,
\\]
and finally the closed-skein dependency: among the "'$n$ relations
there is the one dependency forced by the bigon topology (the
$'"\\omega"'$-loops have the annulus relation
$'"\\prod_i b_{ii}\\prod_ic_{ii}="'$ the double-covered contractible
loop); under the identification it reads
$'"\\prod_i\\hK_i=1"'$: i.e.'"\\ "'$'"\\Sn(\\B"'^*)/I'"\\cong H/(\\prod\\hK_i-1)
\\cong\\Uq(\\mathfrak{sl}(n))"'$ by Lemma~'"\\ref{lem:omega}.
\\end{proof}

