content = '''\"\"\"Authoritative exact verifier for the FINAL conventions (Round 1 rewrite).

Model: n=2, q = t"'^4, exact Laurent arithmetic (scratch/rat.py).

FINAL system (denoted CONV):
  H algebra:   gp(a,b) E gp(a,b)''^-1 = q''^{a-b} E   (K_i E_r K_i''^-1 = q''^{alpha_r(i)} E)
               same for gm side with F: K_i F_r K_i''^-1 = q''^{-alpha_r(i)} F
  Hopf (D-conv): Delta(E) = E (x) 1 + cK (x) E,  Delta(F) = F (x) cK''^-1 + 1 (x) F
               S(E) = -cK''^-1 E,  S(F) = -F cK,  cK = g(1,-1) per side
  Pairing:     <u, yz> = <u1, z><u2, y>   (PA1)
               <uv, z> = <u, z1><v, z2>   (PA2)
               <g(a,b), g'"'(c,d)> = q"'^{(a,b) A (c,d)''^T}, A = [[-1/2, 1/2],[1/2,-1/2]]
               <F, E> = theta = 1/(q''^-1 - q);  grouplike-with-root pairings = 0
  Cross (SK):  x y = <S x1, y1> y2 x2 <x3, y3>   (x in B-, y in B+)
"""
import sys; sys.path.insert(0, '"'scratch')
from rat import RF
from functools import lru_cache

ONE = RF.c(1); ZERO = RF.c(0)
QP = lambda m: RF.c(1, 2*m)          # q"'^{m/2} = t''^{2m}
Q = lambda a: RF.c(1, 4*a)           # q''^a (integer a)
TH = RF.c(1) / (RF.c(1, -4) - RF.c(1, 4))       # theta = 1/(q''^-1 - q)
BETA = RF.c(1) / (RF.c(1, 4) - RF.c(1, -4))     # beta  = 1/(q - q''^-1) = -theta

def gp(a, b): return ('"'p', a, b)
def gm(a, b): return ('m', a, b)
def isG(s): return isinstance(s, tuple)
def side(s): return s[0]
def wt(s): return (s[1], s[2])

CKP = gp(1, -1); CKPI = gp(-1, 1); CKM = gm(1, -1); CKMI = gm(-1, 1)

def QPAIR(u, v):
    # <g(a,b), g'(c,d)> = q"'^{(a,b) A (c,d)''^T}, A = [[-1/2, 1/2],[1/2,-1/2]]
    (a, b), (c, d) = u, v
    e2 = -a*c - b*d + a*d + b*c       # exponent of q = e2/2 ;  QP(m) = q''^{m/2}
    return QP(e2)

def _splice(w, i, choices):
    out = {}
    for sub, c in choices:
        nw = w[:i] + sub + w[i+1:] if sub else w[:i] + w[i+1:]
        for w2, c2 in red(nw).items():
            out[w2] = out.get(w2, ZERO) + c*c2
    return {k: v for k, v in out.items() if not v.iszero()}

@lru_cache(maxsize=None)
def red(w):
    """Normal order: p-grouplikes, E, m-grouplikes, F (at most one root letter)."""
    w = tuple(w)
    if not w:
        return {(): ONE}
    for i in range(len(w)-1):
        x, y = w[i], w[i+1]
        if isG(x) and isG(y) and side(x) == side(y):
            g = gp(x[1]+y[1], x[2]+y[2]) if side(x) == '"'p' else gm(x[1]+y[1], x[2]+y[2])
            return _splice(w, i, (((g,), ONE),))
        if isG(x) and isG(y) and side(x) == 'm' and side(y) == 'p':
            return _splice(w, i, (((y, x), ONE),))
        if x == 'E' and isG(y) and side(y) == 'p':   # E p(a,b) = q"'^{b-a} p E
            a, b = wt(y)
            return _splice(w, i, (((y, x), QP(2*(b-a))),))
        if x == '"'F' and isG(y) and side(y) == 'm':   # F m(a,b) = q"'^{a-b} m F
            a, b = wt(y)
            return _splice(w, i, (((y, x), QP(2*(a-b))),))
        if isG(x) and side(x) == '"'m' and y == 'E':   # m(a,b) E = q"'^{a-b} E m (cross)
            a, b = wt(x)
            return _splice(w, i, (((y, x), QP(2*(a-b))),))
        if x == '"'F' and isG(y) and side(y) == 'p':   # F p(a,b) = q"'^{a-b} p F (cross)
            a, b = wt(y)
            return _splice(w, i, (((y, x), QP(2*(a-b))),))
        if x == '"'F' and y == 'E':                    # F E = E F + th(CKP - CKMI)
            return _splice(w, i, (((y, x), ONE), ((CKP,), TH), ((CKMI,), -TH)))
    wl = list(w)
    changed = True
    while changed:
        changed = False
        for i in range(len(wl)-1):
            a, b = wl[i], wl[i+1]
            if isG(a) and isG(b) and side(a) == side(b) and wt(a) > wt(b):
                wl[i], wl[i+1] = b, a; changed = True
    if tuple(wl) "'!= w:
        return red(tuple(wl))
    return {w: ONE}

def mulw(w1, w2):
    return red(tuple(w1) + tuple(w2))

def mp(p1, p2):
    out = {}
    for w1, c1 in p1.items():
        for w2, c2 in p2.items():
            for w, c in mulw(w1, w2).items():
                out[w] = out.get(w, ZERO) + c1*c2*c
    return {k: v for k, v in out.items() if not v.iszero()}

def W(*s): return {tuple(s): ONE}

def scale(p, c):
    return {k: c*v for k, v in p.items() if not (c*v).iszero()}

def add(p1, p2):
    out = dict(p1)
    for k, v in p2.items():
        out[k] = out.get(k, ZERO) + v
    return {k: v for k, v in out.items() if not v.iszero()}

def cartwt(w):
    a = b = 0
    for s in w:
        if isG(s): a, b = a+s[1], b+s[2]
        else: return None
    return (a, b)

def nE(w): return sum(1 for s in w if s == '"'E')
def nF(w): return sum(1 for s in w if s == 'F')

@lru_cache(maxsize=None)
def d1(s):
    \"\"\"Two-slot coproduct of one letter (phrase pairs, unreduced).\"\"\"
    if isG(s):
        return [(tuple([s]), tuple([s]))]
    if s == 'E':
        return [(('E',), ()), ((CKP,), ('E',))]
    if s == 'F':
        return [(('F',), (CKMI,)), ((), ('F',))]
    raise ValueError(s)

def d2(w):
    st = [((), ())]
    for s in w:
        st = [(a + h1, b + h2) for (a, b) in st for (h1, h2) in d1(s)]
    return st

@lru_cache(maxsize=None)
def pair(u, v):
    \"\"\"<u, v>, u in B- (m-grouplikes and F), v in B+ (p-grouplikes, E).\"\"\"
    u, v = tuple(u), tuple(v)
    if nE(u) or nF(v):
        raise ValueError('sides violated')
    if nF(u) "'!= nE(v):
        return ZERO
    if nF(u) > 1:
        raise ValueError('"'too many root letters')
    if not u:
        return ZERO if nE(v) else ONE
    if not v:
        return ZERO if nF(u) else ONE
    if len(u) >= 2:
        tot = ZERO
        for (v1, v2) in d2(v):                # PA2: <u0 rest, v> = <u0, v1> <rest, v2>
            tot = tot + pair(u[:1], v1) * pair(u[1:], v2)
        return tot
    u0 = u[0]
    if isG(u0):
        if nE(v):
            return ZERO
        wt2 = cartwt(v)
        return ZERO if wt2 is None else QPAIR(wt(u0), wt2)
    # u == ('F',): PA1:  <F, y z> = <F1, z> <F2, y>
    y, z = v[:1], v[1:]
    return pair(('F',), z) * pair((CKMI,), y) + pair((), z) * pair(('F',), y)

def Sm(u):
    \"\"\"S-prime on a B- word: anti-homomorphism, S(m(a,b)) = m(-a,-b), S(F) = -F CKM.\"\"\"
    out = {(): ONE}
    for s in reversed(tuple(u)):
        if isG(s):
            out = mp(out, W(gm(-s[1], -s[2])))
        else:
            out = mp(out, {('F', CKM): -ONE})
    return out

def d2full(w):
    st = [(((), (), ()), ONE)]
    for s in w:
        if isG(s):
            chans = [((s, s, s), ONE)]
        elif s == 'E':
            chans = [((('E',), (), ()), ONE), (((CKP,), ('E',), ()), ONE),
                     (((CKP,), (CKP,), ('E',)), ONE)]
        elif s == 'F':
            chans = [((('F',), (CKMI,), (CKMI,)), ONE), (((), ('F',), (CKMI,)), ONE),
                     (((), (), ('F',)), ONE)]
        st = [(tuple(slots[k] + ch[k] for k in range(3)), c0*c)
              for (slots, c0) in st for (ch, c) in chans]
    out = {}
    for (slots, c) in st:
        rs, cc = [], c
        for k in range(3):
            items = list(red(slots[k]).items())
            assert len(items) == 1, (slots, k)
            w2, cv = items[0]
            rs.append(w2); cc = cc*cv
        key = tuple(rs)
        out[key] = out.get(key, ZERO) + cc
    return [(k, v) for k, v in out.items() if not v.iszero()]

def try_pair(u, v):
    try:
        return pair(u, v)
    except ValueError:
        return None

def psi(y, x):
    out = {}
    for ((x1, x2, x3), cx) in d2full(x):
        for ((y1, y2, y3), cy) in d2full(y):
            for w1, c1 in Sm(x1).items():
                p1 = try_pair(w1, y1)
                if p1 is None or p1.iszero(): continue
                p3 = try_pair(x3, y3)
                if p3 is None or p3.iszero(): continue
                co = cx*cy*c1*p1*p3
                if co.iszero(): continue
                for w, cw in red(tuple(y2) + tuple(x2)).items():
                    out[w] = out.get(w, ZERO) + co*cw
    return {k: v for k, v in out.items() if not v.iszero()}

def fmt(w):
    if not w: return '1'
    out = []
    for s in w:
        if isG(s):
            out.append(('p' if side(s) == 'p' else 'm') + '(%d,%d)' % (s[1], s[2]))
        else:
            out.append(s)
    return ' '.join(out)

def show(name, p):
    print(name)
    for w, c in sorted(p.items(), key=lambda kv: str(kv[0])):
        print('    ', fmt(w), '=', c)
    print()

PASS = [True]
def check(name, got, want):
    keys = set(got) | set(want)
    ok = all((got.get(k, ZERO) - want.get(k, ZERO)).iszero() for k in keys)
    print(('PASS ' if ok else 'FAIL ') + name)
    if not ok:
        show('  got:', got); show('  want:', want)
        PASS[0] = False

