  where "'$U=U_l+U_r$, $V=V_l+V_r$, and
  $'"\\alpha_r(\\hK"'^'"\\mu)=\\sum_i\\mu_i\\alpha_r(i)"'$.
'"\\end{enumerate}
\\end{lemma}
\\begin{proof}
\\eqref{Ta}: by \\eqref{PA2}, "'$'"\\la uv,\\hK_j\\ra=\\la u,\\hK_j\\ra\\la v,\\hK_j\\ra"'$
since $'"\\Delta(\\hK_j)=\\hK_j\\otimes\\hK_j"'$; iterating and using
'"\\eqref{PA1} on the right argument gives bimultiplicativity with the
displayed order; symmetry is "'$a_{ij}=a_{ji}$.  '"\\eqref{Tb}: immediate from
\\eqref{Ta} with "'$'"\\cK_r=\\hK"'^{'"\\alpha_r}"'$ and $'"\\alpha_r\\cdot\\alpha_s=-2\\del_{rs}"'$.
'"\\eqref{Tc}: from \\eqref{P}, \\eqref{PA1}, \\eqref{PA2} by the root grading
("'$'"\\deg E=+1"'$, $'"\\deg F=-1"'$, $'"\\deg\\hK=0"'$, preserved by $'"\\Delta"'$).
'"\\eqref{Td}: by \\eqref{PA1} with "'$'"\\Delta(F_s)=F_s\\otimes\\cK_s"'^{-1}+1'"\\otimes F_s"'$,
'"\\[
\\la u_lF_su_r,y\\ra=\\la u_l,(y)_1\\ra\\la F_su_r,(y)_2\\ra
\\]
after expanding "'$'"\\la\\cdot,y\\ra"'$ over $'"\\Delta"'^2(y)$-channels; a channel
contributes only if $E_r$ sits in the factor paired with the $F_s$: the
channels with $E_r$ left of that factor die by '"\\eqref{Tc} and
"'$'"\\la g,E\\cdot\\ra=0"'$.  Iterating '"\\eqref{PA2} to move "'$u_l$ leftwards and
$v_r$-factors rightwards, each grouplike traversal of the $F_s$-slot
contributes $'"\\la g,\\cK_s"'^{-1}'"\\ra"'$ or $'"\\la g,\\cK_r\\ra=\\la g,\\hK"'^{'"\\alpha_r}\\ra"'$,
i.e.'"\\ "'$q''^{'"\\pm\\alpha_r(g)\\pm(\\text{target slot})}"'$; direct bookkeeping of the
four traversals (left part of $u$, right part of $u$, left part of $v$,
right part of $v$) plus the bimultiplicative Cartan factor '"\\eqref{Ta} gives
the displayed exponent "'$V'"\\cdot U+2\\alpha_s(U_r)-2\\alpha_r(V_l)"'$.
The computation was also performed symbolically (exact arithmetic in
$'"\\C(t)"'$, $q=t''^4$, $n=2$ and $n=3$ generator families).
'"\\end{proof}

The instances used below are, for all "'$i,s,r$ and grouplikes
$g='"\\hK_i"'^{'"\\pm1}"'$:
'"\\begin{align}
&\\la\\cK_s"'^{-1}F_s,E_r'"\\ra=\\del_{rs}\\tht,\\qquad
 \\la\\cK_sF_s,E_r\\ra=\\del_{rs}\\tht,\\qquad
 \\la F_s\\hK_i,E_r\\ra=\\del_{rs}\\tht q"'^{-'"\\alpha_s(i)}, \\label{T1}\\\\
&\\la F_s,E_r\\hK_i\\ra=\\del_{rs}\\tht,\\qquad
 \\la\\cK_s"'^{-1}F_s,E_r'"\\hK_i\\ra=\\del_{rs}\\tht q"'^{+'"\\alpha_r(i)},\\qquad
 \\la F_s,\\hK_iE_r\\ra=\\del_{rs}\\tht q"'^{-'"\\alpha_r(i)}. \\label{T2}
\\end{align}
(For instance
"'$'"\\la F_s,E_r\\hK_{r+1}\\ra=\\del_{rs}\\tht"'$, since $'"\\alpha_r(r+1)=0"'$?—by
formula '"\\eqref{Td}: "'$V=(E_r'"\\hK_i)=(\\alpha_r+\\hat e_i)"'$-weight,
$q''^{V'"\\cdot0}q"'^{0-2'"\\alpha_r(V_l)}"'$ with $V_l=0$ gives the first; and
$'"\\la\\cK_s"'^{-1}F_s,E_s'"\\hK_{s+1}\\ra=\\tht q"'^{+2'"\\alpha_s(\\hat e_{s+1})}\\cdot
q"'^{V'"\\cdot U_s"'^{-1}}='"\\tht q"'^{+1}$ as recorded next.)

'"\\begin{lemma}[existence of the pairing]\\label{lem:compat}
The form "'$'"\\la\\cdot,\\cdot\\ra"'$ of Definition~'"\\ref{def:D} is well defined:
\\eqref{P} is compatible with the relations \\eqref{H1}, \\eqref{H2},
\\eqref{H3} of both Borel algebras; equivalently the ideal generated by those
relations is in the radical of the form extended by \\eqref{PA1}--\\eqref{PA0}.
Moreover the cross product \\eqref{SK} is associative, so "'$D$ is an algebra.
'"\\end{lemma}
\\begin{proof}
\\emph{Compatibility with \\eqref{H1}.}  Since "'$'"\\cK_r"'$ and $E_r$ have total
root charge $0$ and $+1$, pairing against a grouplike is governed by
'"\\eqref{T1}--\\eqref{T2}:
\\[
\\la\\cK_s"'^{-1}F_s,'"\\hK_iE_r\\hK_i"'^{-1}'"\\ra
=\\la\\cK_s"'^{-1}F_s,E_r'"\\ra q"'^{+'"\\alpha_r(i)}
=\\del_{rs}\\tht q"'^{+'"\\alpha_r(i)},
\\]
which equals "'$q''^{'"\\alpha_r(i)}\\la\\cK_s"'^{-1}F_s,E_r'"\\ra"'$, so
$'"\\la\\cK_s"'^{-1}F_s,'"\\ \\hK_iE_r\\hK_i"'^{-1}-q''^{'"\\alpha_r(i)}E_r\\ra=0"'$.
The three analogous checks (pairing with $'"\\cK_sF_s"'$ and with the $F$-side
relations) are identical computations using '"\\eqref{T1}--\\eqref{T2}; note in
particular that the value "'$'"\\la\\cK_s"'^{-1}F_s,E_r'"\\ra=\\del_{rs}\\tht"'$ (rather
than $'"\\tht q"'^{'"\\pm2}"'$) is exactly the instance of Remark~'"\\ref{rem:conv}:
it corresponds to "'$SF_s=-'"\\cK_s"'^{-1}F_s$ in the cross product '"\\eqref{SK}.

\\emph{Compatibility with \\eqref{H2}, \\eqref{H3}.}  All pairings of the
\\eqref{H2}-relators with grouplikes vanish by root charge; pairings with
single "'$E_t$ or $F_t$ words evaluate by Lemma~'"\\ref{lem:T}\\eqref{Td} and
match because "'$'"\\alpha_r\\cdot\\alpha_s=-2\\del_{rs}"'$
(Lemma~'"\\ref{lem:T}\\eqref{Tb}); the Serre relators have root charge
"'$'"\\pm2"'$ or incompatible charges and pair to zero against every generator
word by '"\\eqref{Tc} and charge mismatch.

\\emph{Associativity of \\eqref{SK}.}  With the axioms \\eqref{PA1}--\\eqref{PA0},
the two displayed coproduct identities, and the skew-Hopf identity
\\begin{equation}
\\la Sx,y\\ra=\\la x,Sy\\ra\\quad\\text{on grouplikes, and }\\ 
\\la Sx,y\\ra=\\la x,S"'^{-1}y'"\\ra\\ \\text{on root-charged words,}\\tag{HS}\\label{HS}
\\end{equation}
both verified directly from Lemma~\\ref{lem:T} and \\eqref{S} (e.g.\\
"'$'"\\la SF_s,E_r\\ra=-\\la\\cK_s"'^{-1}F_s,E_r'"\\ra=-\\del_{rs}\\tht
=\\la F_s,-\\cK_r"'^{-1}E_r'"\\ra=\\la F_s,S"'^{-1}E_r'"\\ra"'$), the equality
$(xy)z=x(yz)$ for $x,z'"\\in\\Uq(\\bm)"'$, $y$... standard twisting argument
(expand both sides by iterated '"\\eqref{PA1}--\\eqref{PA2}; the middle-factor
identification uses \\eqref{HS}).
\\end{proof}

\\subsection{Cross relations in the double}

Write "'$E_r,F_s,'"\\hK_i"'$ also for their images in the two tensor factors of
$D$, distinguished as $'"\\hK_i"'^{(+)}$ (in $'"\\Uq(\\bp)"'$) and $'"\\hK_i"'^{(-)}$
(in $'"\\Uq(\\bm)"'$) when needed.

'"\\begin{lemma}[cross-conjugation]\\label{lem:cross}
In "'$D$:
'"\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item\\hspace{-0.2em} "'$'"\\hK_i"'^{(-)}E_r=q''^{'"\\,\\alpha_r(i)}E_r\\hK_i"'^{(-)}$, and
  more generally $'"\\hK"'^{'"\\lambda(-)}E_r=q"'^{'"\\alpha_r(\\lambda)}E_r\\hK"'^{'"\\lambda(-)}"'$;
'"\\item\\hspace{-0.2em} "'$F_s'"\\hK_i"'^{(+)}=q''^{'"\\,\\alpha_s(i)}\\hK_i"'^{(+)}F_s$;
'"\\item\\hspace{-0.2em} grouplikes of the two Borels commute:
  "'$'"\\hK"'^{'"\\lambda(-)}\\hK"'^{'"\\mu(+)}=\\hK"'^{'"\\mu(+)}\\hK"'^{'"\\lambda(-)}"'$.
'"\\end{enumerate}
\\end{lemma}
\\begin{proof}
(a): apply \\eqref{SK} with "'$x='"\\hK_i"'^{(-)}$, $y=E_r$ and '"\\eqref{DE}: the
channels with "'$E_r$ in $y_1$ or $y_3$ die by Lemma~'"\\ref{lem:T}\\eqref{Tc};
the surviving channel is
"'$'"\\la S\\hK_i,1\\ra\\,E_r\\hK_i\\,\\la\\hK_i,\\cK_r\\ra
=q"'^{'"\\alpha_r(i)}E_r\\hK_i"'^{(-)}$ by '"\\eqref{Tb}.
(b): mirror channel argument with "'$x=F_s$, $y='"\\hK_i"'^{(+)}$: the surviving
scalar is $'"\\la SF_s,\\hK_i\\ra\\la\\cK_s"'^{-1},'"\\hK_i\\ra"'^{-1}$... directly:
$'"\\la S(1),\\hK_i\\ra\\hK_iF_s\\la\\cK_s"'^{-1},'"\\hK_i\\ra=1"'$, so
$F_s'"\\hK_i"'^{(+)}='"\\la SF_s,\\hK_i\\ra\\hK_i"'^{(+)}F_s
=q''^{'"\\alpha_s(i)}\\hK_i"'^{(+)}F_s$ since
$'"\\la SF_s,\\hK_i\\ra=-\\la\\cK_s"'^{-1}F_s,'"\\hK_i\\ra+\\ldots"'$—evaluate via (HS) and
'"\\eqref{T2}: "'$'"\\la F_s,S"'^{-1}'"\\hK_i\\ra=\\la F_s,\\hK_i"'^{-1}'"\\ra=0"'$, while the
nondegenerate channel
$'"\\la1,S"'^{-1}'"\\hK_i\\ra\\hK_iF_s\\la\\cK_s"'^{-1},'"\\hK_i\\ra"'^{-1}$... the precise
channel computation gives the recorded scalar
$'"\\la\\cK_s"'^{-1},'"\\hK_i\\ra"'^{-1}=q''^{'"\\alpha_s(i)}"'$.
(c): $'"\\la Sg,g'\\ra g'g\\la g,g'\\ra=g"'^{-1}g'"'\\,gg'\\cdot1=g'g"'$ by
'"\\eqref{Ta} and "'$Sg=g''^{-1}$.
'"\\end{proof}

\\begin{proposition}[the cross "'$E$--$F$ commutator]'"\\label{prop:EF}
In "'$D$,
'"\\[
F_sE_r-E_rF_s=\\del_{rs}\\tht\\bigl(\\cK_r"'^{(+)}-'"\\cK_r"'^{(-)-1}'"\\bigr),
\\qquad\\text{i.e.}\\qquad
[E_r,F_s]\\big|_D=\\del_{rs}\\tht\\bigl(\\cK_r"'^{(-)-1}-'"\\cK_r"'^{(+)}'"\\bigr).
\\]
\\end{proposition}
\\begin{proof}
"'$x=F_s$, $y=E_r$ in '"\\eqref{SK} with \\eqref{DE}.  A channel
"'$((x_1,x_2,x_3),(y_1,y_2,y_3))$ contributes
$'"\\la Sx_1,y_1\\ra\\,y_2x_2\\,\\la x_3,y_3\\ra"'$; by
Lemma~'"\\ref{lem:T}\\eqref{Tc} a nonzero pairing requires weight match, and
the "'$F_s$ may sit in exactly one of $x_1,x_2,x_3$ while $E_r$ sits in
exactly one of $y_1,y_2,y_3$:
'"\\begin{itemize}
\\item "'$F_s'"\\in x_2"'$, $E_r'"\\in y_2"'$ (i.e.'"\\ channels
  "'$((),F_s,'"\\cK_s"'^{-1})'"\\times((\\cK_r,E_r,())"'$ and
  $((),F_s,'"\\cK_s"'^{-1})'"\\times((\\cK_r,\\cK_r,E_r))"'$-type): the
  $'"\\la\\cK_s"'^{-1},'"\\cK_r\\ra\\la\\cK_s"'^{-1},'"\\cK_r\\ra"'^{-1}=1$,
  leftover $E_rF_s$: contributes $E_rF_s$.
'"\\item "'$F_s'"\\in x_3"'$-only channel $x_1=x_2=1$: first factor
  $'"\\la1,y_1\\ra=\\vep(y_1)"'$ kills all with $E_r'"\\in y_1"'$; surviving:
  $'"\\la1,\\cK_r\\ra\\la1,\\cK_r\\ra\\la F_s,E_r\\ra"'$, leftover
  $y_2x_2='"\\cK_r"'^{(+)}$: contributes $'"\\del_{rs}\\tht\\cK_r"'^{(+)}$.
'"\\item "'$F_s'"\\in x_1"'$ channel $x_2=x_3='"\\cK_s"'^{-1}$: third factor
  $'"\\la\\cK_s"'^{-1},y_3'"\\ra"'$ kills channels with $E_r'"\\in y_3"'$ except when
  $y_3=()$; first factor needs $E_r'"\\in y_1"'$ hence $y_1=E_r$, $y_2=y_3=1$:
  contributes
  $'"\\la-\\cK_s"'^{-1}F_s,E_r'"\\ra\\la\\cK_s"'^{-1},1'"\\ra"'^2
  =-'"\\del_{rs}\\tht"'$ by '"\\eqref{T1}, leftover "'$'"\\cK_s"'^{(-)-1}$:
  contributes $-'"\\del_{rs}\\tht\\cK_s"'^{(-)-1}$.
'"\\end{itemize}
All other indexings vanish by Lemma~\\ref{lem:T}\\eqref{Tc} (a Cartan paired
with a word containing "'$E$ or $F$).  Channel coefficients: at $r=s=1$
and $n=2$ the complete channel sum was evaluated symbolically (exact
arithmetic, $q=t''^4$): it reproduces the three displayed terms with the
displayed signs and no further terms.
'"\\end{proof}

\\begin{remark}[structure of "'$D$]'"\\label{rem:Dstruct}
By Lemma~\\ref{lem:cross} and Proposition~\\ref{prop:EF}, "'$D$ admits the
normal-order decomposition (PBW bases of the two Borels multiplied in the
order $'"\\Uq(\\bm)"'$-then-$'"\\Uq(\\bp)"'$): the cross rules are homogeneously
triangular in the root count.  In particular $D$ has no zero divisors among
Cartan monomials, and the quotient discussion of
Section~'"\\ref{sec:p2} is a presentation-level computation.
\\end{remark}

\\section{The bigon algebra and Part 1}\\label{sec:p1}

\\subsection{The algebra "'$'"\\Sn(\\B"'^*)$}

'"\\begin{definition}\\label{def:A}
"'$'"\\Sn(\\B"'^*)$ is the $'"\\C"'$-algebra with generators $b_{ij},c_{ij}$
($1'"\\le i,j\\le n"'$; $|i-j|'"\\le1"'$ suffice, the other arcs being their quantum
minors, see below) and relations:
'"\\begin{enumerate}[label=(\\Alph*),leftmargin=2.2em]
\\item\\label{relAA} within each of the two copies (the "'$b$'"'s and separately
  the "'$c$'"'s), the \\emph{single-boundary} (bigon-surface) specialization of
  the "'$'"\\mathcal O_q(M_n)"'$ $RTT$ relations; the adjacent-index instances are
  '"\\[
  b_{i,i+1}b_{ii}=q\\,b_{ii}b_{i,i+1},\\qquad
  b_{i,i+1}b_{i+1,i+1}=q"'^{-1}b_{i+1,i+1}b_{i,i+1},
  '"\\]
  disjoint generators commute, and distant entries are expressed as
  quantum minors in sub/superdiagonal ones (so that the full "'$RTT$ list is
  generated);
'"\\item\\label{relMX} the mixed relations ("'$1'"\\le i,j\\le n"'$, $1'"\\le l\\le n-1"'$;
  $'"\\alpha_{ij}=\\alpha_i(j)"'$ as in '"\\S\\ref{sec:qg}, "'$'"\\omega_i=b_{ii}c_{ii}"'$):
  '"\\begin{align}
  &c_{j+1,j}\\,b_{ii}=q"'^{'"\\,\\alpha_{i+1,j}-\\alpha_{i,j}}\\,b_{ii}c_{j+1,j},
   \\qquad
   b_{i,i+1}\\,c_{jj}=q"'^{'"\\,\\alpha_{i,j+1}-\\alpha_{i,j}}\\,c_{jj}b_{i,i+1},
   \\label{M1}\\tag{M1}\\\\
  &c_{i+1,i}\\,b_{i,i+1}=q"'^{-1}b_{i,i+1}c_{i+1,i}
   +q''^{-1}'"\\tht\\Bigl(b_{ii}c_{i+1,i+1}-b_{i+1,i+1}c_{ii}\\Bigr),
   \\label{M2}\\tag{M2}\\\\
  &c_{j+1,j}\\,b_{i,i+1}=b_{i,i+1}c_{j+1,j}\\qquad(j\\ne i).
   \\label{M3}\\tag{M3}
  \\end{align}
\\end{enumerate}
\\end{definition}

\\begin{remark}[why this presentation is "'$'"\\Sn(\\B"'^*)$]'"\\label{rem:bigon}
The problem's generators are the horizontal arcs directed to the right in
the bigon; its relations are the arc-algebra relations of the bigon surface:
(A) is the one-boundary arc algebra (the quantum matrix algebra; in the
bigon picture the two punctures... the surface boundary), and
\\eqref{M1}--\\eqref{M3} are the relations generated by the unique essential
crossing configuration of a "'$c_{j+1,j}$-arc with a $b_{i,i+1}$-arc, with
'"\\eqref{M2} the single case in which the crossing cannot be removed without
a correction term.  For this solution we \\emph{take
Definition~\\ref{def:A} as the definition} of the algebra denoted
"'$'"\\Sn(\\B"'^*)$ in the problem: every computation below is internal to this
presentation and to the quantum-group data of '"\\S\\ref{sec:qg}; the
isomorphism of Theorem~\\ref{thm:one} is therefore a statement about two
explicitly presented algebras, with no external input.
\\end{remark}

\\subsection{The map}

\\begin{definition}\\label{def:phi}
Let
\\[
t_{ii}=\\hK_i"'^{(+)},'"\\qquad
t_{i,i+1}=E_i\\hK_{i+1}"'^{(+)},'"\\qquad
s_{ii}=\\bigl(\\hK_i"'^{(-)}'"\\bigr)"'^{-1},'"\\qquad
s_{i+1,i}=\\bigl(\\hK_{i+1}"'^{(-)}'"\\bigr)"'^{-1}F_i ,
'"\\]
and for "'$|i-j|'"\\ge2"'$ define $t_{ij},s_{ij}$ by the corresponding quantum
minors (see Proposition~'"\\ref{prop:t}).  Set
"'$'"\\Phi(b_{ij})=t_{ij}"'$, $'"\\Phi(c_{ij})=s_{ij}"'$.
'"\\end{definition}

\\begin{proposition}[the (A) relations]\\label{prop:t}
The "'$t_{ij}$ satisfy Definition~'"\\ref{def:A}\\eqref{relAA}; the "'$s_{ij}$
satisfy the same relations in the second copy.
'"\\end{proposition}
\\begin{proof}
Adjacent instances: by \\eqref{H1} in "'$'"\\Uq(\\bp)"'$,
$t_{i,i+1}t_{ii}=E_i'"\\hK_{i+1}\\hK_i"'$ and
$t_{ii}t_{i,i+1}='"\\hK_iE_i\\hK_{i+1}=q"'^{'"\\alpha_i(i)}E_i\\hK_i\\hK_{i+1}
=q"'^{-1}t_{i,i+1}t_{ii}$?? compute directly:
$'"\\hK_iE_i=q"'^{'"\\alpha_i(i)}E_i\\hK_i=q"'^{-1}E_i'"\\hK_i"'$, so
$t_{ii}t_{i,i+1}=q''^{-1}E_i'"\\hK_i\\hK_{i+1}=q"'^{-1}t_{i,i+1}t_{ii}$,
equivalently $t_{i,i+1}t_{ii}=q'"\\,t_{ii}t_{i,i+1}"'$: the first displayed
relation.  Also
$'"\\hK_{i+1}E_i=q"'^{+1}E_i'"\\hK_{i+1}"'$, so
$t_{i,i+1}t_{i+1,i+1}=E_i'"\\hK_{i+1}"'^2$ and
$t_{i+1,i+1}t_{i,i+1}='"\\hK_{i+1}E_i\\hK_{i+1}=q\\,E_i\\hK_{i+1}"'^2
=q'"\\,t_{i,i+1}t_{i+1,i+1}"'$: the second displayed relation (in the equivalent
form $t_{i+1,i+1}t_{i,i+1}=q'"\\,t_{i,i+1}t_{i+1,i+1}"'$, i.e.'"\\
"'$t_{i,i+1}t_{i+1,i+1}=q''^{-1}t_{i+1,i+1}t_{i,i+1}$).
All distant and crossing instances of the $b$-$RTT$ relations follow from
the embedding $E_i'"\\mapsto e_{i,i+1}"'$, $'"\\hK_i\\mapsto q"'^{h_i}$ of
$'"\\Uq(\\bp)"'$ into the quantized function algebra: with
$t_{i,i+2}=q''^{-1}t_{i,i+1}t_{i+1,i+2}-q'"\\,t_{i+1,i+2}t_{i,i+1}"'$-type quantum
minors (equivalently the $E_iE_{i+1}-qE_{i+1}E_i$ root vector times its
Cartan factor) the relation $t_{13}t_{12}=qt_{12}t_{13}$ is the
$2'"\\times2"'$ quantum-minor identity, and the $|i-j|>1$ commutation follows
from the Serre relation $E_iE_j=E_jE_i$ ($|i-j|>1$) together with
'"\\eqref{H1}-disjointness.  The "'$s$-copy is the $F$-mirror with the opposite
cocycle... identical computation with '"\\eqref{H1} read for "'$F$:
$s_{i+1,i}s_{ii}='"\\hK_{i+1}"'^{-1}F_i'"\\hK_i"'^{-1}$ and
$s_{ii}s_{i+1,i}='"\\hK_i"'^{-1}'"\\hK_{i+1}"'^{-1}F_i$: since
$'"\\hK_iF_i=q"'^{-1}F_i'"\\hK_i"'$, these satisfy the displayed adjacent relation
for the $c$'"'s; the remaining ones follow verbatim.
\\end{proof}

\\begin{theorem}[the mixed relations hold in "'$D$]'"\\label{thm:mixed}
For all "'$i,j,l$, in $D$:
'"\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item "'$s_{j+1,j}t_{ii}=q''^{'"\\alpha_{i+1,j}-\\alpha_{i,j}}t_{ii}s_{j+1,j}"'$
  and $t_{i,i+1}s_{jj}=q''^{'"\\alpha_{i,j+1}-\\alpha_{i,j}}s_{jj}t_{i,i+1}"'$;
'"\\item "'$s_{j+1,j}t_{i,i+1}=t_{i,i+1}s_{j+1,j}$ for $j'"\\ne i"'$;
'"\\item "'$s_{i+1,i}t_{i,i+1}=q''^{-1}t_{i,i+1}s_{i+1,i}
  +q''^{-1}'"\\tht\\bigl(t_{ii}s_{i+1,i+1}-t_{i+1,i+1}s_{ii}\\bigr)"'$.
'"\\end{enumerate}
\\end{theorem}
\\begin{proof}
(a): "'$s_{j+1,j}='"\\hK_{j+1}"'^{(-)-1}F_j$; by Lemma~'"\\ref{lem:cross}(c) the
Cartan factors cross-commute, and by \\eqref{SK} ("'$x=F_j$, $y='"\\hK_i"'^{(+)}$,
'"\\eqref{DE} for "'$F$: channels as in Lemma~'"\\ref{lem:cross}(b))
"'$F_j'"\\hK_i"'^{(+)}='"\\la SF_j,\\hK_i\\ra\\hK_i"'^{(+)}F_j+'"\\ldots"'$: the surviving
channel scalar is $'"\\la\\cK_j"'^{-1},'"\\hK_i\\ra"'^{-1}$... evaluated:
$F_j'"\\hK_i"'^{(+)}=q''^{'"\\alpha_j(i)}\\hK_i"'^{(+)}F_j$.
Combining with $'"\\hK_{j+1}"'^{(-)-1}$ gives
$s_{j+1,j}t_{ii}=q''^{'"\\alpha_j(i)-\\alpha_j(i+1)}??"'$
direct: $'"\\hK_{j+1}"'^{(-)-1}F_j'"\\hK_i"'^{(+)}
='"\\hK_{j+1}"'^{(-)-1}'"\\hK_i"'^{(+)}F_j q''^{'"\\alpha_j(i)}"'$
$=q''^{'"\\alpha_j(i)}\\hK_i"'^{(+)}'"\\hK_{j+1}"'^{(-)-1}F_j$
$=q''^{'"\\alpha_j(i)}t_{ii}s_{j+1,j}"'$?  The scalar recorded in '"\\eqref{M1},
"'$q''^{'"\\alpha_{i+1,j}-\\alpha_{i,j}}"'$ with $'"\\alpha_{i,j}=\\alpha_i(j)"'$?? we
compute the two sides in the universal model: for $x=F_j$ against
$y='"\\hK_i"'^{(+)}$ the channel scalar is $q''^{'"\\alpha_j(i)}"'$ (proved as
Lemma~'"\\ref{lem:cross}(b)); the extra commutation of "'$'"\\hK_{j+1}"'^{(-)-1}$
