\\begin{proof}
"'$'"\\Omega_i"'$ is grouplike in each copy, so it commutes with all grouplikes
(same copy by commutativity, opposite copy by
Lemma~'"\\ref{lem:cross}(c)).  Conjugation on "'$E_r$: by '"\\eqref{H1},
"'$'"\\hK_i"'^{(+)}E_r'"\\hK_i"'^{(+)-1}=q''^{'"\\alpha_r(i)}E_r"'$; by
Lemma~'"\\ref{lem:cross}(a),
"'$'"\\hK_i"'^{(-)-1}E_r=q''^{-'"\\alpha_r(i)}E_r\\hK_i"'^{(-)-1}$, i.e.'"\\
"'$'"\\hK_i"'^{(-)-1}E_r'"\\hK_i"'^{(-)}=q''^{-'"\\alpha_r(i)}E_r"'$; the exponents cancel,
so $'"\\Omega_iE_r\\Omega_i"'^{-1}=E_r$.  Conjugation on $F_s$: by '"\\eqref{H1},
"'$'"\\hK_i"'^{(-)-1}F_s'"\\hK_i"'^{(-)}=q''^{+'"\\alpha_s(i)}F_s"'$; by
Lemma~'"\\ref{lem:cross}(b), "'$F_s'"\\hK_i"'^{(+)}=q''^{'"\\alpha_s(i)}\\hK_i"'^{(+)}F_s$,
i.e.'"\\ "'$'"\\hK_i"'^{(+)}F_s'"\\hK_i"'^{(+)-1}=q''^{-'"\\alpha_s(i)}F_s"'$; again the
exponents cancel.  The claim for $'"\\omega_i"'$ follows by injectivity of
$'"\\Phi"'$ (Theorem~'"\\ref{thm:one}).
\\end{proof}

\\begin{lemma}[PBW scale factors]\\label{lem:pbw}
"'$'"\\Sn(\\B"'^*)'"\\cong D\\otimes\\C[\\omega_1"'^{'"\\pm1},\\dots,\\omega_n"'^{'"\\pm1}]"'$ as
algebras, where the $'"\\omega_i"'$ are identified with
$'"\\Omega_i\\in D"'$ times an independent Laurent variable; precisely, the
subalgebra generated by the $'"\\omega_i"'$ is a Laurent polynomial algebra in
$n$ free central generators, and multiplication
$'"\\Sn(\\B"'^*)_0'"\\otimes\\C[\\omega"'^{'"\\pm}]\\to\\Sn(\\B"'^*)$ is an isomorphism, where
$'"\\Sn(\\B"'^*)_0$ is the subalgebra generated by $t_{ij},s_{ij}$ with the
$'"\\omega_i"'$ split off.
