SEC3 = r'''
\\section{Part 2: the quotient}\\label{sec:p2}

Let "'$'"\\omega_i=b_{ii}c_{ii}\\in\\Sn(\\B"'^*)$ and
$'"\\Omega_i=\\Phi(\\omega_i)=t_{ii}s_{ii}=\\hK_i"'^{(+)}'"\\hK_i"'^{(-)-1}'"\\in D"'$.

'"\\begin{lemma}[central loops]\\label{lem:loops}
Each "'$'"\\Omega_i"'$ is central in $D$ and each $'"\\omega_i"'$ is central in
$'"\\Sn(\\B"'^*)$.
'"\\end{lemma}
\\begin{proof}
"'$'"\\Omega_i"'$ commutes with all grouplikes ($'"\\Z"'^{2n}$ abelian;
Lemma~'"\\ref{lem:cross}(c)).  Adjunction on the root letters: by
\\eqref{H1}, "'$'"\\hK_i"'^{(+)}E_r'"\\hK_i"'^{(+)-1}=q''^{'"\\alpha_r(i)}E_r"'$; by
Lemma~'"\\ref{lem:cross}(a) applied to "'$'"\\hK_i"'^{(-)-1}$,
$'"\\hK_i"'^{(-)-1}E_r'"\\hK_i"'^{(-)}=q''^{-'"\\alpha_r(i)}E_r"'$; hence
$'"\\Omega_iE_r=E_r\\Omega_i"'$ with total scalar
$q''^{'"\\alpha_r(i)-\\alpha_r(i)}=1"'$.  By Lemma~'"\\ref{lem:cross}(b),
"'$'"\\hK_i"'^{(+)}F_s'"\\hK_i"'^{(+)-1}=q''^{-'"\\alpha_s(i)}F_s"'$; by '"\\eqref{H1} in
"'$'"\\Uq(\\bm)"'$, $'"\\hK_i"'^{(-)-1}F_s'"\\hK_i"'^{(-)}=q''^{+'"\\alpha_s(i)}F_s"'$; hence
$'"\\Omega_iF_s=F_s\\Omega_i"'$.  (Both cancellations were also computed in
the exact model of $D$ at $n=2$.)  The second claim follows by
injectivity of $'"\\Phi"'$.
'"\\end{proof}

\\begin{lemma}[splitting]\\label{lem:split}
"'$'"\\Omega_1,\\dots,\\Omega_n"'$ are algebraically independent and
$D'"\\cong D"'^0'"\\otimes\\C[\\Omega_1"'^{'"\\pm1},\\dots,\\Omega_n"'^{'"\\pm1}]"'$, where
$D''^0='"\\la E_r,F_s,\\hK_i"'^{(+)}'"\\ra"'$ (isomorphic to $D$ itself via
$'"\\hK_i"'^{(-)}'"\\leftrightarrow\\hK_i"'^{(+)}'"\\Omega_i"'^{-1}$).
'"\\end{lemma}
\\begin{proof}
Substitute "'$'"\\hK_i"'^{(-)}='"\\hK_i"'^{(+)}'"\\Omega_i"'^{-1}$ in the PBW basis
$F''^{'"\\mathbf a}\\hK"'^{(-)'"\\lambda}\\hK"'^{(+)'"\\mu}E"'^{'"\\mathbf b}"'$: bijection
with (PBW monomials of $D''^0$)$'"\\times\\Omega"'^{-'"\\lambda}"'$; the defining
relations all preserve the $'"\\hK"'^{(-)}$-degree, so the splitting is
multiplicative.  Independence:
the $'"\\Omega"'$-exponent lattice is
$'"\\ker(\\Z"'^{2n}'"\\to\\Z"'^n,'"\\ (\\lambda,\\mu)\\mapsto\\lambda+\\mu)\\cong\\Z"'^n$.
'"\\end{proof}

\\begin{lemma}[diagonal quotient]\\label{lem:diag}
For "'$J=('"\\hK_i"'^{(+)}-'"\\hK_i"'^{(-)})_{1'"\\le i\\le n}\\subset D"'$,
$D/J'"\\cong H"'$ via $E_r'"\\mapsto E_r"'$, $F_s'"\\mapsto F_s"'$,
$'"\\hK_i"'^{('"\\pm)}\\mapsto\\hK_i"'$.
'"\\end{lemma}
\\begin{proof}
Imposing "'$'"\\hK_i"'^{(+)}='"\\hK_i"'^{(-)}$ in the presentation of $D$:
Lemma~'"\\ref{lem:cross}(a),(b) become copies of \\eqref{H1} with the
same exponents as the internal ones, Lemma~\\ref{lem:cross}(c) becomes
the abelianness of the "'$'"\\hK_i"'$, and Proposition~'"\\ref{prop:EF} becomes
\\[
F_sE_r-E_rF_s=\\del_{rs}\\tht\\bigl(\\cK_r-\\cK_r"'^{-1}'"\\bigr),
\\]
which is \\eqref{H2}.  Together with the internal \\eqref{H1} and
\\eqref{H3} in "'$E$ and $F$, the relations obtained are precisely those
of Definition~'"\\ref{def:H}; PBW monomials specialize bijectively, so
the natural maps are inverse isomorphisms and no further relations
appear.
\\end{proof}

\\begin{theorem}[Part 2]\\label{thm:two}
"'$'"\\Sn(\\B"'^*)/I'"\\cong H=\\Uq"'^{ext}('"\\mathfrak{sl}(n))"'$.
