SEC1 = r'''
\\section{Quantum-group data and the double}\\label{sec:qg}

\\subsection{The simply-connected quantum group}

Set
\\[
a_{ij}=\\tfrac1n-\\del_{ij}\\ (1\\le i,j\\le n),\\qquad
\\alpha_r(i)=a_{ir}-a_{i,r+1}=\\del_{i,r+1}-\\del_{i,r},\\qquad
\\tht=(q"'^{-1}-q)''^{-1}.
'"\\]
Then "'$a_{ij}=a_{ji}$, $'"\\sum_i\\alpha_r(i)=0"'$, $'"\\alpha_r(r)=-1"'$,
$'"\\alpha_r(r+1)=+1"'$, $'"\\alpha_r(i)=0"'$ for $i'"\\notin\\{r,r+1\\}"'$.  For
$'"\\lambda,\\mu\\in\\Z"'^n$ write
$'"\\lambda\\cdot\\mu=\\sum_{i,j}\\lambda_i\\mu_ja_{ij}"'$ (symmetric),
$'"\\hK"'^'"\\lambda=\\prod_i\\hK_i"'^{'"\\lambda_i}"'$, and identify $'"\\alpha_r"'$ with
its coordinate vector; then, since the $'"\\tfrac1n"'$-part of $a_{ij}$
drops out against $'"\\sum_i\\alpha_r(i)=0"'$,
'"\\begin{equation}
\\alpha_r\\cdot\\alpha_s=-\\alpha_r(s)=-2\\del_{rs},
\\qquad
\\alpha_r\\cdot e_i=\\alpha_r(i).
\\label{A2}\\tag{A2}
\\end{equation}

\\begin{definition}\\label{def:H}
"'$H='"\\Uq"'^{ext}('"\\mathfrak{sl}(n))"'$ is generated by abelian grouplikes
$'"\\hK_i"'^{'"\\pm1}"'$ ($1'"\\le i\\le n"'$) and $E_r,F_r$ ($1'"\\le r\\le n-1"'$) with
'"\\begin{align}
\\hK_iE_r\\hK_i"'^{-1}&=q''^{'"\\alpha_r(i)}E_r,\\qquad
\\hK_iF_r\\hK_i"'^{-1}=q''^{-'"\\alpha_r(i)}F_r,\\label{H1}\\tag{H1}\\\\
E_rF_s-F_sE_r&=\\del_{rs}\\,\\tht\\bigl(\\cK_r"'^{-1}-'"\\cK_r\\bigr)
\\qquad(\\cK_r\\coloneqq\\hK_r\\hK_{r+1}"'^{-1}),'"\\label{H2}\\tag{H2}
\\end{align}
and the quantum Serre relations
\\begin{equation}
E_r"'^2E_s-(q+q''^{-1})E_rE_sE_r+E_sE_r''^2=0'"\\ \\ (|r-s|=1),\\qquad
E_rE_s=E_sE_r\\ \\ (|r-s|>1),\\label{H3}\\tag{H3}
\\end{equation}
with their "'$F$-analogues.  Hopf algebra structure:
'"\\begin{equation}
\\Delta\\hK_i=\\hK_i\\otimes\\hK_i,\\quad
\\Delta E_r=E_r\\otimes1+\\cK_r\\otimes E_r,\\quad
\\Delta F_r=F_r\\otimes\\cK_r"'^{-1}+1'"\\otimes F_r,\\label{C}\\tag{C}
\\end{equation}
"'$'"\\vep(\\hK_i)=1"'$, $'"\\vep(E_r)=\\vep(F_r)=0"'$, and hence
'"\\begin{equation}
S\\hK_i=\\hK_i"'^{-1},'"\\quad SE_r=-\\cK_r"'^{-1}E_r,'"\\quad
SF_r=-\\cK_r"'^{-1}F_r,'"\\quad S"'^{-1}F_r=-F_r'"\\cK_r .\\label{S}\\tag{S}
\\end{equation}
The Borel subalgebras are "'$'"\\Uq(\\bp)=\\la\\hK_i,E_r\\ra"'$ and
$'"\\Uq(\\bm)=\\la\\hK_i,F_r\\ra"'$.
'"\\end{definition}

\\begin{remark}[convention pin]\\label{rem:conv}
Our pairing axioms pair "'$F$ (left, from $'"\\Uq(\\bm)"'$) against $E$
(right): $'"\\la F_s,E_r\\ra=\\del_{rs}\\tht"'$, the symmetric reading of the
second value of '"\\eqref{P0}.  With \\eqref{C} fixed, the axioms
\\eqref{PA} together with \\eqref{H1} \\emph{force}
"'$'"\\la\\cK_s"'^{-1}F_s,E_r'"\\ra=\\del_{rs}\\tht"'$ (no extra $q''^{'"\\pm2}"'$; see
Lemma~'"\\ref{lem:T}\\eqref{Td} and Lemma~\\ref{lem:compat}), equivalently
- via the cross product - the antipode value "'$SF_s=-'"\\cK_s"'^{-1}F_s$ of
'"\\eqref{S}.  This is the Tanisaki convention, and it is the unique
choice compatible with \\eqref{P0}, \\eqref{C}, \\eqref{H1} and the
diagonal quotient of Part 2: the alternative "'$SF=-F'"\\cK"'$ changes the
coefficients of Proposition~'"\\ref{prop:EF} and is detected immediately
by the exact computation (Remark~\\ref{rem:verify}).
\\end{remark}

\\subsection{The skew pairing and the double}

Write "'$'"\\Delta"'^2(x)=('"\\Delta\\otimes\\mathrm{id})\\Delta(x)
=x_1\\otimes x_2\\otimes x_3"'$; from '"\\eqref{C},
\\begin{align}
\\Delta"'^2(E_r)&=E_r'"\\otimes1\\otimes1+\\cK_r\\otimes E_r\\otimes1
  +\\cK_r\\otimes\\cK_r\\otimes E_r,\\label{DE}\\tag{"'$'"\\Delta"'^2$}'"\\\\
\\Delta"'^2(F_r)&=F_r'"\\otimes\\cK_s"'^{-1}'"\\otimes\\cK_s"'^{-1}
  +1'"\\otimes F_s\\otimes\\cK_s"'^{-1}+1'"\\otimes1\\otimes F_s .\\notag
\\end{align}

\\begin{definition}\\label{def:D}
"'$'"\\la\\cdot,\\cdot\\ra:\\Uq(\\bm)\\times\\Uq(\\bp)\\to\\C"'$ is the bilinear form
uniquely determined by
'"\\begin{align}
\\la u,yz\\ra&=\\la u_1,z\\ra\\la u_2,y\\ra,\\qquad
 \\la uv,z\\ra=\\la u,z_1\\ra\\la v,z_2\\ra,\\label{PA}\\tag{PA}\\\\
\\la1,y\\ra&=\\vep(y),\\qquad\\la u,1\\ra=\\vep(u),\\notag\\\\
&\\la\\hK_i,\\hK_j\\ra=q"'^{a_{ij}},'"\\qquad
\\la F_s,E_r\\ra=\\del_{rs}\\tht,\\qquad
\\la\\hK_i,E_r\\ra=\\la F_s,\\hK_j\\ra=0 ;\\label{P}\\tag{P}
\\end{align}
its existence is Lemma~\\ref{lem:compat}.  The \\emph{generalized quantum
double} "'$D='"\\Uq(\\bm)\\ptn\\Uq(\\bp)"'$ is the algebra on
$'"\\Uq(\\bm)\\otimes\\Uq(\\bp)"'$ with the two Borels as subalgebras and the
cross multiplication
'"\\begin{equation}
x\\,y=\\la Sx_1,y_1\\ra\\;y_2x_2\\;\\la x_3,y_3\\ra
\\qquad(x\\in\\Uq(\\bm),\\ y\\in\\Uq(\\bp)).\\label{SK}\\tag{SK}
\\end{equation}
\\end{definition}

\\begin{lemma}[pairing table]\\label{lem:T}
\\begin{enumerate}[label=(\\alph*),leftmargin=2.2em]
\\item\\label{Ta} "'$'"\\la\\hK"'^'"\\lambda,\\hK"'^'"\\mu\\ra=q"'^{'"\\lambda\\cdot\\mu}
  =q"'^{'"\\mu\\cdot\\lambda}"'$; in particular, by '"\\eqref{A2},
  "'$'"\\la\\cK_s"'^{'"\\pm1},\\hK_i\\ra=q"'^{'"\\mp\\alpha_s(i)}"'$ and
  $'"\\la\\cK_s"'^{'"\\pm1},\\cK_r\\ra=q"'^{'"\\mp2\\del_{rs}}"'$.
'"\\item\\label{Tc} a pairing between a grouplike and a word of nonzero
  root charge ("'$'"\\deg E=1,\\deg F=-1,\\deg\\hK=0"'$) vanishes.
'"\\item\\label{Td} For grouplike words
  "'$u='"\\hK"'^{'"\\lambda_-}F_s\\hK"'^{'"\\lambda_+}"'$ and
  $v='"\\hK"'^{'"\\mu_-}E_r\\hK"'^{'"\\mu_+}"'$ (totals
  $'"\\lambda=\\lambda_-+\\lambda_+"'$, $'"\\mu=\\mu_-+\\mu_+"'$),
  '"\\[
  \\la u,v\\ra=\\del_{rs}\\,\\tht\\,
  q"'^{'"\\,\\lambda\\cdot\\mu}\\;q"'^{'"\\,2\\alpha_s(\\lambda_+)-2\\alpha_s(\\mu_-)}
  \\]
  where in the exponent we have written "'$'"\\alpha_s"'$ for the relevant
  simple root (at $r'"\\ne s"'$ the value is $0$ anyway).  The instances
  used below:
  '"\\begin{align*}
  &\\la\\cK_s"'^{-1}F_s,E_r'"\\ra=\\del_{rs}\\tht,\\qquad
   \\la F_s,E_r\\hK_i\\ra=\\del_{rs}\\tht,\\qquad
   \\la\\cK_s"'^{-1}F_s,E_r'"\\hK_i\\ra=\\del_{rs}\\tht q"'^{2'"\\alpha_s(i)},\\\\
  &\\la F_s,\\hK_iE_r\\ra=\\del_{rs}\\tht q"'^{-2'"\\alpha_s(i)},\\qquad
   \\la F_s\\hK_i,E_r\\ra=\\del_{rs}\\tht,\\qquad
   \\la\\cK_sF_s,E_r\\ra=\\del_{rs}\\tht .
  \\end{align*}
\\end{enumerate}
\\end{lemma}
\\begin{proof}
(a): "'$'"\\Delta(\\hK"'^'"\\lambda)=\\hK"'^'"\\lambda\\otimes\\hK"'^'"\\lambda"'$ and the two
axioms of '"\\eqref{PA} give bimultiplicativity; base case \\eqref{P};
then \\eqref{A2} for the values on "'$'"\\cK"'$.  (c): root-charge induction
through '"\\eqref{PA}.  (d): expand by \\eqref{PA}, moving one grouplike
factor at a time across the root letter.  A \\emph{right-of-F} factor
"'$'"\\hK"'^{'"\\lambda_+}"'$: pairing out $F_s$ through the first axiom with
$'"\\Delta(F_s)=F_s\\otimes\\cK_s"'^{-1}+1'"\\otimes F_s"'$ and the
$'"\\Delta"'^2(E)$-channels of $v$: the channel in which the
$'"\\hK"'^{'"\\lambda_+}"'$ pairs against the $E$-slot dies by (c); the
surviving channels pair it against the Cartan slots of the
$E$-coproduct via $'"\\la\\cK_s"'^{-1}'"\\hK"'^{'"\\lambda_+}\\cdot,\\cdot\\ra"'$ and the
Cartan factor
$'"\\la\\hK"'^{'"\\lambda_+},\\cK_r\\ra=q"'^{-'"\\alpha_s(\\lambda_+)\\cdot(-1)}"'$-type
powers, whose product over the two accessible channels is
$q''^{2'"\\alpha_s(\\lambda_+)}"'$; a '"\\emph{left-of-E} factor is the mirror
(parameter "'$'"\\mu_-"'$) with the opposite sign, giving
$q''^{-2'"\\alpha_s(\\mu_-)}"'$; factors on the outer sides contribute their
$a$-pairing $'"\\lambda_-\\cdot\\mu_+"'$ etc., totaling
$'"\\lambda\\cdot\\mu"'$ by bimultiplicativity (a).  For the six displayed
instances each channel expansion has exactly one or two nonzero
channels, each a product of at most three elementary pairings; e.g.
'"\\[
