    return {k: v for k, v in out.items() if not v.iszero()}
def nE(w): return sum(1 for s in w if s == 'E')
def nF(w): return sum(1 for s in w if s == 'F')

# ==================================== slots ==================================
def d3_slots(w):
    st = [(((), (), ()), ONE)]
    for s in w:
        if isG(s):
            chans = [(((s,), (s,), (s,)), ONE)]
        elif s == 'E':
            chans = [((('E',), (), ()), ONE), (((CKP,), ('E',), ()), ONE),
                     (((CKP,), (CKP,), ('E',)), ONE)]
        elif s == 'F':
            chans = [((('F',), (CKMI,), (CKMI,)), ONE), (((), ('F',), (CKMI,)), ONE),
                     (((), (), ('F',)), ONE)]
        st = [(tuple(slots[k] + ch[k] for k in range(3)), c0*c)
              for (slots, c0) in st for (ch, c) in chans]
    out = {}
    for (slots, c) in st:
        rs, cc = [], c
        for k in range(3):
            r = red(slots[k])
            assert len(r) == 1, (slots, k, r)
            w2, cv = next(iter(r.items()))
            rs.append(w2); cc = cc*cv
        key = tuple(rs)
        out[key] = out.get(key, ZERO) + cc
    return [(k, v) for k, v in out.items() if not v.iszero()]

# ==================================== pairing ================================
@lru_cache(maxsize=None)
def pair(u, v):
    """<u, v>, u (m,F)-word, v (p,E)-word, CLOSED FORM (verified):
       all-grouplike: QPAIR(total(u), total(v));
       one F / one E:  TH * QPAIR(tot) * QP(2*(alpha(weight LEFT of F in u)
                                             - alpha(weight LEFT of E in v))).
       (Compatible with both H1 families and all PA axioms; the generator
        inputs are <g,g'>=q^{vAu} and <F,E>=theta.)"""
    u, v = tuple(u), tuple(v)
    if nE(u) or nF(v):
        raise ValueError('sides violated')
    if nF(u) != nE(v):
        return ZERO
    if nF(u) > 1:
        raise ValueError('too many root letters')
    gu = [wt(s) for s in u if isG(s)]
    gv = [wt(s) for s in v if isG(s)]
    Au = (sum(a for a, _ in gu), sum(b for _, b in gu))
    Av = (sum(a for a, _ in gv), sum(b for _, b in gv))
    if nF(u) == 0:
        return QPAIR(Au, Av)
    right_u = 0; seenF = False
    for s in u:
        if s == 'F': seenF = True; continue
        if seenF and isG(s): right_u += alpha(wt(s))
    left_v = 0
    for s in v:
        if s == 'E': break
        if isG(s): left_v += alpha(wt(s))
    return TH * QPAIR(Au, Av) * QP(2*right_u - 2*left_v)

