def Sm(u):
    """S on B- words: anti-homomorphism; S(m) = m^-1; S(F) = -CKMI F."""
    out = {(): ONE}
    for s in reversed(tuple(u)):
        if isG(s):
            out = mp(out, W(gm(-s[1], -s[2])))
        else:
            out = mp(out, {(CKMI, 'F'): -ONE})
    return out

# ==================================== psi ====================================
def try_pair(u, v):
    try:
        return pair(u, v)
    except ValueError:
        return None

def psi(y, x):
    out = {}
    for ((x1, x2, x3), cx) in d3_slots(x):
        for ((y1, y2, y3), cy) in d3_slots(y):
            for w1, c1 in Sm(x1).items():
                p1 = try_pair(w1, y1)
                if p1 is None or p1.iszero(): continue
                p3 = try_pair(x3, y3)
                if p3 is None or p3.iszero(): continue
                co = cx*cy*c1*p1*p3
                if co.iszero(): continue
                for w, cw in red(tuple(y2) + tuple(x2)).items():
                    out[w] = out.get(w, ZERO) + co*cw
    return {k: v for k, v in out.items() if not v.iszero()}

def fmt(w):
    if not w: return '1'
    out = []
    for s in w:
        if isG(s):
            out.append(('p' if side(s) == 'p' else 'm') + '(%d,%d)' % (s[1], s[2]))
        else:
            out.append(s)
    return ' '.join(out)

