        chans = [((), ())]
        for s in word:
            chans = [(w1+b1, w2+b2) for (w1, w2) in chans for (b1, b2) in dslots(s)]
        return chans
    def d3(word):
        st = [((), ())]
        for s in word:
            st = [(w1+b1, w2+b2) for (w1, w2) in st for (b1, b2) in dslots(s)]
        out = []
        for (x1, rest) in st:
            for (b1, b2) in d2(rest):
                out.append((x1, b1, b2))
        return out
    cache = {}
    def P(u, v):
        u, v = tuple(u), tuple(v)
        key = (u, v)
        if key in cache: return cache[key]
        r = P_compute(u, v)
