\"\"\"Pairing-left/right kernel check: <x, R v> and <L x, v> for relators R (E-side), L (F-side).\"\"\"
import sys; sys.path.insert(0,'.')
from full_scan2 import build
from fractions import Fraction as Fr
from rat import RF

def test(N, cfdiag):
    env = build(N, 'L', 1, 'L', -1, 'xy')
    P, QE, TH, alpha, isG, side = (env[k] for k in ['P','QE','TH','alpha','isG','side'])
    e = lambda i: tuple(1 if j==i else 0 for j in range(N))
    Kp = lambda i: ('p', e(i)); Km = lambda i: ('m', e(i))
    Kpi = lambda i: ('p', tuple(-x for x in e(i))); Kmi = lambda i: ('m', tuple(-x for x in e(i)))
    cKp = lambda r: ('p', alpha(r)); cKpi = lambda r: ('p', tuple(-x for x in alpha(r)))
    cKm = lambda r: ('m', alpha(r)); cKmi = lambda r: ('m', tuple(-x for x in alpha(r)))
    def av(r, i): return (1 if i == r else 0) - (1 if i == r+1 else 0)

    bad = []
    # right kernel: H1(r,i): Kp_i E_r Kpi_i - q"'^{+av} E_r ; H2(r,s) relator word-pair via sign:
    #  (E F - F E) words live on DIFFERENT sides; pairing defined only m-word x p-word, so H2
    #  can NEVER appear as a right-side relator -- it is not an element of either Borel. Skip.
    # H3(r,s): E_r''^2 E_s - (q+q''^{-1}) E_r E_s E_r + E_s E_r''^2  (|r-s|=1); E_r E_s - E_s E_r (|r-s|>1)
    x0 = (('"'F', 0),)
    xg = (Km(0),)
    xw = (cKm(0), ('F', 0))
    for x in (x0, xg, xw):
        for i in range(N):
            for r in range(N-1):
                v = (Kp(i), ('E', r), Kpi(i))
                lhs = P(x, v)
                rhs = QE(av(r, i)) * P(x, (('E', r),))
                if not lhs.eq(rhs): bad.append(('H1r', fmt_(x,isG,side), i, r, lhs, rhs))
        for r in range(N-1):
            for s in range(N-1):
                if abs(r-s) == 1:
                    rel = [((('E', r), ('E', r), ('E', s)), RF.c(1)),
                           ((('E', r), ('E', s), ('E', r)), RF.c(0)-(QE(1)+QE(-1))),
                           ((('E', s), ('E', r), ('E', r)), RF.c(1))]
                    tot = RF.c(0)
                    for w, c in rel: tot += c * P(x, w)
                    if not tot.iszero(): bad.append(('H3r', fmt_(x,isG,side), r, s, tot))
                elif abs(r-s) > 1:
                    tot = P(x, (('E', r), ('E', s))) - P(x, (('E', s), ('E', r)))
                    if not tot.iszero(): bad.append(('H3com', fmt_(x,isG,side), r, s, tot))
    # left kernel: F-side relators vs E words
    y0 = (('E', 0),); yg = (Kp(0),); yw = (('E', 0), Kp(1))
    for y in (y0, yg, yw):
        for i in range(N):
            for r in range(N-1):
                u = (Km(i), ('F', r), Kmi(i))
                lhs = P(u, y)
                rhs = QE(-av(r, i)) * P((('F', r),), y)
                if not lhs.eq(rhs): bad.append(('H1l', i, r, fmt_(y,isG,side), lhs, rhs))
        for r in range(N-1):
            for s in range(N-1):
                if abs(r-s) == 1:
                    rel = [((('F', r), ('F', r), ('F', s)), RF.c(1)),
                           ((('F', r), ('F', s), ('F', r)), RF.c(0)-(QE(1)+QE(-1))),
                           ((('F', s), ('F', r), ('F', r)), RF.c(1))]
                    tot = RF.c(0)
                    for w, c in rel: tot += c * P(w, y)
                    if not tot.iszero(): bad.append(('H3l', r, s, fmt_(y,isG,side), tot))
    return bad

def fmt_(w, isG, side):
    out = []
    for s in w:
        if isG(s): out.append(('p' if side(s)=='p' else 'm') + str(tuple(s[1])))
        else: out.append('%s%d' % s)
    return ' '.join(out)
for N in (2, 3):
    bad = test(N, None)
    print(f'N={N}: {len(bad)} violations')
    for b in bad[:20]: print('   ', b)
