            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                i = None; hit = None
                for k in range(len(wl)-1):
                    mis = self.misordered(wl[k], wl[k+1])
                    if mis is not None:
                        i = k; hit = mis; break
                if hit is None: continue
                del work[w0]
                for sub, cc in hit:
                    nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i+2:])
                    work[nw] = work.get(nw, RF.c(0)) + c0*cc
