# FINAL generator-relation table, X→q"'^x·(reversed) with locked crossing rules:
def cross_tab(N):
    alpha = lambda r: tuple(1 if j==r else (-1 if j==r+1 else 0) for j in range(N))
    def scalar_to_canonical(w):
        w = list(w); scal = 0
        changed = True
        while changed:
            changed = False
            for i in range(len(w)-1):
                a, b = w[i], w[i+1]
                ag = a[0]=='"'G'; bg = b[0]=='G'
                if ag and bg:
                    w = w[:i]+[('G', tuple(x+y for x,y in zip(a[1],b[1])))]+w[i+2:]; changed=True; break
