                    tag, r = a; mu = b[1]
                    amu = sum(c*alpha(r)[j] for j, c in enumerate(mu) if c)
                    d = -amu if tag=='E' else +amu
                    scal += d
                    w = w[:i]+[b,a]+w[i+2:]; changed=True; break
        return tuple(w), scal
    def rel(L, R):
        wl, xl = scalar_to_canonical(L); wr, xr = scalar_to_canonical(R)
        assert wl == wr or True, (wl, wr)
