"""Vector-space model of D. All grouplikes stored as weight tuples; the model reduces
any adjacent same-side grouplike merge immediately, tracking q-scalars from cross rules.
Cross rules (solution.tex conventions):
  m^u E_r = q^{ar.u} E_r m^u ; F_s p^u = q^{as.u} p^u F_s ; m p = p m ;
  F_s E_r = E_r F_s + delta_rs TH(cKp_r - cKm_r^-1).
Same-side: K^u X_r K^-u with H1 gives X K^u = q^{?}: we implement via the absolute
rules E_r p^u = q^{ar.u} p^u E_r and F_s m^u = q^{as.u} m^u F_s (consistent with H1).
"""
from fractions import Fraction as Fr
import sys; sys.path.insert(0,'.')
from rat import RF

D = 12
def QE(x):
    x = Fr(x); e = D*x
    assert e.denominator == 1, x
    return RF.c(1, int(e))
TH = QE(0)/(QE(-1) - QE(1))

def isG(s): return s[0] in ('p','m')
def side(s): return s[0]

class V:
    def __init__(self, N):
        self.N = N
    def alpha(self, r):
        v = [0]*self.N; v[r] = 1; v[r+1] = -1; return tuple(v)
    def adot(self, ar, u):
        sa, su = sum(ar), sum(u)
        dot = sum(a*b for a, b in zip(ar, u))
        return Fr(sa*su, self.N) - dot
    def mul(self, A, B):
        out = {}
        for wa, ca in A.items():
            for wb, cb in B.items():
                for w, c in self.mul_words(tuple(wa), tuple(wb)).items():
                    out[w] = out.get(w, RF.c(0)) + ca*cb*c
        return self.canon_el(out)
    def canon_el(self, el):
        return {k: v for k, v in el.items() if not v.iszero()}
    def mul_words(self, wa, wb):
        work = {tuple(wa)+tuple(wb): RF.c(1)}
        for _ in range(200000):
            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                # phase 1: letter-level misorders (letters vs grouplikes, F vs E)
                i = None; hit = None
                for k in range(len(wl)-1):
                    x, y = wl[k], wl[k+1]
                    if isG(x) and isG(y):
                        continue
                    mis = self.step(x, y)
                    if mis is not None:
                        i = k; hit = mis; break
                # phase 2: grouplike block moves: a p-grouplike must not sit right of
                # an m-grouplike or an F; an m-grouplike must not sit right... handled:
                # find first adjacent grouplike-grouplike pair m|p -> swap.
                if hit is None:
                    for k in range(len(wl)-1):
                        x, y = wl[k], wl[k+1]
                        if isG(x) and isG(y) and side(x) == 'm' and side(y) == 'p':
                            i, hit = k, [((y, x), RF.c(1))]; break
                # phase 3: merge adjacent same-side grouplikes
                if hit is None:
                    for k in range(len(wl)-1):
                        x, y = wl[k], wl[k+1]
                        if isG(x) and isG(y) and side(x) == side(y):
                            if all(a == 0 for a in x[1]):
                                i, hit = k, [((y,), RF.c(1))]
                            elif all(a == 0 for a in y[1]):
                                i, hit = k, [((x,), RF.c(1))]
                            else:
                                i, hit = k, [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
                            break
                if hit is None: continue
                del work[w0]
                for sub, cc in hit:
                    nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i+2:])
                    work[nw] = work.get(nw, RF.c(0)) + c0*cc
                changed = True
            if not changed: break
        else:
            raise RuntimeError('nontermination')
        out = {}
        for w, c in work.items():
            nw = tuple(s for s in w if not (isG(s) and all(a == 0 for a in s[1])))
            out[nw] = out.get(nw, RF.c(0)) + c
        return {k: v for k, v in out.items() if not v.iszero()}
    def qA(self, ar, u):
        return QE(self.adot(ar, u))
    def step(self, x, y):
        # returns rewrite list [(subword, coeff)] or None
        if isG(x) and isG(y):
            if side(x) == side(y):
                # merge always (combined weight); zero weight symbols are dropped upstream
                if all(a == 0 for a in x[1]): return [((y,), RF.c(1))]
                if all(a == 0 for a in y[1]): return [((x,), RF.c(1))]
                return [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
            return [((y, x), RF.c(1))] if side(x) == 'm' else None
        if not isG(x) and not isG(y):
            if x[0] == 'F' and y[0] == 'E':
                r, s = y[1], x[1]
                cKp = ('p', self.alpha(r)); cKmi = ('m', tuple(-t for t in self.alpha(s)))
                if r == s:
                    return [((y, x), RF.c(1)), ((cKp,), TH), ((cKmi,), RF.c(0)-TH)]
                return [((y, x), RF.c(1))]
            return None
        # letter-grouplike
        if not isG(x) and isG(y):
            s = x
            if s[0] == 'E' and side(y) == 'p':   # E_r p^u = q^{ar.u} p^u E_r
                return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
            if s[0] == 'F' and side(y) == 'm':   # F_s m^u = q^{as.u} m^u F_s
                return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
            if s[0] == 'E' and side(y) == 'm':   # E_r m^u = q^{-ar.u} m^u E_r (inverse of cross law)
                return [((y, x), self.qA(self.alpha(s[1]), y[1]).inv())]

        ar = alpha(x[1])
        return [((y, x), QE(-adot(ar, tuple(-t for t in y[1]))))]
    def R_ss(w):
        work = {tuple(w): RF.c(1)}
        for _ in range(2000):
            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                for i in range(len(wl)-1):
                    x, y = wl[i], wl[i+1]
                    hit = None
                    if isG(x) and isG(y):
                        hit = [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
                    elif not isG(x) and x[0] == 'E' and isG(y):
                        hit = erule(y, x)
                    elif not isG(x) and x[0] == 'F' and isG(y):
                        hit = frule(y, x)
                    if hit:
                        del work[w0]
                        for sub, cc in hit:
                            nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i+2:])
                            work[nw] = work.get(nw, RF.c(0)) + c0*cc
                        changed = True
                        break
                if changed: break
            if not changed: break
        return {k: v for k, v in work.items() if not v.iszero()}
    def psi(y, x):
        out = {}
        for (x1, x2, x3) in d3(tuple(x)):
            for (y1, y2, y3) in d3(tuple(y)):
                for (sx1, cs) in Sm(x1):
                    p1 = P(sx1, y1)
                    if p1.iszero(): continue
                    p3 = P(x3, y3)
                    if p3.iszero(): continue
                    co = cs*p1*p3
                    if mid == 'yx':
                        it2, it1 = R_ss(tuple(y2)).items(), R_ss(tuple(x2)).items()
                        for w2p, cp in R_ss(tuple(y2)).items():
                            for w2q, cq in R_ss(tuple(x2)).items():
                                w = tuple(w2p) + tuple(w2q)
                                out[w] = out.get(w, RF.c(0)) + co*cp*cq
                    else:
                        for w2p, cp in R_ss(tuple(x2)).items():
                            for w2q, cq in R_ss(tuple(y2)).items():
                                w = tuple(w2p) + tuple(w2q)
                                out[w] = out.get(w, RF.c(0)) + co*cp*cq
        return {k: v for k, v in out.items() if not v.iszero()}
    # normalized coproduct (right convention): word = ordered (grouplikes then root letters),
    # coefficient attached; Delta multiplicative. Returns dict {(x1,x2): coeff} with same normalization.
    def d2n(w):
        elts = R_ss(tuple(w))
        out = {}
        for wn, cw in elts.items():
            gs = [s for s in wn if isG(s)]
            fs = [s for s in wn if not isG(s)]
            chans = [((), (), RF.c(1))]
            for s in gs + fs:
                chans = [(w1+b1, w2+b2, co) for (w1, w2, co) in chans
                         for (b1, b2) in dslots(s)]
            for (w1, w2, co) in chans:
                e1 = R_ss(w1); e2 = R_ss(w2)
                for n1, c1 in e1.items():
                    for n2, c2 in e2.items():
                        key = (n1, n2)
                        out[key] = out.get(key, RF.c(0)) + cw*co*c1*c2
        return {k: v for k, v in out.items() if not v.iszero()}
    def d3n(w):
        """Sweedler (Delta x id) Delta with normalized convention."""
        out = {}
        for (x1, rest), co in d2n(w).items():
            for (b1, b2), c2 in d2n(rest).items():
                key = (x1, b1, b2)
                out[key] = out.get(key, RF.c(0)) + co*c2
        return {k: v for k, v in out.items() if not v.iszero()}
    def psi_n(y, x):
        out = {}
        for (x1, x2, x3), cx in d3n(tuple(x)).items():
            for (y1, y2, y3), cy in d3n(tuple(y)).items():
                for (sx1, cs) in Sm_n(x1):
                    p1 = Pn(sx1, y1)
                    if p1.iszero(): continue
                    p3 = Pn(x3, y3)
                    if p3.iszero(): continue
                    co = cx*cy*cs*p1*p3
                    w = tuple(x2) + tuple(y2)
                    out[w] = out.get(w, RF.c(0)) + co
        return {k: v for k, v in out.items() if not v.iszero()}
    def Sm_n(u):
        out = [((), RF.c(1))]
        for s in reversed(tuple(u)):
            new = []
            for (w, c) in out:
                for (p, cp) in S_letter_n(s):
                    new.append((tuple(p)+tuple(w), c*cp))
            out = new
        return out
    def S_letter_n(s):
        if isG(s):
            return [( (('m', tuple(-x for x in s[1])),), RF.c(1) )]
        K = ('m', tuple(-x*sF for x in alpha(s[1])))
        return [((('F', s[1]), K), RF.c(-1))]

    # full reducer: normal order p-Cartans, E's, m-Cartans, F's
    def R(w):
        work = {tuple(w): RF.c(1)}
        for _ in range(6000):
            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                hit_i, hit = -1, None
                for i in range(len(wl)-1):
                    x, y = wl[i], wl[i+1]
                    if isG(x) and isG(y) and side(x) == side(y):
                        hit = [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]; hit_i = i
                    elif isG(x) and isG(y):
                        hit = [((y, x), RF.c(1))]; hit_i = i
                    elif not isG(x) and x[0] == 'E' and isG(y) and side(y) == 'p':
                        hit = erule(y, x); hit_i = i
                    elif not isG(x) and x[0] == 'F' and isG(y) and side(y) == 'm':
                        hit = frule(y, x); hit_i = i
                    elif (isG(x) and side(x) == 'm' and (not isG(y) or side(y) == 'p')) or \
                         (not isG(x) and x[0] == 'F' and (not isG(y) or side(y) == 'p')):
                        hit = [(t, c) for t, c in psi((y,), (x,)).items()]; hit_i = i
                    if hit: break
                if hit:
                    del work[w0]
                    for sub, cc in hit:
                        nw = tuple(wl[:hit_i]) + tuple(sub) + tuple(wl[hit_i+2:])
                        work[nw] = work.get(nw, RF.c(0)) + c0*cc
                    changed = True
            if not changed: break
        fin = {}
        for w0, c0 in work.items():
            wl = list(w0); ch = True
            while ch:
                ch = False
                for i in range(len(wl)-1):
                    a_, b_ = wl[i], wl[i+1]
                    if isG(a_) and isG(b_) and side(a_) == side(b_) and a_[1] > b_[1]:
                        wl[i], wl[i+1] = b_, a_; ch = True
            fin[tuple(wl)] = fin.get(tuple(wl), RF.c(0)) + c0
        return {k: v for k, v in fin.items() if not v.iszero()}
    return dict(QE=QE, TH=TH, alpha=alpha, isG=isG, side=side, P=P, Sm=Sm, psi=psi, R=R, N=N, d2n=d2n, d3n=d3n, psi_n=psi_n)

def run(env):
    QE, TH, alpha, isG, side, P, Sm, psi, N = (env[k] for k in 'QE TH alpha isG side P Sm psi N'.split())
    e = lambda i: tuple(1 if j == i else 0 for j in range(N))
    Km = lambda i: ('m', e(i)); Kp = lambda i: ('p', e(i))
    Kmi = lambda i: ('m', tuple(-x for x in e(i))); Kpi = lambda i: ('p', tuple(-x for x in e(i)))
    cKm = lambda r: ('m', alpha(r)); cKmi = lambda r: ('m', tuple(-x for x in alpha(r)))
    cKp = lambda r: ('p', alpha(r)); cKpi = lambda r: ('p', tuple(-x for x in alpha(r)))
    res = {}
    # pairing table
    res['<cKm F,E>']    = P((cKm(0), ('F', 0)), (('E', 0),))
    res['<cKm^-1 F,E>'] = P((cKmi(0), ('F', 0)), (('E', 0),))
    res['<F Km1^-,E>']  = P((('F', 0), Kmi(0)), (('E', 0),))
    res['<F Km2^-,E>']  = P((('F', 0), Kmi(1)), (('E', 0),))
    res['<F,Kp1 E>']    = P((('F', 0),), (Kp(0), ('E', 0)))
    res['<F,Kp2 E>']    = P((('F', 0),), (Kp(1), ('E', 0)))
    res['<F,E Kp1>']    = P((('F', 0),), (('E', 0), Kp(0)))
    res['<F,E Kp2>']    = P((('F', 0),), (('E', 0), Kp(1)))
    sfx = next(iter(Sm((('F', 0),))))
    res['<S(F),E>']     = P(sfx[0], (('E', 0),)) * sfx[1]
    # cross laws
    res['Km1.E'] = psi((('E', 0),), (Km(0),))
    res['Km2.E'] = psi((('E', 0),), (Km(1),))
    res['F.Kp1'] = psi((Kp(0),), (('F', 0),))
    res['F.Kp2'] = psi((Kp(1),), (('F', 0),))
    res['F.E']   = psi((('E', 0),), (('F', 0),))
    res['F1.E0'] = psi((('E', 0),), (('F', 1),)) if N > 2 else None
    res['F0.E1'] = psi((('E', 1),), (('F', 0),)) if N > 2 else None
    res['Km1.Kp2'] = psi((Kp(1),), (Km(0),))
    return res

