def step(self, x, y):
    # returns rewrite list [(subword, coeff)] or None
    if isG(x) and isG(y):
        if side(x) == side(y):
            # merge always (combined weight); zero weight symbols are dropped upstream
            if all(a == 0 for a in x[1]): return [((y,), RF.c(1))]
            if all(a == 0 for a in y[1]): return [((x,), RF.c(1))]
            return [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
        return [((y, x), RF.c(1))] if side(x) == 'm' else None
    if not isG(x) and not isG(y):
        if x[0] == 'F' and y[0] == 'E':
            r, s = y[1], x[1]
            cKp = ('p', self.alpha(r)); cKmi = ('m', tuple(-t for t in self.alpha(s)))
            if r == s:
                return [((y, x), RF.c(1)), ((cKp,), TH), ((cKmi,), RF.c(0)-TH)]
            return [((y, x), RF.c(1))]
        return None
    # letter-grouplike
    if not isG(x) and isG(y):
        s = x
        if s[0] == 'E' and side(y) == 'p':   # E_r p^u = q^{ar.u} p^u E_r
            return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
        if s[0] == 'F' and side(y) == 'm':   # F_s m^u = q^{as.u} m^u F_s
            return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
        if s[0] == 'E' and side(y) == 'm':   # E_r m^u = q^{-ar.u} m^u E_r (inverse of cross law)
            return [((y, x), self.qA(self.alpha(s[1]), y[1]).inv())]
