       tau(u, y z) = sum_{D(u)} tau(u1, y) tau(u2, z)
       tau(u v, z) = sum_{D(z)} tau(u, z2) tau(v, z1)
    base: tau(1,y)=eps(y), tau(u,1)=eps(u), tau(g_u,g_v)=q"'^{u.v},
          tau(E_r,F_s)=delta th, tau(g,E)=tau(E,g)=tau(g,F)=tau(F,g)=0.
