    def __init__(self, n, sE, sF):
        self.n = n; self.sE = sE; self.sF = sF
        self._cache = {}
    def alpha(self, r):
        return tuple(-1 if j == r else (1 if j == r+1 else 0) for j in range(self.n))
    def adot(self, u, v):
