        if s[0] == 'E':
            w = tuple(self.sE * x for x in self.alpha(s[1]))
            return [(s, '1'), (('g', 'p', w), s)]
        w = tuple(self.sF * x for x in self.alpha(s[1]))
        return [(s, ('g', 'm', w)), ('1', s)]
