from fractions import Fraction as Fr
import sys; sys.path.insert(0,'.')
from rat import RF

D = 12
def QE(x):
    x = Fr(x); e = D*x
    assert e.denominator == 1, x
    return RF.c(1, int(e))
TH = QE(0)/(QE(-1) - QE(1))

def isG(s): return s[0] in ('p','m')
def side(s): return s[0]

class V:
    def __init__(self, N):
        self.N = N
    def alpha(self, r):
        v = [0]*self.N; v[r] = 1; v[r+1] = -1; return tuple(v)
    def adot(self, ar, u):
        sa, su = sum(ar), sum(u)
        dot = sum(a*b for a, b in zip(ar, u))
        return Fr(sa*su, self.N) - dot
    def mul(self, A, B):
        out = {}
        for wa, ca in A.items():
            for wb, cb in B.items():
                for w, c in self.mul_words(tuple(wa), tuple(wb)).items():
                    out[w] = out.get(w, RF.c(0)) + ca*cb*c
        return self.canon_el(out)
    def canon_el(self, el):
        return {k: v for k, v in el.items() if not v.iszero()}
    def mul_words(self, wa, wb):
        work = {tuple(wa)+tuple(wb): RF.c(1)}
        for _ in range(200000):
            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                # phase 1: letter-level misorders (letters vs grouplikes, F vs E)
                i = None; hit = None
                for k in range(len(wl)-1):
                    x, y = wl[k], wl[k+1]
                    if isG(x) and isG(y):
                        continue
                    mis = self.step(x, y)
                    if mis is not None:
                        i = k; hit = mis; break
                # phase 2: grouplike block moves: a p-grouplike must not sit right of
                # an m-grouplike or an F; an m-grouplike must not sit right... handled:
                # find first adjacent grouplike-grouplike pair m|p -> swap.
                if hit is None:
                    for k in range(len(wl)-1):
                        x, y = wl[k], wl[k+1]
                        if isG(x) and isG(y) and side(x) == 'm' and side(y) == 'p':
                            i, hit = k, [((y, x), RF.c(1))]; break
                # phase 3: merge adjacent same-side grouplikes
                if hit is None:
                    for k in range(len(wl)-1):
                        x, y = wl[k], wl[k+1]
                        if isG(x) and isG(y) and side(x) == side(y):
                            if all(a == 0 for a in x[1]):
                                i, hit = k, [((y,), RF.c(1))]
                            elif all(a == 0 for a in y[1]):
                                i, hit = k, [((x,), RF.c(1))]
                            else:
                                i, hit = k, [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
                            break
                if hit is None: continue
                del work[w0]
                for sub, cc in hit:
                    nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i+2:])
                    work[nw] = work.get(nw, RF.c(0)) + c0*cc
                changed = True
            if not changed: break
        else:
            raise RuntimeError('nontermination')
        out = {}
        for w, c in work.items():
            nw = tuple(s for s in w if not (isG(s) and all(a == 0 for a in s[1])))
            out[nw] = out.get(nw, RF.c(0)) + c
        return {k: v for k, v in out.items() if not v.iszero()}
    def qA(self, ar, u):
        return QE(self.adot(ar, u))
    def step(self, x, y):
        # returns rewrite list [(subword, coeff)] or None
        if isG(x) and isG(y):
            if side(x) == side(y):
                # merge always (combined weight); zero weight symbols are dropped upstream
                if all(a == 0 for a in x[1]): return [((y,), RF.c(1))]
                if all(a == 0 for a in y[1]): return [((x,), RF.c(1))]
                return [(((x[0], tuple(a+b for a, b in zip(x[1], y[1]))),), RF.c(1))]
            return [((y, x), RF.c(1))] if side(x) == 'm' else None
        if not isG(x) and not isG(y):
            if x[0] == 'F' and y[0] == 'E':
                r, s = y[1], x[1]
                cKp = ('p', self.alpha(r)); cKmi = ('m', tuple(-t for t in self.alpha(s)))
                if r == s:
                    return [((y, x), RF.c(1)), ((cKp,), TH), ((cKmi,), RF.c(0)-TH)]
                return [((y, x), RF.c(1))]
            return None
        # letter-grouplike
        if not isG(x) and isG(y):
            s = x
            if s[0] == 'E' and side(y) == 'p':   # E_r p^u = q^{ar.u} p^u E_r
                return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
            if s[0] == 'F' and side(y) == 'm':   # F_s m^u = q^{as.u} m^u F_s
                return [((y, x), self.qA(self.alpha(s[1]), y[1]))]
            if s[0] == 'E' and side(y) == 'm':   # E_r m^u = q^{-ar.u} m^u E_r (inverse of cross law)
                return [((y, x), self.qA(self.alpha(s[1]), y[1]).inv())]

                return [((y, x), self.qA(self.alpha(s[1]), y[1]).inv())]
            if s[0] == 'F' and side(y) == 'p':
                return [((y, x), self.qA(self.alpha(s[1]), y[1]))]

        if isG(x) and not isG(y):
            s = y
            if side(x) == 'p' and s[0] == 'F':   # p^u F_s misordered (p before F is normal! blk p<E<m<F: p then F fine) -> None
                return None
            return None
        return None
    def bare(self, *w):
        return {tuple(w): RF.c(1)}

def check(name, got, want, PASS, FAILS):
    keys = set(got) | set(want)
    ok = all((got.get(k, RF.c(0)) - want.get(k, RF.c(0))).iszero() for k in keys)
    print(('PASS ' if ok else 'FAIL ') + name)
    if not ok:
        for k in sorted(keys, key=str):
            g, w_ = got.get(k, RF.c(0)), want.get(k, RF.c(0))
            if not (g - w_).iszero():
                print('    ', k, 'got', g, 'want', w_)
        PASS[0] = False; FAILS.append(name)

def runN(N, PASS, FAILS):
    v = V(N)
    e = lambda i: tuple(1 if j==i else 0 for j in range(N))
    Kp = lambda i: ('p', e(i)); Km = lambda i: ('m', e(i))
    Kmi = lambda i: ('m', tuple(-x for x in e(i))); Kpi = lambda i: ('p', tuple(-x for x in e(i)))
    cKp = lambda r: ('p', v.alpha(r)); cKpi = lambda r: ('p', tuple(-x for x in v.alpha(r)))
    cKm = lambda r: ('m', v.alpha(r)); cKmi = lambda r: ('m', tuple(-x for x in v.alpha(r)))
    av = lambda r, i: (1 if i == r else 0) - (1 if i == r+1 else 0)
    M = v.mul
    def add(*ps):
        out = {}
        for p in ps:
            for k, x in p.items():
                out[k] = out.get(k, RF.c(0)) + x
        return {k: x for k, x in out.items() if not x.iszero()}
    def scale(p, c): return {k: c*x for k, x in p.items() if not (c*x).iszero()}
    W = v.bare
    td = [W(Kp(i)) for i in range(N)]; sd = [W(Kmi(i)) for i in range(N)]
    to = [W(('E', i), Kp(i+1)) for i in range(N-1)]
    so = [W(Kmi(i+1), ('F', i)) for i in range(N-1)]
    print(f'########## n={N} ##########')
    for i in range(N-1):
        check(f'A b{i+1}{i+2} b{i+1}{i+1} = q b{i+1}{i+1} b{i+1}{i+2} A-stale', M(to[i], td[i]), scale(M(td[i], to[i]), QE(-1)), PASS, FAILS)
        check(f'A b{i+1}{i+2} b{i+2}{i+2} = q b{i+2}{i+2} b{i+1}{i+2} A-stale', M(to[i], td[i+1]), scale(M(td[i+1], to[i]), QE(-1)), PASS, FAILS)
        check(f'A b{i+1}{i+2} b{i+1}{i+1} true scalar', M(to[i], td[i]), scale(M(td[i], to[i]), QE(-1)), PASS, FAILS)
        check(f'A b{i+1}{i+2} b{i+2}{i+2} true scalar', M(to[i], td[i+1]), scale(M(td[i+1], to[i]), QE(1)), PASS, FAILS)
        check(f'A c{i+2}{i+1} c{i+1}{i+1} = q c{i+1}{i+1} c{i+2}{i+1} paper', M(so[i], sd[i]), scale(M(sd[i], so[i]), QE(1)), PASS, FAILS)
        check(f'A c{i+2}{i+1} c{i+2}{i+2} = q^-1 c{i+2}{i+2} c{i+2}{i+1} paper', M(so[i], sd[i+1]), scale(M(sd[i+1], so[i]), QE(-1)), PASS, FAILS)
    # Serre must hold as DERIVED? no: Serre is an internal H relation on E's; model treats E's free on the nose.
    # But s21 t12 etc. generate E·F-words only linearly; Serre correctness is part of def of D, not a check here.
    for j in range(N-1):
        for i in range(N):
            check(f'M1 c{j+2}{j+1} b{i+1}{i+1} (paper relAA: q^-a)', M(so[j], td[i]), scale(M(td[i], so[j]), QE(-av(j, i))), PASS, FAILS)
    for j in range(N):
        for i in range(N-1):
            # normalized expectation via scalar equation derived from grouplike projection:
            lhs = M(sd[j], to[i]); rhs_raw = M(to[i], sd[j])
            # machine-derive exponent: find u with lhs = q^x rhs_raw by testing x in {-3..3}
            found = None
            for x in range(-3, 4):
                if all((scale(rhs_raw, QE(x)).get(k, RF.c(0)) - lhs.get(k, RF.c(0))).iszero() for k in set(lhs)|set(rhs_raw)):
                    found = x; break
            check(f'M1 c{j+1}{j+1} b{i+1}{i+2} = q^{found} b..c.. (machine-derived)', lhs,
                  scale(rhs_raw, QE(found if found is not None else 99)), PASS, FAILS)
            print(f'    [note] exponent c{j+1}{j+1} b{i+1}{i+2}: {found}')
    for i in range(N-1):
        lhs = M(so[i], to[i])
        rhs = add(scale(M(to[i], so[i]), QE(-2)),
                  scale(M(td[i], sd[i+1]), TH*QE(1)),
                  scale(M(td[i+1], sd[i]), RF.c(0)-TH*QE(1)))
        check(f'M2 c{i+2}{i+1} b{i+1}{i+2}', lhs, rhs, PASS, FAILS)
    for j in range(N-1):
        for i in range(N-1):
            if j != i:
                lhs = M(so[j], to[i]); rhs = M(to[i], so[j])
                found = None
                for x in range(-3, 4):
                    if all((scale(rhs, QE(x)).get(k, RF.c(0)) - lhs.get(k, RF.c(0))).iszero() for k in set(lhs)|set(rhs)):
                        found = x; break
                check(f'M3* c{j+2}{j+1} b{i+1}{i+2} (scalar {found})', lhs, scale(rhs, QE(found if found is not None else 99)), PASS, FAILS)
    for i in range(N):
        for j in range(N):
            check(f'M0 c{j+1}{j+1} b{i+1}{i+1}', M(sd[j], td[i]), M(td[i], sd[j]), PASS, FAILS)
    for k in range(N):
        Z = M(td[k], sd[k])
        for i in range(N-1):
            check(f'om{k+1} b{i+1}{i+2}', M(Z, to[i]), M(to[i], Z), PASS, FAILS)
            check(f'om{k+1} c{i+2}{i+1}', M(Z, so[i]), M(so[i], Z), PASS, FAILS)
        for i in range(N):
            check(f'om{k+1} b{i+1}{i+1}', M(Z, td[i]), M(td[i], Z), PASS, FAILS)
            check(f'om{k+1} c{i+1}{i+1}', M(Z, sd[i]), M(sd[i], Z), PASS, FAILS)
    def quo(w):
        return tuple(('p', s[1]) if (isG(s) and side(s) == 'm') else s for s in w)
    for r in range(N-1):
        for s in range(N-1):
            comm = add(M(W(('E', r)), W(('F', s))), scale(M(W(('F', s)), W(('E', r))), RF.c(-1)))
            got = {}
            for w, c in comm.items():
