/bin/bash -lc "cd /work/first-proof-humanize-tdgou2bu/002-prob-003/scratch && cat > tri.py <<'EOF'
\"\"\"tri.py: validate claimed maps E-side b_{ij} -> t'_{ij} = K_i E_{j-1}... E_i? and
F-side c_{ji} -> s'_{ji}, jointly with mixed laws, at n=3 (gap<=2 patterns incl).
Normal forms: grouplike-rear, letters as words (E's ordered, F's ordered) — we keep
letter words verbatim and reduce only letter-grouplike swaps; E_g"'^2/(letter-letter)
swaps are honest (free algebra on letters modulo Serre — we check identities that
are LETTER-word identities, so Serre never needed).
Notation as vfin but letter swaps between E'"'s/F's NOT applied (words kept as-is).
\"\"\"
from fractions import Fraction as Fr
import sys; sys.path.insert(0, '/work/first-proof-humanize-tdgou2bu/002-prob-003/scratch')
from rat import RF
D = 12
def QE(x):
    x = Fr(x); e_ = D * x; assert e_.denominator == 1, x; return RF.c(1, int(e_))
ONE = RF.c(1); ZERO = RF.c(0); TH = QE(0)/(QE(-1)-QE(1))

class T:
    def __init__(self, n): self.n = n
    def av(self, r, i): return (1 if i == r + 1 else 0) - (1 if i == r else 0)
    def alpha(self, r): return tuple((1 if j == r else 0) - (1 if j == r+1 else 0) for j in range(self.n))
    # letter-grouplike swap only; grouplikes merged to a single sorted block per side
    def norm(self, w):
        # w: list of symbols; bubble letters right of grouplikes leftwards: move each
        # grouplike left across letters accruing scalar; then merge/sort grouplikes.
        w = list(w); sc = ONE
        # move grouplikes left
        for k in range(len(w)):
            for i in range(len(w) - 1):
                x, y = w[i], w[i + 1]
                if y[0] in ('p', 'm') and x[0] in ('E', 'F'):
                    w[i], w[i + 1] = y, x
                    r = x[1]; u = y[2] if len(y) > 2 else y[1]
                    if x[0] == 'E' and y[1] == 'p': sc *= QE(-self.av(r, u))
                    elif x[0] == 'E' and y[1] == 'm': sc *= QE(+self.av(r, u))
                    elif x[0] == 'F' and y[1] == 'p': sc *= QE(-self.av(r, u))
                    elif x[0] == 'F' and y[1] == 'm': sc *= QE(+self.av(r, u))
        # symbols: ('E',r),('F',s),('g',side,weight)
        gp = [0]*self.n; gm = [0]*self.n; lets = []
        for s in w:
            if s[0] == 'g':
                if s[1] == 'p': gp = [a+b for a, b in zip(gp, s[2])]
                else: gm = [a+b for a, b in zip(gm, s[2])]
            else: lets.append(s)
        key = (tuple(gp), tuple(gm), tuple(lets))
        return {key: sc}
    def mul(self, A, B):
        out = {}
        for (gp, gm, lt), c in A.items():
            w = [('g', 'p', gp)] * (any(gp)) + [('g', 'm', gm)] * (any(gm)) + list(lt)
            for (hq, hm, ht), d in B.items():
                w2 = w + ([('g', 'p', hq)] * (any(hq)) + [('g', 'm', hm)] * (any(hm)) + list(ht))
                for k, v in self.norm(w2).items():
                    out[k] = out.get(k, ZERO) + c * d * v
        return {k: v for k, v in out.items() if not v.iszero()}
    def el(self, *syms): return self.norm(list(syms))

def test():
    ok = True
    for n in (3, 4):
        T0 = T(n)
        e = lambda i: tuple(1 if j == i else 0 for j in range(n))
        gP = lambda i, s=1: ('g', 'p', tuple(s*x for x in e(i)))
        gM = lambda i, s=1: ('g', 'm', tuple(s*x for x in e(i)))
        E = lambda r: ('E', r); F = lambda s: ('F', s)
        # candidate maps
        def t(r, c):  # b_rc, r<=c
            syms = [gP(r)] + [E(k) for k in range(r, c)]
            return T0.el(*syms)
        def s(r, c):  # c_rc, r>=c
            syms = [gM(r, -1)] + [F(k) for k in range(c, r)]  # F_c..F_{r-1}? careful: c_{r,c} walk F_c,...,F_{r-1}
            return T0.el(*syms)
        def elist(*els):
            out = T0.el()
            for x in els: out = T0.mul(out, x)
            return out
        def diff(A, B):
            ks = set(A) | set(B)
            return [(k, A.get(k, ZERO), B.get(k, ZERO)) for k in ks if not (A.get(k, ZERO) - B.get(k, ZERO)).iszero()]
        # --- same-side exchanges at gap<=2 ---
        for i in range(n - 1):
            # b_{i+1,i+2} b_{i+1,i+1} vs b_{i+1,i+1} b_{i+1,i+2}
            d1 = diff(T0.mul(t(i, i+1), t(i, i)), T0.mul(t(i, i), t(i, i+1)))
            d2 = diff(T0.mul(t(i, i+1), t(i+1, i+1)), T0.mul(t(i+1, i+1), t(i, i+1)))
            d3 = diff(T0.mul(s(i+1, i), s(i, i)), T0.mul(s(i, i), s(i+1, i)))
            d4 = diff(T0.mul(s(i+1, i), s(i+1, i+1)), T0.mul(s(i+1, i+1), s(i+1, i)))
            print(f\"n{n} adj b({i+1}{i+2}·{i+1}{i+1}) commute:{not d1} b({i+1}{i+2}·{i+2}{i+2}):{not d2} c({i+2}{i+1}·{i+1}{i+1}):{not d3} c({i+2}{i+1}·{i+2}{i+2}):{not d4}\")
            ok &= not (d1 or d2 or d3 or d4)
        # --- minor recursion: b_{i,i+2} ?= t_{i,i+1}t_{i+1,i+2} - q"'^? t t = t_{i,i+2} ---
        for i in range(n - 2):
            lhs = T0.mul(t(i, i+1), t(i+1, i+2))
            rhs1 = T0.mul(t(i+1, i+2), t(i, i+1))
            tgt = t(i, i+2)
            for x in (-1, 1, 0):
                combo = dict(lhs)
                for k, v in rhs1.items():
                    combo[k] = combo.get(k, ZERO) - QE(x) * v
                d = diff(combo, tgt)
                if not d:
                    print(f"n{n} b{i+1}{i+3}: minor recursion OK with q''^{x}")
                else:
                    if x == 0: print(f"n{n} b{i+1}{i+3}: no recursion match; lhs={lhs} rhs={rhs1} tgt={tgt}")
            # c side: c_{i+2,i} ?= s_{i+2,i+1}s_{i+1,i} - q''^? s s
            lhs2 = T0.mul(s(i+2, i+1), s(i+1, i))
            rhs2 = T0.mul(s(i+1, i), s(i+2, i+1))
            tgt2 = s(i+2, i)
            for x in (-1, 1, 0):
                combo = dict(lhs2)
                for k, v in rhs2.items():
                    combo[k] = combo.get(k, ZERO) - QE(x) * v
                if not diff(combo, tgt2):
                    print(f"n{n} c{i+3}{i+1}: minor recursion OK with q''^{x}")
        # --- mixed laws ---
        M = T0.mul
        for i in range(n - 1):
            for j in range(n):
                # s_jj t_{i,i+1} vs scalar t s
                A = M(s(j, j), t(i, i+1)); B = M(t(i, i+1), s(j, j))
                xs = [x for x in range(-3, 4) if not diff(A, {k: QE(x)*v for k, v in B.items()})]
                print(f"n{n} M1'"'(j={j+1},i={i+1}): scalar q"'^{xs}  (want q''^{{{+T0.av(i, j)}}})")
                ok &= (xs == [T0.av(i, j)])
            for j in range(n - 1):
                A = M(s(j+1, j), t(i, i))
                B = M(t(i, i), s(j+1, j))
                xs = [x for x in range(-3, 4) if not diff(A, {k: QE(x)*v for k, v in B.items()})]
                print(f"n{n} M0b(j={j+1},i={i+1}): scalar q''^{xs} (want q''^{{{+T0.av(j, i)}}})")
                ok &= (xs == [T0.av(j, i)])
                if j != i:
                    A = M(s(j+1, j), t(i, i+1)); B = M(t(i, i+1), s(j+1, j))
                    xs = [x for x in range(-3, 4) if not diff(A, {k: QE(x)*v for k, v in B.items()})]
                    want = T0.av(j, i+1) + T0.av(i, j+1)
                    print(f"n{n} M3(j={j+1},i={i+1}): scalar q''^{xs} (want q''^{{{want}}})")
                    ok &= (xs == [want])
            # M2
            A = M(s(i+1, i), t(i, i+1))
            B = dict(M(t(i, i+1), s(i+1, i)))
            for k, v in M(t(i, i), s(i+1, i+1)).items(): B[k] = B.get(k, ZERO) + TH * v
            for k, v in M(t(i+1, i+1), s(i, i)).items(): B[k] = B.get(k, ZERO) - TH * v
            d = diff(A, B)
            print(f"n{n} M2(i={i+1}): {'"'OK' if not d else d}\")
            ok &= not d
    print('TRI-VALID:', ok)

if __name__ == '__main__':
    test()
