\begin{document}

\begin{center}
{\LARGE\bfseries The bigon surface algebra is the generalized quantum
double}
\end{center}

\bigskip
\noindent
Fix $n\ge2$ and $q\in\C^\times$ not a root of unity.  Let
$\Uq(\bm),\Uq(\bp)$ be the Borel subalgebras of the simply-connected
quantum group $H=\Uq^{ext}(\mathfrak{sl}(n))$ (the
$U_q^{ext}(\mathfrak{sl}(n))$ of Klimyk--Schm\"udgen), and let
$\la\cdot,\cdot\ra:\Uq(\bm)\times\Uq(\bp)\to\C$ be the
Drinfel'd--Tanisaki skew pairing, normalized as in the problem by
\begin{equation}
\la\hK_i,\hK_j\ra=q^{\,\frac1n-\del_{ij}},\qquad
\la E_i,F_j\ra=\la F_j,E_i\ra=\frac{\del_{ij}}{q^{-1}-q},\qquad
\la\hK_i,F_j\ra=\la E_j,\hK_i\ra=0 .
\label{P0}\tag{P0}
\end{equation}
We prove:
\begin{enumerate}[label=(\arabic*),leftmargin=2em]
\item an explicit algebra isomorphism
  $\Sn(\B^*)\cong\Uq(\bm)\ptn\Uq(\bp)$, the generalized quantum double
  (Theorem~\ref{thm:one});
\item an algebra isomorphism $\Sn(\B^*)/I\cong H$, where
  $I=(b_{ii}c_{ii}-1\mid 1\le i\le n)$ and $b_{ij},c_{kl}$ are the
  horizontal arcs directed to the right (Theorem~\ref{thm:two}).
\end{enumerate}

\noindent\emph{Standing ground and external inputs.}  We take
$\Sn(\B^*)$ in its presentation by horizontal arcs
(Definition~\ref{def:A}): one quantum-matrix-algebra copy
\eqref{relAA} per boundary component and the mixed relations
\eqref{M0}--\eqref{M3} of the single essential mixed crossing
configuration.  The general theorem behind this description — the
stated skein algebra of the bigon with one boundary arc of each sign
per side is the quantum matrix algebra $\mathcal O_q(M_n)$, and
stacks of bigons present the general case — is the bigon case of the
standard presentation theory of stated skein algebras (L\^e,
\emph{Triangular decomposition of skein algebras}); in this paper it
is used only as the input description of $\Sn(\B^*)$ and is adopted,
together with the skew-pairing existence theorem of
Definition~\ref{def:D}, as one of our two precisely stated external
inputs.  Both parts then concern explicitly presented algebras; every
constant is derived in \S\ref{sec:cross} from \eqref{P0} and the Hopf
axioms via the channel calculus of the skew pairing, and the whole
calculus was independently machine-checked
(Remark~\ref{rem:verify}).

"""vfin.py — round-2 verification battery for prob-003 (NEW adopted rule world).

The rule world is EXACTLY the one printed in solution.tex (round 2):
  Same-side (within each Borel = restriction of H):
      E_r K^{u(p)} = q^{-alpha_r(u)} K^{u} E_r,   F_s K^{u(m)} = q^{+alpha_s(u)} K^{u} F_s
  Cross (skew-product with kernel <S x1, y1> x2 y2 <x3, y3>, pairing evolved):
      E_r K^{u(m)} = q^{+alpha_r(u)} K^{u} E_r,   F_s K^{u(p)} = q^{-alpha_s(u)} K^{u} F_s
      K^{u(m)} K^{v(p)} = K^{v(p)} K^{u(m)}
      F_s E_r = E_r F_s - delta_rs TH ( cK_r^{(p)-1} - cK_s^{(m)} )
                = E_r F_s + delta_rs TH ( cK_s^{(m)} - cK_r^{(p)-1} )
  phi-images:  t_ii = K_i^{(p)},  t_{i,i+1} = E_i K_{i+1}^{(p)},
               s_ii = K_i^{(m)-1}, s_{i+1,i} = K_{i+1}^{(m)-1} F_i.
  Engineering alpha(r) = +e_r - e_{r+1}; the paper's root function
  alpha_r(i) = delta_{i,r+1} - delta_{i,r} = -alpha(r)_i; q-exponents below are
  stated directly in terms of av(r,i) := alpha_r(i) (paper function).
Every check compares the engine's output with an Independently-symbolically-derived
expectation; exponents are never read out of the engine and re-asserted.
Checks:
  A1..A4   relAA adjacent exchanges for t and s images
  M0a,M0b  mixed diagonal/off-diagonal exchanges (scalars q^{+alpha_j(i)} resp)
  M1p      s_jj t_{i,i+1} = q^{+alpha_i(j)} t s
  M2       s_{i+1,i} t_{i,i+1} = t s + th(t_ii s_{i+1,i+1} - t_{i+1,i+1} s_ii)
  M3       s_{j+1,j} t_{i,i+1} = q^{alpha_j(i+1)-alpha_i(j+1)} t s   (j != i)
  OM       Omega_k = K_k^{(p)} K_k^{(m)-1} central in D (all generator pairs)
  EFdiag   [E_r,F_s] in the diagonal quotient D/J equals delta th(cK^-1 - cK) (H2)
  MINt,MINs gap-2 quantum-minor image displays of prop:t
"""
from fractions import Fraction as Fr
import sys; sys.path.insert(0, '/work/first-proof-humanize-tdgou2bu/002-prob-003/scratch')
from rat import RF

D = 12
def QE(x):
    x = Fr(x); e = D * x
    assert e.denominator == 1, x
    return RF.c(1, int(e))
TH = QE(0) / (QE(-1) - QE(1))

def isG(s): return s[0] in ('p', 'm')
def side(s): return s[0]

class V:
    def __init__(self, N):
        self.N = N
    def alpha(self, r):                      # engineering: +e_r - e_{r+1}
        v = [0] * self.N; v[r] = 1; v[r + 1] = -1; return tuple(v)
    def av(self, r, i):                      # paper function alpha_r(i)
        return -(1 if i == r else 0) + (1 if i == r + 1 else 0)
    def mul(self, A, B):
        out = {}
        for wa, ca in A.items():
            for wb, cb in B.items():
                for w, c in self.mul_words(tuple(wa), tuple(wb)).items():
                    out[w] = out.get(w, RF.c(0)) + ca * cb * c
        return {k: v for k, v in out.items() if not v.iszero()}
    def mul_words(self, wa, wb):
        work = {tuple(wa) + tuple(wb): RF.c(1)}
        for _ in range(200000):
            changed = False
            for w0 in list(work):
                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                hit = None; i = None
                for k in range(len(wl) - 1):
                    x, y = wl[k], wl[k + 1]
                    sw = self.step(x, y)
                    if sw is not None:
                        i, hit = k, sw; break
                if hit is None: continue
                del work[w0]
                for sub, cc in hit:
                    nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i + 2:])
                    work[nw] = work.get(nw, RF.c(0)) + c0 * cc
                changed = True
            if not changed: break
        else:
            raise RuntimeError('nontermination')
        out = {}

        out = {}
        for w, c in work.items():
            nw = tuple(s for s in w if not (isG(s) and all(a == 0 for a in s[1])))
            out[nw] = out.get(nw, RF.c(0)) + c
        return {k: v for k, v in out.items() if not v.iszero()}
    def step(self, x, y):
        if isG(x) and isG(y):
            if side(x) == side(y):
                if all(a == 0 for a in x[1]): return [((y,), RF.c(1))]
                if all(a == 0 for a in y[1]): return [((x,), RF.c(1))]
                if tuple(x[1]) < tuple(y[1]):
                    return [((y, x), RF.c(1))]     # canonical: decreasing weight order
                return None
            return [((y, x), RF.c(1))] if side(x) == 'm' else None   # m|p -> p|m freely

        if not isG(x) and not isG(y):
            if x[0] == 'F' and y[0] == 'E':
                s, r = x[1], y[1]
                if r == s:
                    cKpi = ('p', tuple(-t for t in self.alpha(r)))
                    cKm = ('m', self.alpha(s))
                    return [((y, x), RF.c(1)), ((cKm,), TH), ((cKpi,), RF.c(0) - TH)]
                return [((y, x), RF.c(1))]
            return None
        # letter before grouplike: move grouplike LEFT is normal (blk p E m F)
        if not isG(x) and isG(y):
            r = x[1]; u = y[1]
            if x[0] == 'E' and side(y) == 'p':    # E K^{u(p)} = q^{-av(r,u)} K E
                return [((y, x), QE(-self.av(r, u)))]
            if x[0] == 'E' and side(y) == 'm':    # E K^{u(m)} = q^{+av(r,u)} K E
                return [((y, x), QE(+self.av(r, u)))]
            if x[0] == 'F' and side(y) == 'm':    # F K^{u(m)} = q^{+av(s,u)} K F
                return [((y, x), QE(+self.av(r, u)))]
            if x[0] == 'F' and side(y) == 'p':    # F K^{u(p)} = q^{-av(s,u)} K F
                return [((y, x), QE(-self.av(r, u)))]
        return None
    def bare(self, *w):
        return self.mul_words(tuple(w), ())

def check(name, got, want, PASS, FAILS):
    keys = set(got) | set(want)
    ok = all((got.get(k, RF.c(0)) - want.get(k, RF.c(0))).iszero() for k in keys)
    print(('PASS ' if ok else 'FAIL ') + name)
    if not ok:
        for k in sorted(keys, key=str):
            g, w_ = got.get(k, RF.c(0)), want.get(k, RF.c(0))
            if not (g - w_).iszero():
                print('     ', k, 'got', g, 'want', w_)
        PASS[0] = False; FAILS.append(name)

def runN(N, PASS, FAILS):
    v = V(N)
    e = lambda i: tuple(1 if j == i else 0 for j in range(N))
    Kp = lambda i: ('p', e(i)); Km = lambda i: ('m', e(i))
    Kpi = lambda i: ('p', tuple(-x for x in e(i))); Kmi = lambda i: ('m', tuple(-x for x in e(i)))
    M = v.mul; W = v.bare
    def add(*ps):
        out = {}
        for p in ps:
            for k, x in p.items():
                out[k] = out.get(k, RF.c(0)) + x
        return {k: x for k, x in out.items() if not x.iszero()}
    def scale(p, c): return {k: c * x for k, x in p.items() if not (c * x).iszero()}
    td = [W(Kp(i)) for i in range(N)]
    sd = [W(Kmi(i)) for i in range(N)]
    to = [W(('E', i), Kp(i + 1)) for i in range(N - 1)]
    so = [W(Kmi(i + 1), ('F', i)) for i in range(N - 1)]
    print(f'########## n={N} ##########')
    for i in range(N - 1):
