                c0 = work[w0]
                if c0.iszero():
                    del work[w0]; continue
                wl = list(w0)
                hit = None; i = None
                for k in range(len(wl) - 1):
                    x, y = wl[k], wl[k + 1]
                    sw = self.step(x, y)
                    if sw is not None:
                        i, hit = k, sw; break
                if hit is None: continue
                del work[w0]
                for sub, cc in hit:
                    nw = tuple(wl[:i]) + tuple(sub) + tuple(wl[i + 2:])
                    work[nw] = work.get(nw, RF.c(0)) + c0 * cc
                changed = True
            if not changed: break
        else:
            raise RuntimeError('nontermination')
        out = {}
        for w, c in work.items():
            nw = tuple(s for s in w if not (isG(s) and all(a == 0 for a in s[1])))
            out[nw] = out.get(nw, RF.c(0)) + c
        return {k: v for k, v in out.items() if not v.iszero()}
    def step(self, x, y):
        if isG(x) and isG(y):
            if side(x) == side(y):
                if all(a == 0 for a in x[1]): return [((y,), RF.c(1))]
                if all(a == 0 for a in y[1]): return [((x,), RF.c(1))]
                if tuple(x[1]) < tuple(y[1]):
                    return [((y, x), RF.c(1))]
                return None
            return [((y, x), RF.c(1))] if side(x) == 'm' else None   # m|p -> p|m freely

        if not isG(x) and not isG(y):
            if x[0] == 'F' and y[0] == 'E':
                s, r = x[1], y[1]
                if r == s:
                    # F_s E_r = E_r F_s - th cK_r^{(p)} + th cK_s^{(m)-1}
                    cKp = ('p', tuple(-t for t in self.alpha(r)))   # weight e_r-e_{r+1}
                    cKmi = ('m', self.alpha(s))                      # weight -e_s+e_{s+1}
                    return [((y, x), RF.c(1)),
                            ((cKp,), RF.c(0) - TH),
                            ((cKmi,), TH)]
                return [((y, x), RF.c(1))]
            return None
        # letter then grouplike: normal order is (p-g) E (m-g) F, grouplike FIRST
        if not isG(x) and isG(y):
            r = x[1]; u = y[1]

            r = x[1]; u = y[1]
            if x[0] == 'E' and side(y) == 'p':    # internal: E K^{u(p)} = q^{-av} K E
                return [((y, x), QE(-self.av(r, u)))]
            if x[0] == 'E' and side(y) == 'm':    # cross (a): E K^{u(m)} = q^{-av} K E
                return [((y, x), QE(-self.av(r, u)))]
            if x[0] == 'F' and side(y) == 'm':    # internal: F K^{u(m)} = q^{+av} K F
                return [((y, x), QE(+self.av(r, u)))]
            if x[0] == 'F' and side(y) == 'p':    # cross (b): F K^{u(p)} = q^{+av} K F
                return [((y, x), QE(+self.av(r, u)))]
        return None
    def bare(self, *w):
        return self.mul_words(tuple(w), ())

def check(name, got, want, PASS, FAILS):
    keys = set(got) | set(want)
    ok = all((got.get(k, RF.c(0)) - want.get(k, RF.c(0))).iszero() for k in keys)
    if not ok:
        print('FAIL ' + name)
        for k in sorted(keys, key=str):
            g, w_ = got.get(k, RF.c(0)), want.get(k, RF.c(0))
            if not (g - w_).iszero():
                print('     ', k, 'got', g, 'want', w_)
        PASS[0] = False; FAILS.append(name)

def runN(N, PASS, FAILS):
    v = V(N)
    e = lambda i: tuple(1 if j == i else 0 for j in range(N))
    ne = lambda i: tuple(-x for x in e(i))
    Kp = lambda i: ('p', e(i)); Km = lambda i: ('m', e(i))
    Kpi = lambda i: ('p', ne(i)); Kmi = lambda i: ('m', ne(i))
    M = v.mul; W = v.bare
    def add(*ps):
        out = {}
        for p in ps:
            for k, x in p.items():
                out[k] = out.get(k, RF.c(0)) + x
        return {k: x for k, x in out.items() if not x.iszero()}
    def scale(p, c): return {k: c * x for k, x in p.items() if not (c * x).iszero()}
    td = [W(Kp(i)) for i in range(N)]
    tdi = [W(Kpi(i)) for i in range(N)]
    sd = [W(Kmi(i)) for i in range(N)]
    sdi = [W(Km(i)) for i in range(N)]      # s_{ii}^{-1} = K_i^{(m)}
    to = [W(('E', i), Kp(i + 1)) for i in range(N - 1)]
    so = [W(Kmi(i + 1), ('F', i)) for i in range(N - 1)]
    # relAA adjacent exchanges
    for i in range(N - 1):
        check(f'n{N} A1 t{i+1}{i+2} t{i+1}{i+1}', M(to[i], td[i]), M(td[i], to[i]), PASS, FAILS)
        check(f'n{N} A2 t{i+1}{i+2} t{i+2}{i+2}', M(to[i], td[i+1]), M(td[i+1], to[i]), PASS, FAILS)
        check(f'n{N} A3 s{i+2}{i+1} s{i+1}{i+1}', M(so[i], sd[i]), M(sd[i], so[i]), PASS, FAILS)
        check(f'n{N} A4 s{i+2}{i+1} s{i+2}{i+2}', M(so[i], sd[i+1]), M(sd[i+1], so[i]), PASS, FAILS)
    # M0a, M0b, M1p, M3
    for j in range(N):
        for i in range(N):
            check(f'n{N} M0a c{j+1}{j+1} b{i+1}{i+1}', M(sd[j], td[i]), M(td[i], sd[j]), PASS, FAILS)
    for j in range(N - 1):
        for i in range(N):
            check(f'n{N} M0b c{j+2}{j+1} b{i+1}{i+1}', M(so[j], td[i]), M(td[i], so[j]), PASS, FAILS)
    for j in range(N):
        for i in range(N - 1):
            check(f'n{N} M1p c{j+1}{j+1} b{i+1}{i+2}', M(sd[j], to[i]), M(to[i], sd[j]), PASS, FAILS)
    for j in range(N - 1):
        for i in range(N - 1):
            if j != i:
                check(f'n{N} M3 c{j+2}{j+1} b{i+1}{i+2}', M(so[j], to[i]), M(to[i], so[j]), PASS, FAILS)
    # M2 display: s t = t s + th( t_{i+1,i+1} s_{ii}^{-1} s_{i+1,i+1} - t_{i+1,i+1} t_{ii}^{-1} s_{i+1,i+1} )
    for i in range(N - 1):
        rhs = add(M(to[i], so[i]),
                  scale(M(M(td[i + 1], sdi[i]), sd[i + 1]), TH),
                  scale(M(M(td[i + 1], tdi[i]), sd[i + 1]), RF.c(0) - TH))
        check(f'n{N} M2 c{i+2}{i+1} b{i+1}{i+2}', M(so[i], to[i]), rhs, PASS, FAILS)
    # Omega centrality (exact commutation)
    for k in range(N):
        Z = M(td[k], sd[k])
        for i in range(N - 1):
            check(f'n{N} OM{k+1} vs t{i+1}{i+2}', M(Z, to[i]), M(to[i], Z), PASS, FAILS)
            check(f'n{N} OM{k+1} vs s{i+2}{i+1}', M(Z, so[i]), M(so[i], Z), PASS, FAILS)
        for i in range(N):
            check(f'n{N} OM{k+1} vs t{i+1}{i+1}', M(Z, td[i]), M(td[i], Z), PASS, FAILS)
            check(f'n{N} OM{k+1} vs s{i+1}{i+1}', M(Z, sd[i]), M(sd[i], Z), PASS, FAILS)
    # EF diagonal quotient: identify m-grouplikes with p of same weight; expect (H2)
    def quo(w):
        return tuple(('p', s[1]) if (isG(s) and side(s) == 'm') else s for s in w)
    for r in range(N - 1):
        for s in range(N - 1):
            comm = add(M(W(('E', r)), W(('F', s))), scale(M(W(('F', s)), W(('E', r))), RF.c(0) - RF.c(1)))
            got = {}
            for w, c in comm.items():
                for w2, c2 in v.mul_words(quo(w), ()).items():
                    got[w2] = got.get(w2, RF.c(0)) + c * c2
            want = {}
            if r == s:
                for w2, c2 in {(('p', v.alpha(r)),): TH,                      # th cK^{-1} (weight -e_r+e_{r+1})
                               (('p', tuple(-t for t in v.alpha(r))),): RF.c(0) - TH}.items():
                    for w3, c3 in v.mul_words(w2, ()).items():
                        want[w3] = want.get(w3, RF.c(0)) + c2 * c3
            check(f'n{N} EFdiag [E{r+1},F{s+1}]=(H2)', got, want, PASS, FAILS)
    # minors (gap 2): uD2 = merge grouplikes per side, keep ordered letters
    def uD2(bag):
        out = {}
        for w, c in bag.items():
            gp = [0] * N; gm = [0] * N; lets = []
            for s in w:
                if isG(s):
                    tgt = gp if side(s) == 'p' else gm
                    for a, b in zip(tgt, s[1]):
                        if side(s) == 'p': gp[[i for i in range(N) if s[1][i]][0] if False else 0] += 0
                    if side(s) == 'p': gp = [a + b for a, b in zip(gp, s[1])]
                    else: gm = [a + b for a, b in zip(gm, s[1])]
                else: lets.append(s)
            key = (tuple(gp), tuple(gm), tuple(lets))
            out[key] = out.get(key, RF.c(0)) + c
        return {k: v for k, v in out.items() if not v.iszero()}
    for i in range(N - 2):
        combo2 = uD2(add(M(to[i], to[i + 1]), scale(M(to[i + 1], to[i]), RF.c(0) - QE(-1))))
        want2 = uD2(add(scale(v.bare(('E', i), ('E', i + 1), Kp(i + 1), Kp(i + 2)), QE(-1)),
                        scale(v.bare(('E', i + 1), ('E', i), Kp(i + 1), Kp(i + 2)), RF.c(0) - QE(-1))))
        check(f'n{N} MINt b{i+1}{i+3} image', combo2, want2, PASS, FAILS)
        combo3 = uD2(add(M(so[i + 1], so[i]), scale(M(so[i], so[i + 1]), RF.c(0) - QE(-1))))
        want3 = uD2(add(scale(v.bare(Kmi(i + 2), Kmi(i + 1), ('F', i + 1), ('F', i)), QE(-1)),
                        scale(v.bare(Kmi(i + 2), Kmi(i + 1), ('F', i), ('F', i + 1)), RF.c(0) - QE(-1))))
        check(f'n{N} MINs c{i+3}{i+1} image', combo3, want3, PASS, FAILS)

if __name__ == '__main__':
    PASS = [True]; FAILS = []
    for n in (2, 3, 4):
        runN(n, PASS, FAILS)
    print()
    print('ALL PASS' if PASS[0] else f'{len(FAILS)} FAILURES: {FAILS[:24]}')

