    def _kminor(self, s, k):
        if k == 1: return [(s,)]
        out = []
        for (a, b) in self.d1(s):
            for rest in (self._kminor(b, k - 1) if b != '1' else [('1',) * (k - 1)]):
                out.append((a,) + rest)
        return out
    # --- antipode of a grouplike-only-or-letter word (S anti-automorphism) ---
    def S_word(self, w):
        out = [(ONE, ())]
        for lt in reversed(w):
            sc, wl = self.S_letter(lt)
            out = [(a * sc, ww + wl) for (a, ww) in out]
        return out
    def S_letter(self, s):
        if s[0] == 'g':
            return (ONE, (('g', tuple(-x for x in s[1])),))
        if s[0] == 'E':
            return (RF.c(-1), (('g', self.alpha(s[1])), s))       # -cK^{-1} E (weight +alpha)
        return (RF.c(-1), (s, ('g', tuple(-x for x in self.alpha(s[1])))))  # -F cK (weight -alpha)
    # --- the pairing, by (PA1),(PA2),(P) ---
    def pair(self, u, v):
        key = (u, v)
        if key not in self._pcache:
            self._pcache[key] = self._pair(u, v)
        return self._pcache[key]
    def _pair(self, u, v):
        if not u: return ONE if all(s[0] == 'g' for s in v) else ZERO
        if not v: return ONE if all(s[0] == 'g' for s in u) else ZERO
        if self.isG(u) and self.isG(v):
            return QE(self.adot(self.totW(u), self.totW(v)))
        if len(u) > 1:
            # (PA2): <X1...Xm, Y> = sum <X1,Y_(1)>...<Xm,Y_(m)> over Delta^m(Y);
            # implement by recursion: split off the FIRST letter of the first
            # argument and use <b, word> = sum <b_(1),? >... via (PA1) duality,
            # concretely: <(a,rest), Y> = sum over 2-minors of Y: <a,Y_(1)><rest,Y_(2)>
            a, rest = u[0], u[1:]
            out = ZERO
            for (v1, v2) in self.dslots(v, 2):
                p1 = self.pair((a,), v1)
                if p1.iszero(): continue
                out += p1 * self.pair(rest, v2)
            return out
        a = u[0]
        # a is a single E or F letter; v nonempty
        if len(v) == 1:
            z = v[0]
            if z[0] == 'g': return ZERO
            if a[0] != z[0] and a[0] in 'EF' and z[0] in 'EF':
                return TH if a[1] == z[1] else ZERO
            return ZERO
        # (PA1): <a, y z> = <a_(1),y><a_(2),z>, split the FIRST letter y of v
        y, z = v[0], v[1:]
        out = ZERO
        for (b1, b2) in self.d1(a):
            b1 = () if b1 == '1' else (b1,)
            b2 = () if b2 == '1' else (b2,)
            p1 = self.pair(b1, (y,))
            if p1.iszero(): continue
            out += p1 * self.pair(b2, z)
        return out
    # --- S^{-1} of a word (anti-automorphism, letterwise mirror of S) ---
    def Sinv_word(self, w):
