\begin{theorem}[the mixed relations hold in $D$]\label{thm:mixed}
With $t,s$ as in Definition~\ref{def:phi}:
\begin{enumerate}[label=(\alph*),leftmargin=2.2em]
\item (M0) $s_{jj}t_{ii}=t_{ii}s_{jj}$;
\item (M1) $s_{j+1,j}t_{ii}=q^{\alpha_j(i)}t_{ii}s_{j+1,j}$;
\item (M1$'$) $s_{jj}t_{i,i+1}=q^{+\alpha_i(j)}\,t_{i,i+1}s_{jj}$,
  i.e.\ equals $q^{-1}t_{i,i+1}s_{jj}$ for $j=i$, equals
  $q\,t_{i,i+1}s_{jj}$ for $j=i+1$, and equals $t_{i,i+1}s_{jj}$
  for $j\notin\{i,i+1\}$;
\item (M3)
  $s_{j+1,j}t_{i,i+1}=q^{\alpha_j(i+1)+\alpha_i(j+1)}\,
  t_{i,i+1}s_{j+1,j}$ for $j\ne i$; the exponent is $-1$ for
  $j=i-1$, $+1$ for $j=i+1$, $0$ otherwise;
\item (M2) $s_{i+1,i}t_{i,i+1}
  =t_{i,i+1}s_{i+1,i}
  +\tht\bigl(t_{i+1,i+1}\,(s_{ii}^{-1}s_{i+1,i+1})\,s_{i+1,i+1}
  -t_{i+1,i+1}\,(t_{ii}^{-1}t_{i+1,i+1})\,s_{i+1,i+1}\bigr)$.
\end{enumerate}
\end{theorem}
\begin{proof}
Throughout, the rear-reduction of a mixed word moves each grouplike
to the back past the root letters; by \eqref{H1pm},
Lemma~\ref{lem:cross}(a),(b),(c) and \eqref{aInv}, \eqref{bInv}, the
scalar contributed per crossing is: $\hK_j^{(\pm)}$ or
$\hK_j^{(\pm)-1}$ past $E_r$ contributes $q^{\pm\alpha_r(j)}$
(with $+$ for $\hK_j^{(+)}$ and for $\hK_j^{(-)-1}$, $-$ for
$\hK_j^{(+)-1}$ and for $\hK_j^{(-)}$), and past $F_s$ the scalar is
$q^{+\alpha_s(j)}$ for $\hK_j^{(+)-1}$ and for $\hK_j^{(-)-1}$, and
$q^{-\alpha_s(j)}$ for $\hK_j^{(+)}$ and for $\hK_j^{(-)}$;
opposite-Borel grouplikes
cross freely.

