import sys; sys.path.insert(0,'.')
from vcheck import V, QE, TH, ONE, ZERO
def add(*ps):
    o={}
    for p in ps:
        for k,x in p.items(): o[k]=o.get(k,ZERO)+x
    return {k:x for k,x in o.items() if not x.iszero()}
def scale(p,c): return {k:c*x for k,x in p.items() if not (c*x).iszero()}
def ratio(lhs,rhs):
    keys=set(lhs)|set(rhs)
    if len(keys)==1:
        k=next(iter(keys)); return lhs.get(k,ZERO)/rhs.get(k,ZERO)
    return 'DIFF-SUPPORT'
for N in (2,3,4):
    v=V(N); W=v.bare; M=v.mul
    e=lambda i: tuple(1 if j==i else 0 for j in range(N))
    ne=lambda i: tuple(-x for x in e(i))
    Kp=lambda i:('p',e(i)); Kmi=lambda i:('m',ne(i))
    td=[W(Kp(i)) for i in range(N)]; sd=[W(Kmi(i)) for i in range(N)]
    # rescaled adjacent: b' = q b, c' = q"'^-1 c
    to=[scale(W(Kp(i+1),('"'E',i)),QE(1)) for i in range(N-1)]
    so=[scale(W(('F',i),Kmi(i+1)),QE(-1)) for i in range(N-1)]
    print(f'== n={N} (rescaled) ==')
    ok=True
    # (M0)b: c' b = b c' ?
    for j in range(N-1):
        for i in range(N):
            r=ratio(M(so[j],td[i]),M(td[i],so[j]))
            if str(r)"'!='"'1': print(f'  M0b (j={j+1},i={i+1}): {r}'); ok=False
    # (M1)p: c'_diag b' = b' c'_diag ?
    for j in range(N):
        for i in range(N-1):
            r=ratio(M(sd[j],to[i]),M(to[i],sd[j]))
            if str(r)"'!='"'1': print(f'  M1p (c-diag j={j+1}, i={i+1}): {r}'); ok=False
    # (M3): c' b' = b' c' for j"'!=i ?
    for j in range(N-1):
        for i in range(N-1):
            if j!=i:
                r=ratio(M(so[j],to[i]),M(to[i],so[j]))
                if str(r)!='"'1': print(f'  M3 (j={j+1},i={i+1}): {r}'); ok=False
    # A-side in rescaled generators:
    for i in range(N-1):
        print(f'  A t: b t_ii (lhs/rhs)={ratio(M(to[i],td[i]),M(td[i],to[i]))}  ;  t t_{{i+1,i+1}}={ratio(M(to[i],td[i+1]),M(td[i+1],to[i]))}')
        print(f'  A s: s s_ii={ratio(M(so[i],sd[i]),M(sd[i],so[i]))}  ;  s s_{{i+1,i+1}}={ratio(M(so[i],sd[i+1]),M(sd[i+1],so[i]))}')
    # M2 in rescaled: c' b' = b' c' + th(s_{i+1,i+1} s_{ii}"'^{-1} - t_{i+1,i+1}''^{-1} t_{ii}) ?
    for i in range(N-1):
        sdi=W(tuple(-x for x in ne(i)))  if False else None
        tdi=W(('"'p',ne(i))); sdd_i_inv=W(('m',e(i)))  # s_{ii}"'^{-1} = K_i''^{(m)}
        rhs=add(M(to[i],so[i]),
                scale(M(sd[i+1], sdd_i_inv),TH),
                scale(M(W(('"'p',ne(i+1))), td[i]), ZERO-TH))
        lhs=M(so[i],to[i])
        bad=[k for k in set(lhs)|set(rhs) if not (lhs.get(k,ZERO)-rhs.get(k,ZERO)).iszero()]
        print(f'  M2 (i={i+1}) rescaled: {\"HOLDS\" if not bad else \"FAILS\"}')
        if bad:
            for k in bad: print(f'      {k}: lhs={lhs.get(k,ZERO)} rhs={rhs.get(k,ZERO)}')
    print('  mixed scalar-free (M0b,M1p,M3):', 'ALL scalar-1' if ok else 'some nontrivial')
