code = '''\"\"\"vrf3.py -- ROUND-3 PRINCIPLED two-letter-capable pairing/kernel engine.

Built fresh: co-op second (PA) line (<uv,z> = <u,z2><v,z1>) and straight first
line (<u,yz> = <u1,y><u2,z>), both directions iterated correctly to word
level (d2 channels over coproducts DELTA-iterated).  No bug: the multi-letter
first-argument recursion is CO-OP below; the single-letter first-argument
recursion against a multi-letter second argument iterates the first line
against the WHOLE word (not just the first letter) -- this is the single
technical difference from vrf.py/vrf2.py (whose letter-F path paired the
coproduct second slot against only the FIRST letter of the tail).
Consequently <F, E K"'^v> is UNCHANGED (T7/T9 world agrees with vrf/vrf2),
while everything is now definition-consistent on both directions.

Every cross value used by (SK) is verified here; in particular the contested
first channel of prop:EF, which is computed FOUR ways:
  (i)  <F, S''^{-1}(E)> directly with S''^{-1}(E) = -E cK''^{-1};
  (ii) <cK_s''^{-1} F_s, E_r cK_r''^{-1}> (the un-cancelled channel product);
  (iii) the full (SK) cross(E,F) channel enumeration;
  (iv) the same in the engineer-frame with grouplike tails separated.
"""
from fractions import Fraction as Fr
import sys
sys.path.insert(0, '"'/work/first-proof-humanize-tdgou2bu/002-prob-003/scratch')
from rat import RF

Dv = 12
def QE(x):
    x = Fr(x); e = Dv * x
    assert e.denominator == 1
    return RF.c(1, int(e))
TH = QE(0) / (QE(-1) - QE(1)); ZERO = RF.c(0); ONE = RF.c(1)
N_PASS = [0]; N_FAIL = [0]; FAILS = []
def chk(name, got, want):
    if (got - want).iszero(): N_PASS[0] += 1
    else:
        N_FAIL[0] += 1; FAILS.append(name); print('FAIL', name, 'got', got, 'want', want)

class Engine:
    def __init__(self, n):
        self.n = n; self._pc = {}
    def alpha(self, r):
        return tuple(-1 if i == r else (1 if i == r + 1 else 0) for i in range(self.n))
    def adot(self, u, v):
        return Fr(sum(u) * sum(v), self.n) - sum(a * b for a, b in zip(u, v))
    def aval(self, r, u): return -u[r] + u[r + 1]
    # letters: ('g', wt) grouplike; ('E', r, 'p'); ('F', s, 'm')
    def isG(self, w): return all(s[0] == 'g' for s in w)
    # ---- letter coproducts (C) ----
    def d1(self, s):
        if s[0] == 'g': return [(s, s)]
        if s[0] == 'E':
            return [(s, '1'), (('g', tuple(-x for x in self.alpha(s[1]))), s)]  # cK_r wt -a(r)
        return [(s, ('g', self.alpha(s[1]))), ('1', s)]                          # F: cK"'^-1 wt +a(s)
    def d2(self, word):
        # Delta''^2-style minors across a word: preserves letter order per slot
        chans = [((), ())]
        for s in word:
            new = []
            for (A, B) in chans:
                for a, b in self.d1(s):
                    A2 = A + (() if a == '"'1' else (a,))
                    B2 = B + (() if b == '1' else (b,))
                    new.append((A2, B2))
            chans = new
        return chans
    # ---- antipode inverse (S), word-level (anti-automorphism) ----
    def Sinv_word(self, w):
        out = [(ONE, ())]
        for lt in reversed(w):
            sc, wl = self.Sinv_letter(lt)
            out = [(a * sc, ww + wl) for (a, ww) in out]
        return out
    def Sinv_letter(self, s):
        if s[0] == 'g': return (ONE, (('g', tuple(-x for x in s[1])),))
        if s[0] == 'E': return (RF.c(-1), (s, ('g', self.alpha(s[1]))))       # -E cK"'^{-1}
        return (RF.c(-1), (('"'g', tuple(-x for x in self.alpha(s[1]))), s))    # -cK F
    # ---- the pairing: (PA) with CO-OP second line ----
    def pair(self, u, v):
        key = (u, v)
        if key not in self._pc: self._pc[key] = self._p(u, v)
        return self._pc[key]
    def _p(self, u, v):
        if not u: return ONE if self.isG(v) else ZERO
        if not v: return ONE if self.isG(u) else ZERO
        if self.isG(u) and self.isG(v):
            # total weights
            tu = [0] * self.n; tv = [0] * self.n
            for s in u: tu = [a2 + b2 for a2, b2 in zip(tu, s[1])]
            for s in v: tv = [a2 + b2 for a2, b2 in zip(tv, s[1])]
            t = self.adot(tu, tv); e12 = 12 * Fr(t); assert e12.denominator == 1
            return RF.c(1, int(e12))
        if len(u) > 1:
            # CO-OP second line iterated: <a rest, Y> = sum <a, Y_(2)> <rest, Y_(1)>
            a, rest = u[0], u[1:]
            out = ZERO
            for y1, y2 in self.d2(v):
                p1 = self.pair((a,), y2)
                if p1.iszero(): continue
                out += p1 * self.pair(rest, y1)
            return out
        a = u[0]
        if a[0] == 'g':
            return ZERO  # grouplike vs non-grouplike word: killed by charge (P)
        # FIRST line against the WHOLE word v: <x, Y> = sum <x_(1), Y_(1)> <x_(2), Y_(2)>
        out = ZERO
        for b1, b2 in self.d1(a):
            b1 = () if b1 == '1' else (b1,)
            b2 = () if b2 == '1' else (b2,)
            for y1, y2 in self.d2(v):
                p1 = self.pair(b1, y1)
                if p1.iszero(): continue
                out += p1 * self.pair(b2, y2)
        return out
    # ---- (SK): y x, y plus-word, x minus-word ----
    def cross(self, y, x):
        out = {}
        # x-channels: iterate d2 twice = 3-fold minors; implement by nested d2
        def d3(word):
            chans = [((), (), ())]
            for s in word:
                new = []
                for (X1, X2, X3) in chans:
                    for (a, bc) in self.d1(s):
                        pass
                # simpler: 3-slot via two-level split
            # -- build via recursive slot distribution
            slots = [((), (), ())]
            for s in word:
                new = []
                opts = [(s, '1', '1'), ('1', s, '1'), ('1', '1', s)]
                for (A, B, C) in slots:
                    for (o1, o2, o3) in self._three(s):
                        new.append((A + (() if o1 == '1' else (o1,)),
                                    B + (() if o2 == '1' else (o2,)),
                                    C + (() if o3 == '1' else (o3,))))
                slots = new
            return slots
        for (x1, x2, x3) in d3(x):
            for (y1, y2, y3) in d3(y):
                s1 = ZERO
                for (a2, wx) in self.Sinv_word(x1):
                    s1 += a2 * self.pair(wx, y1)
                if s1.iszero(): continue
                s3 = self.pair(x3, y3)
                if s3.iszero(): continue
                out[(x2, y2)] = out.get((x2, y2), ZERO) + s1 * s3
        return {k: v for k, v in out.items() if not v.iszero()}
    def _three(self, s):
        # three-fold coproduct minors of one letter via associativity:
        # Delta"'^2(s) = sum a | b | c with (Delta x id) Delta
        out = []
        for (a2, b2) in self.d1(s):
            if b2 == '"'1':
                out.append((a2, '1', '1') if a2 "'!= '"'1' else ('1', '1', '1'))
            else:
                for (b3, c3) in self.d1(b2):
                    out.append((a2 if a2 "'!= '"'1' else '1', b3, c3))
        # normalize '1'
        return out

def K(u): return (('g', u),)
def E(r): return (('E', r, 'p'),)
def F(s): return (('F', s, 'm'),)

def run(n):
    w = Engine(n)
    e = lambda i: tuple(1 if j == i else 0 for j in range(n))
    av = w.aval
    # ---- pairing table spot checks (printed co-op values) ----
    for r in range(n - 1):
        for u in (e(0), (1,) * n):
            chk(f'n{n} T2c <K"'^u F,E> = th'"', w.pair(K(u) + F(r), E(r)), TH)
            chk(f'n{n} T3c <F K"'^u,E> = th q''^+av'"', w.pair(F(r) + K(u), E(r)), TH * QE(+av(r, u)))
        for v in (e(0), (1,) * n):
            chk(f'n{n} T4c <F,K"'^v E> = th'"', w.pair(F(r), K(v) + E(r)), TH)
            chk(f'n{n} T5c <F,E K"'^v> = th q''^-av'"', w.pair(F(r), E(r) + K(v)), TH * QE(-av(r, v)))
        a = w.alpha(r); na = tuple(-x for x in a)
        chk(f'n{n} T6c <cK"'^-1 F,E> = th'"', w.pair(K(a) + F(r), E(r)), TH)
        chk(f'n{n} T7c <F,E cK> = th q"'^+2'"', w.pair(F(r), E(r) + K(na)), TH * QE(2))
        chk(f'n{n} T8c <F,E cK"'^-1> = th q''^-2'"', w.pair(F(r), E(r) + K(a)), TH * QE(-2))
        chk(f'n{n} T9c <cK"'^-1 F, E cK''^-1> = th q''^-2'"',
            w.pair(K(a) + F(r), E(r) + K(a)), TH * QE(-2))
    # ---- the contested channel: <F, S"'^{-1}(E)> ----
    for r in range(n - 1):
        tot = ZERO
        for (sc, wd) in w.Sinv_word(E(r)):
            tot += sc * w.pair(F(r), wd)
        chk(f'"'n{n} CH1 <F{r+1}, S"'^-1(E{r+1})> = -th q''^-2'"', tot, ZERO - TH * QE(-2))
    # ---- (SK): full EF cross ----
    for r in range(n - 1):
        for s in range(n - 1):
            d = w.cross(E(r), F(s))
            exp = {(F(s), E(r)): ONE}
            if r == s:
                a = w.alpha(r); na = tuple(-x for x in a)
                exp[((), K(na))] = TH
                exp[(K(a), ())] = ZERO - TH * QE(-2)
            keys = set(d) | set(exp)
            bad = ZERO
            for k in keys: bad += d.get(k, ZERO) - exp.get(k, ZERO)
            chk(f'n{n} SKEF ({r+1},{s+1}) = q"'^-2-shell'"', bad, ZERO)
    # ---- (SK): cross conjugations (round-3 lem:cross (a),(b),(c)) ----
    for r in range(n - 1):
        for i in range(n):
            d = w.cross(E(r), K(e(i)))
            chk(f'n{n} CRa E{r+1} Kh{i+1}(-)', d.get((K(e(i)), E(r)), ZERO), QE(-av(r, e(i))))
            d = w.cross(K(e(i)), F(r))
            chk(f'n{n} CRb Kh{i+1}(+) F{r+1}', d.get((F(r), K(e(i))), ZERO), QE(-av(r, e(i))))
    for i in range(n):
        for j in range(n):
            d1 = w.cross(K(e(i)), K(e(j)))
            ok = len(d1) == 1 and list(d1.values())[0] == ONE
            chk(f'n{n} CRc ({i+1},{j+1})', RF.c(1 if ok else 0), ONE)

if __name__ == '__main__':
    for n in (2, 3):
        run(n)
    print()
    print(f'{N_PASS[0]} PASS, {N_FAIL[0]} FAIL' + ('' if not FAILS else ': ' + str(FAILS[:25])))
'''
