class Engine:
    def __init__(self, n):
        self.n = n
        self._pcache = {}
    # --- lattice data ---
    def alpha(self, r):  # the alpha-VECTOR appearing in coproduct weights:
        # wt(cK_r) = e_r - e_{r+1} = -alpha-vec; alpha-vec(r) := -e_r + e_{r+1}
        # (coordinate tuple i=0..n-1: alpha_r(i) = -delta_{i,r} + delta_{i,r+1})
        return tuple(-1 if i == r else (1 if i == r + 1 else 0) for i in range(self.n))
    def adot(self, u, v):  # u . v under a_ij = 1/n - delta_ij
        return Fr(sum(u) * sum(v), self.n) - sum(a * b for a, b in zip(u, v))
    def aval(self, r, u):  # alpha_r(u) = sum_i alpha_r(i) u_i  (the -1/n part drops out)
        return -u[r] + u[r + 1]
    # --- letters and words ---
    def isG(self, w): return all(s[0] == 'g' for s in w)
    def totW(self, w):
        u = (0,) * self.n
        for s in w:
            if s[0] == 'g': u = tuple(a + b for a, b in zip(u, s[1]))
            else: u = tuple(a + b for a, b in zip(u, s[2]))
        return u
    # --- coproduct minors (C), letterwise; returns list of tensor-word pairs ---
    def d1(self, s):
        if s[0] == 'g': return [(s, s)]
        if s[0] == 'E':
            # Delta E_r = E|1 + cK_r|E, cK_r weight = -alpha(r) = e_r - e_{r+1}
            return [(s, '1'), (('g', tuple(-x for x in self.alpha(s[1]))), s)]
        # Delta F_s = F|cK_s^{-1} + 1|F, cK_s^{-1} weight = +alpha(s)
        return [(s, ('g', self.alpha(s[1]))), ('1', s)]
    def dslots(self, word, k):
        chans = [tuple(() for _ in range(k))]
        for s in word:
            new = []
            for ch in chans:
                # iterate over all k-fold minors of this letter by recursion
                for parts in self._kminor(s, k):
                    new.append(tuple(ch[j] + (() if parts[j] == '1' else (parts[j],))
                                     for j in range(k)))
            chans = new
        return chans
