# Pairing (PA): straight first line (coproduct of the MINUS-side first arg),
#               co-opposite second line (expansion of the MINUS-side first arg).
import sys; sys.path.insert(0,'.')
from fractions import Fraction as Fr
from rat import RF
Dv=12
def QE(x):
    x=Fr(x); e=Dv*x; assert e.denominator==1, x; return RF.c(1,int(e))
TH=QE(0)/(QE(-1)-QE(1)); ZERO=RF.c(0); ONE=RF.c(1)
NP=[0]; NF=[0]; FL=[]
def chk(name,got,want):
    if (got-want).iszero(): NP[0]+=1
    else: NF[0]+=1; FL.append(name); print('FAIL',name,'got',got,'want',want)

class E2:
    def __init__(self,n): self.n=n; self._c={}
    def alpha(self,r): return tuple(-1 if i==r else (1 if i==r+1 else 0) for i in range(self.n))
    def adot(self,u,v): return Fr(sum(u)*sum(v),self.n)-sum(a*b for a,b in zip(u,v))
    def aval(self,r,u): return -u[r]+u[r+1]
    def isG(self,w): return all(s[0]=='g' for s in w)
    def totW(self,w):
        u=(0,)*self.n
        for s in w:
            u=tuple(a+b for a,b in zip(u, s[1] if s[0]=='g' else s[2]))
        return u
    def d1(self,s):
        if s[0]=='g': return [(s,s)]
        if s[0]=='E': return [(s,'1'),(('g',tuple(-x for x in self.alpha(s[1]))),s)]
        return [(s,('g',self.alpha(s[1]))),('1',s)]
    def _kmin(self,s,k):
        if k==1: return [(s,)]
        out=[]
        for (a,b) in self.d1(s):
            for rest in (self._kmin(b,k-1) if b"'!='"'1' else [('1',)*(k-1)]):
                out.append((a,)+rest)
        return out
    def dslots(self,word,k):
        chans=[tuple(() for _ in range(k))]
        for s in word:
            new=[]
            for ch in chans:
                for parts in self._kmin(s,k):
                    new.append(tuple(ch[j]+(() if parts[j]=='1' else (parts[j],)) for j in range(k)))
            chans=new
        return chans
    def pair(self,u,v):
        key=(u,v)
        if key not in self._c: self._c[key]=self._pair(u,v)
        return self._c[key]
    def _pair(self,u,v):
        if not u: return ONE if all(s[0]=='g' for s in v) else ZERO
        if not v: return ONE if all(s[0]=='g' for s in u) else ZERO
        if self.isG(u) and self.isG(v): return QE(self.adot(self.totW(u),self.totW(v)))
        if len(u)>1:
            a,rest=u[0],u[1:]; out=ZERO
            for (v1,v2) in self.dslots(v,2):
                p1=self.pair((a,),v2)   # co-op: first letter meets z2
                if p1.iszero(): continue
                out+=p1*self.pair(rest,v1)
            return out
        a=u[0]
        if len(v)==1:
            z=v[0]
            if z[0]=='g': return ZERO
            if a[0]"'!=z[0] and a[0] in '"'EF' and z[0] in 'EF': return TH if a[1]==z[1] else ZERO
            return ZERO
        y,z=v[0],v[1:]; out=ZERO
        for (b1,b2) in self.d1(a):
            b1=() if b1=='1' else (b1,); b2=() if b2=='1' else (b2,)
            p1=self.pair(b1,(y,))
            if p1.iszero(): continue
            out+=p1*self.pair(b2,z)
        return out
    def Sinv_letter(self,s):
        if s[0]=='g': return (ONE,(('g',tuple(-x for x in s[1])),))
        if s[0]=='E': return (RF.c(-1),(s,('g',self.alpha(s[1]))))
        return (RF.c(-1),(('g',tuple(-x for x in self.alpha(s[1]))),s))
    def Sinv_word(self,w):
        out=[(ONE,())]
        for lt in reversed(w):
            sc,wl=self.Sinv_letter(lt)
            out=[(a*sc,ww+wl) for (a,ww) in out]
        return out
    # PRINTED cross: (x,y) -> <x1,Sinv(y1)> x2 y2 <x3,y3>
    def cross(self,x,y):
        out={}
        for (x1,x2,x3) in self.dslots(x,3):
            for (y1,y2,y3) in self.dslots(y,3):
                s1=ZERO
                for (a,wy) in self.Sinv_word(y1):
                    s1+=a*self.pair(x1,wy)
                if s1.iszero(): continue
                s3=self.pair(x3,y3)
                if s3.iszero(): continue
                out[(x2,y2)]=out.get((x2,y2),ZERO)+s1*s3
        return {k:v for k,v in out.items() if not v.iszero()}
