            d0=w.cross(F(s),E(r))
            dlt=ONE if r==s else ZERO
            exp={(F(s),E(r)):ONE,(Km,()):dlt*TH,((),Kpin):-dlt*TH}
            exp={k:v for k,v in exp.items() if not v.iszero()}
