import sys; sys.path.insert(0,'.')
from vtrue import Eng,QE,TH,ZERO,ONE
from rat import RF
# D-word engine: normalize a word of generators {Km_i(+/-),Kp_i(+/-),E,F} to
# grouplike-rear PBW order, using (H1) internal + lem:cross + corrected (EF').
# We only need the MONOMIAL relations, so track words symbolically with q-scalars.
# Represent element as dict: tuple(word)->RF, word letters in canonical order:
#   minus-grouplikes, F's, plus-grouplikes, E's   (grouplikes sorted among themselves trivially)
# Crossing rules needed (alpha-functionals):
#  internal B+: Kp_i E_r = q"'^{+a_r(i)} E_r Kp_i ; Kp_i F = q''^{-a} F Kp
#  internal B-: Km_i F_r = q''^{+a_r(i)} F_r Km_i ; Km_i E = q''^{-a} E Km   [internal H1 minus]
#  cross: (a) Km_i E_r = q''^{+a_r(i)} E_r Km_i ; (b) F_s Kp_i = q''^{+a_s(i)} Kp_i F_s
#         (c) Km Kp commute.
# (EF'"'): F_s E_r = E_r F_s + d th(cK_s"'^{(-)} - cK_r''^{(+)-1}); cK wt=alpha(letter).
class T:
    def __init__(s,n): s.n=n; s.e=lambda i:tuple(1 if j==i else 0 for j in range(n))
    def alpha(s,r): return tuple(-1 if j==r else (1 if j==r+1 else 0) for j in range(s.n))
    def aval(s,r,u): return -u[r]+u[r+1]
    # letter: ('"'Km',i),('Kp',i),('E',r),('F',r) with i 0-based; grouplikes have +1 power
    def cross_scalar(s,A,B):
        # scalar for moving A past B to get canonical order (A,B adjacent -> B,A)*scalar
        # canonical order: Km(-) < F < Kp(+) < E
        def rank(L): return {'Km':0,'F':1,'Kp':2,'E':3}[L[0]]
        if rank(A)<=rank(B): return None  # already ordered
        # A after B needed: compute scalar c with ...A B... = c ...B A...
        a,b=A,B
        # find rule for b a -> c a b ; we want a b = (1/c) b a ; but rules are for specific pairs.
        return s._rule(a,b)
    def _rule(s,a,b):
        # returns scalar c such that  a b  =  c * b a   (the crossing of a past b to the RIGHT)
        ta,tb=a[0],b[0]
        qe=QE
        if ta=='E' and tb=='Kp':  # E_r Kp_i = q"'^{-a_r(i)} Kp_i E_r
            return qe(-s.aval(a[1],s.e(b[1])))
        if ta=='"'Kp' and tb=='F':  # Kp_i F_s = q"'^{-a_s(i)} F_s Kp_i
            return qe(-s.aval(b[1],s.e(a[1])))
        if ta=='"'E' and tb=='Km':  # E_r Km_i = q"'^{-a_r(i)} Km_i E_r  (from Km E=q''^{+a} E Km)
            return qe(-s.aval(a[1],s.e(b[1])))
        if ta=='"'F' and tb=='Km':  # F_r Km_i = q"'^{-a_r(i)} Km_i F_r (from Km F=q''^{+a}F Km)
            return qe(-s.aval(a[1],s.e(b[1])))
        if ta=='"'Kp' and tb=='Km': return ONE   # commute
        if ta=='F' and tb=='Kp':  # F_s Kp_i = q"'^{+a_s(i)} Kp_i F_s
            return qe(s.aval(a[1],s.e(b[1])))
        raise Exception('"'no rule %s %s'%(a,b))
    def canon(s, elem):
        # bubble-sort grouplikes-rear; returns dict tuple->RF (no EF swapping here)
        out={}
        for w,c in elem.items():
            w=list(w); co=c; ch=True
            while ch:
                ch=False
                for i in range(len(w)-1):
                    A,B=w[i],w[i+1]
                    def rank(L): return {'Km':0,'F':1,'Kp':2,'E':3}[L[0]]
                    if rank(A)>rank(B):
                        sc=s.cross_scalar(A,B); co=co*sc; w[i],w[i+1]=B,A; ch=True
            out.setdefault(tuple(w),ZERO); out[tuple(w)]+=co
        return {k:v for k,v in out.items() if not v.iszero()}
    def mul(s,e1,e2):
        out={}
        for w1,c1 in e1.items():
            for w2,c2 in e2.items():
                out.setdefault(w1+w2,ZERO); out[w1+w2]+=c1*c2
        return s.canon(out)
    def E(s,r): return { (('E',r),):ONE }
    def F(s,r): return { (('F',r),):ONE }
    def Kp(s,i,p=1): return { (('Kp',i,p),):ONE }
    def Km(s,i,p=1): return { (('Km',i,p),):ONE }

W=T(3)
# arc images (D1a):  t_ii=Kp_i ; t_{i,i+1}=q"'^-1 Kp_{i+1} E_i ; s_ii=Km_i''^-1 ; s_{i+1,i}=F_i Km_{i+1}''^-1
def t_adj(W,i):   # t_{i,i+1} = q''^-1 Kp_{i+1} E_i
    e=W.mul(W.Kp(i+1),W.E(i)); return {k:v*QE(-1) for k,v in e.items()}
def s_adj(W,i):
    return W.mul(W.F(i),W.Km(i+1,-1))
def t_d(W,i): return W.Kp(i)
def s_d(W,i): return W.Km(i,-1)
# check t_{i,i+1} t_{jj} vs t_{jj} t_{i,i+1}
for i in (0,1):
    A=t_adj(W,i)
    for j in (0,1,2):
        L=W.mul(A,t_d(W,j)); R=W.mul(t_d(W,j),A)
        # find scalar: L should be s * R (single monomial each)
        lk=list(L.items()); rk=list(R.items())
        if len(lk)==1 and len(rk)==1 and lk[0][0]==rk[0][0]:
            print(f'"'t_{{{i+1},{i+2}}} t_{{{j+1},{j+1}}} = (coef {lk[0][1]}) * mono ; t_{{jj}} t = (coef {rk[0][1]}); ratio L/R = {lk[0][1]/rk[0][1]}')
        else:
            print(f'i{i} j{j}: L={lk} R={rk}')
