            keys=set(lhs)|set(rhs); bad={k:(lhs.get(k,ZERO)-rhs.get(k,ZERO)) for k in keys}
            bad={k:v for k,v in bad.items() if not v.iszero()}
            chk(f'n{n} gen u={uwt} r{r+1}s{s+1}', RF.c(0 if bad else 1), ONE)
